INSERT INTO `berita` (`id_berita`, `iduser`, `id_kategori`, `id_user`, `judul`, `isi_berita`, `gambar`, `tgl_posting`, `plan`, `updated_at`, `deleted_at`, `status`, `approved_by`, `approved_at`) VALUES
(1, 0, 1, 13, 'EARTHWORK 1 DESEMBER 2025 SHIFT SIANG', 'KEGIATAN:\r\nKegiatan diawali dengan penyampaian K3 saat briefing untuk memastikan seluruh pekerja memahami potensi bahaya, prosedur kerja aman, serta pembagian tugas pada masing-masing area kerja. Setelah briefing, pekerjaan dilanjutkan sesuai rencana harian di dua area utama, yaitu Line 1 Utara dan Line 2 Selatan.\r\n\r\nPada Line 1 Utara, tim melakukan beberapa aktivitas penting, yaitu trimming bawah Megatower di 2 titik, kemudian pekerjaan trimming di area Comp. AP23, serta pekerjaan dozing pada titik jatuhan material yang mengarah ke sisi timur. Seluruh pekerjaan dilakukan dengan menjaga kemiringan dan kestabilan kontur area kerja.\r\n\r\nSementara itu, pada Line 2 Selatan, kegiatan yang dilakukan meliputi trimming di area BP89 pada 2 titik, yaitu di elevasi 60 bagian tengah dan pada area Batress CP89. Selain itu, dilakukan pula pekerjaan trimming pada Tugu Batu sebanyak 1 titik, untuk merapikan permukaan dan memastikan area tetap aman serta sesuai rencana kontur yang ditetapkan.\r\n\r\nTEMUAN:\r\nSelama kegiatan berlangsung, terdapat beberapa temuan penting yang perlu menjadi perhatian. Pertama, kondisi hujan pada pertengahan shift menyebabkan penurunan visibilitas serta potensi bahaya licin pada area kerja. Situasi ini berdampak pada perlambatan aktivitas dan memerlukan peningkatan kewaspadaan seluruh tim.\r\n\r\nSelain itu, akses BP89 menuju area utara pada elevasi tertentu harus di-hold (dihentikan sementara) karena kondisi jalan dinilai tidak aman untuk dilalui. Keputusan ini diambil untuk mencegah risiko kecelakaan serta memastikan keselamatan personel dan alat yang beroperasi.\r\n\r\nMANPOWER:\r\n1.Driver DT:24 orang\r\n2.Driver LT:3 orang\r\n3.Operator Buldozer:16\r\n4.Operator Exavator.14\r\n5.Operator Compactor:3\r\n6.Cheker:8\r\n7.Pengawasan:5\r\n-Ramli T\r\n-A rahman\r\n-Stewani T\r\n-Abdu M hamid\r\n-Theodorus S\r\n8.SPV : Ardyles Teken', '1765341660_WhatsApp Image 2025-11-20 at 17.10.17.jpeg', '2025-12-01 02:31:53', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(2, 0, 1, 14, 'EARTHWORK 1 DESEMBER 2025 SHIFT MALAM', 'KEGIATAN:\r\nPada area Line 1 Utara, kegiatan difokuskan pada pekerjaan hauling dan trimming. Tim melakukan trimming di Comp A sisi timur dan Comp B sisi timur, serta melanjutkan trimming pada dua titik di bawah Megatower. Seluruh aktivitas dilakukan untuk memastikan kontur area tetap aman dan sesuai rencana elevasi.\r\n\r\nDi Line 2 Selatan, pekerjaan juga meliputi hauling dan trimming. Tim melakukan trimming di Buttress B89, Buttress C89, serta pada titik elevasi +60, guna merapikan area kerja dan mempertahankan stabilitas lereng.\r\n\r\nSelain pekerjaan utama tersebut, tim turut membantu kelanjutan pekerjaan Buttress B89 serta meratakan material batu yang semalam masih berada pada area dampingan bebas. Kegiatan ini bertujuan untuk memastikan area siap digunakan dan tidak menghambat mobilisasi alat.\r\n\r\nTim juga melakukan pekerjaan laminating pada jalan opritan menuju buttress apabila ditemukan batu yang dapat mengganggu akses alat. Langkah ini penting untuk menjaga kualitas dan keamanan jalur operasional.\r\n\r\nTerakhir, dilakukan maintenance jalan hauling pada Line 1 dan Line 2 untuk memastikan kondisi jalan tetap layak, aman, dan mendukung kelancaran aktivitas hauling di kedua area tersebut.\r\n\r\nTEMUAN:\r\nPada awal shift, tercatat bahwa cuaca malam sebelumnya mengalami hujan deras, sehingga beberapa area kerja menjadi licin dan memerlukan kewaspadaan ekstra dalam mobilisasi alat maupun personel.\r\n\r\nSelain itu, alat LT 12 dan LT 27 masih dalam kondisi breakdown, sehingga belum dapat dioperasikan dan membutuhkan tindak lanjut dari tim maintenance untuk memastikan kelayakan operasional pada shift berikutnya.\r\n\r\nMANPOWER:\r\n1.Op Exsa 11\r\n2.Op Doser 12\r\n3.Op Dt 21\r\n4.Op Compakc 3\r\n5.Cheker 7\r\n6.Lv 1 \r\nForman 4 :\r\n-Elpin H S\r\n-Budi Setiawan\r\n-Safaat Umar\r\n-Ramli Tajuddin', '1765342813_WhatsApp Image 2025-12-01 at 19.58.38.jpeg', '2025-11-30 19:00:13', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(3, 0, 1, 13, 'EARTHWORK 02 DESEMBER 2025 SHIFT SIANG', 'KEGIATAN:\r\nKegiatan dimulai dengan penyampaian K3 saat briefing, yang menekankan pentingnya keselamatan kerja, kewaspadaan terhadap kondisi lapangan, serta pembagian tugas untuk masing-masing area operasi.\r\n\r\nPada Line 1 Utara, aktivitas terfokus pada full hauling menuju beberapa titik tujuan, yaitu Megatower, A23 Timur, serta tambahan emergency ke BP23 Timur apabila terjadi kondisi crowded di area loading. Tim juga melakukan pekerjaan dozing ke arah selatan pada titik jatuhan material bagian dalam untuk menjaga alur material tetap lancar dan aman.\r\n\r\nSementara itu, pada Line 2 Selatan, kegiatan berjalan dengan full hauling menuju tiga area utama, yaitu Buttress CP89, Buttress BP89, dan Elevasi 60 sisi tengah. Hauling dilakukan secara bertahap sesuai arahan planner dan prioritas kebutuhan lapangan.\r\n\r\nJUMLAH MANPOWER:\r\n1.Driver DT = 25 Orang\r\n2.Driver LT/LV = 1 Orang\r\n3.Operator Exca =17 Orang\r\n4.Operator Bulldozer = 12 Orang\r\n5.Operator Compactor = 4 Orang\r\n6.Checker = 9 Orang\r\n7.Foreman = 5 Orang\r\n-.Stewani T\r\n-.Abdu M hamid\r\n-.Theodorus S\r\n-.Septiawan Dwi\r\n-.A rahman \r\n8.SPV = 1: Ardyles Teken\r\n', '1765343373_WhatsApp Image 2025-12-02 at 08.17.23.jpeg', '2025-12-01 21:09:33', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(4, 0, 1, 14, 'PEKERJAAN EARTHWORK 02 DESEMBER 2025 SHIFT MALAM', 'KEGIATAN:\r\n\r\n1.Line 1 Utara houling dan Triming\r\n  Trimingan d komp A timur\r\n  Trimingan d komp B timur\r\n  2 Trimingan d bawa mega tower\r\n2.Line 2 selatan houling dan Triming\r\n   Trimingan d Buttras B89\r\n   Trimingan d Buttras C89\r\n   Trimingan d +60\r\n3.Bantu lanjut buttras B89 dan bantu ratakan batu yg semalam kita damping bebas\r\n4.Bantu Laminating jalan opritan k   menbuttras klu ada batu\r\n5.Mentenens Jalan houling line1&2\r\n\r\nTEMUAN:\r\n\"Cuaca tadi malam Hujan kencang\r\nLt 12&27 masi break down\"\r\n\r\nKETERANGAN:\r\nSelari tengki masi tinggi line 1&2 tidak ada kancing pagi ini\r\n\r\n\r\nMANPOWER:\r\nDriver DT 21 orang\r\nOp Excavator 11 orang\r\nOp Doser 12 orang\r\nOp Compact 3orang\r\nCheker 7\r\nLv 1 \r\nForman 4 :\r\n-.Elpin H S\r\n-.Budi Setiawan\r\n-.Safaat Umar\r\n-.Ramli Tajuddin', '1765409206_4f8dc2dd-7ef3-476b-84e9-2b777dfa8422.jpeg', '2025-12-01 19:26:46', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(5, 0, 1, 13, 'LAPORAN KEGIATAN EARTHWORK 03 DESEMBER 2025 SHIFT SIANG', 'KEGIATAN:\r\n\r\n1. Penyampaian K3 dan Kondisi Lapangan Pasca Hujan\r\nDilakukan briefing K3 sebelum kegiatan dimulai, dengan penekanan pada potensi bahaya akibat kondisi lapangan yang licin setelah hujan. Seluruh operator dan kru diingatkan untuk meningkatkan kewaspadaan, terutama pada area dengan permukaan tidak stabil.\r\n\r\n2. Kegiatan di Line 1 â€“ Full Hauling\r\nKegiatan hauling di Line 1 berjalan penuh dengan fokus pada beberapa area utama, yaitu Megatower, Comp. AP23 Timur, serta Comp. B yang dipersiapkan sebagai area emergency apabila kondisi di bawah Megatower tidak lagi aman untuk spreading. Selain itu, aktivitas dozing diarahkan ke bagian selatan sesuai dengan titik jatuh material.\r\n\r\n3. Kegiatan di Line 2 Selatan â€“ Full Hauling\r\nHauling di Line 2 Selatan juga berlangsung penuh, termasuk triminÂ­gan di area B bagian barat P89 dan pengerjaan di dua titik Tugu Batu. Area CP89 menjadi opsional dan dikerjakan sesuai kondisi lapangan serta evaluasi keselamatan saat kegiatan berlangsung.\r\n\r\nTEMUAN:\r\nâ€¢Hujan Mulai pukul 12.30-akhir shift\r\nâ€¢Jalan Hauling 60 tidak aman harap di Hold\r\n\r\nMANPOWER:\r\n\r\n1. Driver DT = 23\r\n2. Driver LT/LV = 1\r\n3. Operator Exca = 21\r\n4. Operator Bulldozer = 16\r\n5. Operator Compactor = 5\r\n6. Checker = 9\r\n7. Foreman = 5\r\n-.A rahman\r\n-.Deni N\r\n-.Theodorus\r\n-.Stewani T\r\n-.Septiawan Dwi\r\n8. SPV : Ardyles Teken', '1765410058_WhatsApp Image 2025-12-03 at 08.18.05.jpeg', '2025-12-02 15:40:58', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(6, 0, 1, 14, 'EARTHWORK 3 DESEMBER 2025 SHIFT MALAM', 'JOB PENDINNG:\r\n1. Line 1 Selatan Houling & Triming\r\n   Trimingan d Komp B timur\r\n   Trimingan d Komp A timur klu ada lebih      yunit bantu CutðŸ™\r\n  Trimingan Bawa mega tower\r\n2.Line 2 Selatan Full Houling\r\n   Trimingan d B89\r\n   Trimingan d C89\r\n   Trimingan d Tugu batu\r\n3.Batu B89\r\n4.Lanjut laminating jalan opritan ke menbattras \r\n\r\nKETERANGAN:\r\nTinggi Tengki line 1 ^ 2-3 meter\r\nTinggi Tengki line 2 ^ 3-4 meter\r\n\r\nMANPOWER:\r\n1.Driver DT : 22\r\n2.Opr Exca : 11\r\n3.Opr Dozer : 13\r\n4.Opr Compec : 1\r\n5.Driver LT/LV : 1\r\n6.Cheker  : 7\r\n7.Foreman : 4\r\n-.Elpin H S \r\n-.Abdu M Hamid\r\n-.Safaat Umar\r\n-.Ramli Tajuddin\r\n  ', '1765420710_WhatsApp Image 2025-12-03 at 20.49.40.jpeg', '2025-12-02 18:38:30', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(7, 0, 1, 13, 'KEGIATAN EARTHWORK 04 DESEMBER 2025 SHIFT SIANG', '<p><strong>KEGIATAN</strong>:</p>\r\n\r\n<p style=\"text-align:justify\">1.Briefing Penyampaian K3 Kegiatan diawali dengan briefing K3 yang menekankan pentingnya keselamatan kerja, termasuk pemeriksaan kondisi alat, jarak aman antar unit, serta kewaspadaan terhadap area yang memiliki potensi bahaya. Seluruh kru diimbau mematuhi prosedur dan memastikan komunikasi tetap efektif selama operasi berlangsung. 2.Kegiatan di Line 1 Utara &ndash; Full Hauling Aktivitas hauling di Line 1 Utara berjalan penuh dengan pembagian titik sebagai berikut: -Megatower: 1 titik -A Timur:</p>\r\n\r\n<p>2 titik -Comp. BP23 Timur: 1 titik Setelah hauling, titik jatuh diarahkan ke area dalam, dan pekerjaan continue full dozing dilakukan untuk menurunkan elevasi lipatan ex-a sesuai design, dengan arah pembuangan ke bagian selatan. Selain itu, dilakukan juga cut tailing Megatower ke arah WS baru untuk memastikan aliran material lebih teratur dan mendukung stabilitas area.</p>\r\n\r\n<p>3.Kegiatan di Line 2 Selatan &ndash; Full Hauling Hauling di Line 2 Selatan berlangsung dengan titik kerja: -Batress BP89 ke arah timur CP89 (1 titik) -Batress CP89 ke arah Comp. CP89 (1 titik) -Tugubatu (1 titik) 4.Maintenance Jalan Hauling ke Elevasi 60 Dilakukan pemeliharaan dan perbaikan jalan hauling menuju elevasi 60 untuk memastikan jalur tetap aman dan layak dilalui unit, terutama untuk mengantisipasi kondisi licin dan potensi kerusakan akibat cuaca.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>MANPOWER</strong>:</p>\r\n\r\n<p>1.Operator Buldozer:14</p>\r\n\r\n<p>2.Operator Exavator:16+4 Orientasi</p>\r\n\r\n<p>3.Operatoe Compactor:4</p>\r\n\r\n<p>4.Driver DT:24</p>\r\n\r\n<p>5.Driver LT/LV:2</p>\r\n\r\n<p>6.Motor greader:_</p>\r\n\r\n<p>7.WT:_</p>\r\n\r\n<p>8.Cheker:10</p>\r\n\r\n<p>9.Pengawas:4 -.Stewani T -.Septiawan Dwi -.Budi -.A rahman</p>\r\n\r\n<p>10.Spv: Ardyles Teken</p>\r\n', '1765421100_WhatsApp Image 2025-12-04 at 08.49.58.jpeg', '2025-12-30 06:27:58', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(17, 0, 2, 20, 'Geotek,29/12/2025', 'Untuk Pekerjaan Divisi Geotek hari ini melakukan,Pengujian LAB,Monitoring Area,Perbaikan Portal poin view,Monitoring penurunan elevasi 70.,adapun pengujian di lapangan meliputi pengujian Sand cone.semua pekerjaan di atas dikerjakan sesuai target yang di inginkan.untuk temuan hari ini,ada batu yang menggantung di elevasi 100.dari tim geotek akan melakukan pengawasan dan asessment.', '1767000800_WhatsApp Image 2025-12-29 at 12.07.25.jpeg', '2025-12-29 01:33:20', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(18, 0, 2, 20, 'Geotek,29/12/2025', 'Untuk Pekerjaan Divisi Geotek Malam Hari, Monitoring line 1 dan 2 , Pengambilan sampel fp line 1 dan 2 dan progress fp line 1 dan 2 ', '1767042739_WhatsApp Image 2025-12-29 at 21.13.05.jpeg', '2025-12-29 13:12:19', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(19, 0, 1, 16, 'BA EARTHWORK SHIFT SIANG', '<p><strong>JOB PENDING:</strong></p>\r\n\r\n<p>1. Line 1 selatan full dozing ke Utara dan Selatan</p>\r\n\r\n<p>2. Line 2 selatan full Hauling - triming di +60,B,C dan tugu batu ( argent )</p>\r\n\r\n<p>3. Batu line 1 selatan kontruksi pelebaran buttres bP89 atau maintenance jalan line 2 4.Cut +70 ( kalau main power cukup )</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>JUMLAH MANPOWER</strong>:</p>\r\n\r\n<p>Dt 19 orang</p>\r\n\r\n<p>Exc 17 orang</p>\r\n\r\n<p>Dozer 9 orang</p>\r\n\r\n<p>Compact 4 orang</p>\r\n\r\n<p>Lt/Lv 2 orang</p>\r\n\r\n<p>Ceker 7 orang&nbsp;</p>\r\n\r\n<p>Foreman 5 orang</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>FOREMAN:</p>\r\n\r\n<p>1.Abdu m hamid</p>\r\n\r\n<p>2.m safaat umar</p>\r\n\r\n<p>3.Irfandi ode</p>\r\n\r\n<p>4.Abdul Rahman</p>\r\n\r\n<p>5.Elpin hadi</p>\r\n\r\n<p>6.Septiawan dwi</p>\r\n', '1767056796_WhatsApp Image 2025-12-29 at 09.58.38.jpeg', '2025-12-30 06:25:25', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(20, 0, 1, 28, 'EARTHWORK SHIFT MALAM  29/12/2025', '<p><em><strong>JOB PENDDING:</strong></em></p>\r\n\r\n<p>1.line 1 selata. Full dosing dan arah dosingan ke utara dan arah MSP</p>\r\n\r\n<p>2.line 2 full hauljng dumpingan di komp B,Dan D P89</p>\r\n\r\n<p>3.kontruksi jalan +70 4.perbaikan jalan hauling di line 2</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><em><strong>JML MANPOWER HARI INI</strong>:</em></p>\r\n\r\n<p>Driver DT : 18 Opr</p>\r\n\r\n<p>Exca : 14 Opr</p>\r\n\r\n<p>Dozer : 13 Opr</p>\r\n\r\n<p>Compec : 4 Driver</p>\r\n\r\n<p>LT/LV : 2</p>\r\n\r\n<p>Cheker : 5</p>\r\n\r\n<p>Foreman : 3</p>\r\n\r\n<p>Spv 1</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><em><strong>FOREMAN</strong></em>: Deni nugraha, Theodorus s, Budi setiawan</p>\r\n', '1767057145_WhatsApp Image 2025-12-29 at 21.23.56.jpeg', '2025-12-30 06:04:35', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(24, 0, 1, 16, 'EARTHWORH SHIFT SIANG 30/12/2025', '<p><strong>JOB PENDING:</strong></p>\r\n\r\n<ol>\r\n	<li>line 1 selatan full dozing ke arah Utara dan Selatan</li>\r\n	<li>Line 2 selatan Hauling dan triming di +60,B, C dan tugu</li>\r\n	<li>batu batu Senggigi kontruksi buttres bP89 batu sedang maintenance akses jalan loding line 2</li>\r\n	<li>Cut jalan 70</li>\r\n</ol>\r\n\r\n<p><strong>JUMLAH MANPOWER:</strong><br />\r\nDt 21 orang Exc 15 orang Dozer 10 orang Compac 4 orang Lt / Lv 2 orang Ceker 12 orang Foreman 4 orang<br />\r\n<br />\r\n<em><strong>FOREMAN:</strong></em><br />\r\nelpin hadi abdu m hamid Abdul Rahman septiawan dwi</p>\r\n', '1767087647_WhatsApp Image 2025-12-30 at 08.42.02.jpeg', '2025-12-30 01:40:47', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(25, 0, 2, 26, 'BA Overshift Geotech Shift Siang', '<p>Daily Job Geotech hari ini dimulai dari&nbsp;<br />\r\n*). Instrument dan Monitoring:<br />\r\n1.&nbsp;Pembacaan Extensometer Line 1 Selatan_<br />\r\n- Tanggal: Sabtu, 30 Desember 2025<br />\r\n- Jam: 08:28 WIT<br />\r\n- Lokasi: Titik Jatuh Line 1 Selatan<br />\r\n- Operator: M Inding &amp; Wahid M Tais&nbsp;<br />\r\n- Hasil Pembacaan:<br />\r\n&nbsp; &nbsp; - Nilai: 71,2 mm<br />\r\n&nbsp; &nbsp; - Suhu: 24&deg;C<br />\r\n&nbsp; &nbsp; - Kondisi lingkungan: Cerah<br />\r\n- Kondisi Alat: Semua aman (sling, tripod, patok/angkur semua terpasang )<br />\r\n- Kondisi Tanah: Stabil, tidak ada tanda-tanda pergeseran atau longsor di area tripod.<br />\r\n2. Selanjutnya ada temuan retakan memanjang di tengah area spreadingan, di karenakan material dozingan Line I selatan yang langsung pelandaian ke arah timur namun masih terlalu tegak &amp; pembebanan dari atas, sehingga timbunan baru mengalami pergerakan di bagian kakimulai dari bawah ujung ekstensometer - bench baru sisi utara. Rekomendasi perbaikan dilakukan dengan&nbsp;membuat dorongan ke arah timur di line merah, nantinya di line oren akan melakukan dorongan langsung ke utara dan selatan, tujuannya adalah agar membentuk kaki, baru lanjut pembuatan bench di line biru.&nbsp;<br />\r\n3. Pengujian Sandcone dilakukan sebanyak 10 titik di Comp. C P89 untuk&nbsp;quality control kepadatan timbunan baru.<br />\r\n4. Pengujian CBR tidak jadi dilakukan karena cuaca hujan.<br />\r\nDilakukan sebanyak&nbsp;<br />\r\n*). Pengujian Lab<br />\r\nPengujian moisture content dan <strong>b</strong>ulk density dry tailing hasil filter press dilaksanakan sebagai bagian dari kegiatan quality control untuk memastikan kualitas dan tingkat kepadatan material sesuai dengan kriteria operasional. Sampel dry tailing diambil dari outlet filter press dan diuji kadar airnya menggunakan metode pengeringan di oven, sedangkan bulk density ditentukan berdasarkan perbandingan berat material terhadap volume cetakan sampel. Hasil pengujian menunjukkan bahwa nilai moisture content dan bulk density yang diperoleh merepresentasikan kondisi kekeringan dan kepadatan dry tailing pada hari pengujian, sehingga dapat digunakan sebagai acuan dalam evaluasi kinerja filter press serta kesiapan material untuk proses penanganan, penimbunan, dan pemadatan lanjutan di area DSTF.</p>\r\n', '1767087678_WhatsApp Image 2025-12-30 at 09.03.43.jpeg', '2025-12-30 09:47:35', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(26, 0, 6, 11, 'Daily Job Hidro ', '<p>1. Maintenance Sedimend Pond&nbsp;<br />\r\nPemindahan material lumpur dari kolam 2 ke sisi barat untuk dimasukan ke drying bed dilanjutkan dengan perapian material di drying bed yang kering di sisi selatan<br />\r\n# Masih continue untuk kolam 3</p>\r\n\r\n<p>2. Konstruksi saluran diatas main buttres selatan&nbsp;<br />\r\nKonstruksi saluran pada area outlet pipa ke arah sump pada compartmend D P89&nbsp;<br />\r\n# Continue pada jalur turunan kearah sump D P89</p>\r\n\r\n<p>3. Monitoring&nbsp;<br />\r\n* Pengukuran debit curah hujan manual 30 - 12 - 2025&nbsp; sebesar 0 mL<br />\r\n* Pengukuran debit manual 0,068 m3/s<br />\r\n* Pengukuran GW 7 manual sebesar 36,92 m&nbsp;</p>\r\n\r\n<p>Area&nbsp;<br />\r\n&nbsp;</p>\r\n\r\n<p>* Box kontrol comp A P23 dan A0 banyak lumpur Harus di maintenance&nbsp;</p>\r\n\r\n<p>* Finger drain comp B P89 tertutup lumpur akibat aktivitas unit sehingga perlu maintenance</p>\r\n\r\n<p>* Finger drain jalan 90 dekat titik jatuh line 1 banyak lumpur dan tertutup batu batu&nbsp;</p>\r\n', '1767088489_WhatsApp Image 2025-12-30 at 16.50.16.jpeg', '2025-12-30 01:54:49', 'Hydrology & Hydrogeology', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(27, 0, 2, 20, 'Geotek,30/12/2025', '<p>Untuk Pekerjaan Divisi Geotek Malam Hari, Monitoring line 1 dan 2 , Suport Tim Operaion di Elevasi 60 dan Buttress C P89,Pengambilan sampel fp line 1 dan 2 dan progress fp line 1 dan 2</p>\r\n', '1767125674_WhatsApp Image 2025-12-30 at 21.53.17.jpeg', '2025-12-30 12:14:34', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(28, 0, 7, 19, 'Daily Job WWTP', '<ul>\r\n	<li style=\"text-align: justify;\">proses pengolahan lindi start jam 8.00 sampai dengan jam 16.20, karena aerator B trouble dan influent dari 2 ponton sudah lumpur</li>\r\n	<li style=\"text-align: justify;\">analisa laboratorium (Cr6+, Fe, NH3, NO2, NO3)</li>\r\n	<li style=\"text-align: justify;\">â sampling dan monitoring area toba 1</li>\r\n	<li style=\"text-align: justify;\">sampling genangan air komp. D P89 dan air limpasan dari akses jalan trimingan komp. D P89 ke toedrain</li>\r\n	<li style=\"text-align: justify;\">pengantaran sampel daily tanggal 27, 28, 29 ke lab enviro</li>\r\n	<li style=\"text-align: justify;\">sampel CP1, CP2, dan Outlet tanggal 27 request pengujian semua parameter logam berat ICP</li>\r\n	<li style=\"text-align: justify;\">â IM geotube 10pcs 7,2x18 meter full approved</li>\r\n	<li style=\"text-align: justify;\">â perbaikan pompa dosing FeSO4 A dan PAM B oleh tim equipment</li>\r\n	<li style=\"text-align: justify;\">perbaikan aerator B yang bocor, setelah di on kan aerator tidak nyala mesinnya. Dari mekanik eqp menyarankan hub tim EID kemungkinan di elektrikal nya. lampu indikator di panel on, mcb aman</li>\r\n	<li style=\"text-align: justify;\">â dossing PDMC kolam 1 pengolah lindi</li>\r\n	<li style=\"text-align: justify;\">dossing flokulan di toedrain</li>\r\n	<li style=\"text-align: justify;\">monthly report sudah selesai, kurang data monitoring per hari ini (tgl 30)</li>\r\n	<li style=\"text-align: justify;\">cat handrail bak penampung</li>\r\n	<li style=\"text-align: justify;\">penyikatan tanggul 3,4,5 kolam pengolah lindi sisi barat</li>\r\n	<li style=\"text-align: justify;\">FU larutan kalibrasi TDS untuk horiba, masih dicek oleh tim teknologi</li>\r\n	<li style=\"text-align: justify;\">cek stok&nbsp;bahan&nbsp;kimia&nbsp;lab</li>\r\n</ul>\r\n', '1767133416_Sampling Inlet 16-12-2025.jpg', '2025-12-30 14:23:36', 'Waste Water Treatment Plant', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(29, 0, 1, 28, 'EARTHWORH SHIFT MALAM 30/12/2025', '<p><strong>JOB PENDING:</strong></p>\r\n\r\n<ol>\r\n	<li>line 1 selatan full dosing arah dosingan ke utara dan arah MSP&nbsp;</li>\r\n	<li>line 2 full hauling dumping di komp B,C dan D P89&nbsp;</li>\r\n	<li>kontruksi jalan+70&nbsp;</li>\r\n	<li>kontruksi butress B P89&nbsp;</li>\r\n	<li>Perbaikan jalan hauling all area</li>\r\n</ol>\r\n\r\n<p><strong>KENDALA:</strong><br />\r\nKondisi jalan trimingan Butttres B P89 Pasca Hujan (shift siang)&nbsp; mudah amblas masih perlu dimaintenance&nbsp;</p>\r\n\r\n<p><strong>JUMLAH MANPOWER:</strong></p>\r\n\r\n<ol>\r\n	<li>Driver DT : 19</li>\r\n	<li>Opr Exca : 15</li>\r\n	<li>Opr Dozer : 13</li>\r\n	<li>Opr Compec : 3</li>\r\n	<li>Driver LT/LV : 2</li>\r\n	<li>Cheker : 4</li>\r\n	<li>Foreman : 4</li>\r\n	<li>Spv 1</li>\r\n</ol>\r\n\r\n<p>FOREMAN:</p>\r\n\r\n<ul>\r\n	<li>Deni N</li>\r\n	<li>Budi S</li>\r\n	<li>Safaat Umar</li>\r\n	<li>Irfamdi Ode</li>\r\n</ul>\r\n', '1767137506_WhatsApp Image 2025-12-30 at 20.16.19.jpeg', '2025-12-31 09:21:53', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(30, 0, 1, 16, 'EARTHWORH SHIFT SIANG 31/12/2025', '<p><strong>Job Pendding:</strong></p>\r\n\r\n<ol>\r\n	<li>Line 1 selatan full dozing kearah Utara dan Selatan</li>\r\n	<li>Line 2 selatan Hauling dan triming di 60,B, C dan tugu batu</li>\r\n	<li>batu Senggigi kontruksi buttres bP89 batu sedang maintenance jalan di line 2</li>\r\n	<li>cut jalan 70</li>\r\n</ol>\r\n\r\n<p><strong>Jumlah Mnapower:</strong></p>\r\n\r\n<ul>\r\n	<li>Dt 21 orang</li>\r\n	<li>Exca 17 orang</li>\r\n	<li>Dozer 12 orang</li>\r\n	<li>Compac 5 orang</li>\r\n	<li>Lt 2 orang</li>\r\n	<li>Ceker 14 orang</li>\r\n	<li>Foreman 5 orang</li>\r\n</ul>\r\n\r\n<p><strong>Foreman:</strong></p>\r\n\r\n<ol>\r\n	<li>Elpin hadi</li>\r\n	<li>Theodorus Sitohang</li>\r\n	<li>Abdu m hamid</li>\r\n	<li>Abdul Rahman</li>\r\n	<li>Septiawan dwi</li>\r\n</ol>\r\n', '1767170893_WhatsApp Image 2025-12-31 at 14.15.58.jpeg', '2025-12-31 00:48:13', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(31, 0, 2, 20, 'BA OFFER SHIFT GEOTEK SHIFT SIANG', '<p>Untuk Pekerjaan Hari ini Tanggal 31/12/2025 Untuk Tim Geotek ,Meliputi :</p>\r\n\r\n<p>1.Monitoring Timbunan All Area</p>\r\n\r\n<p>2.Pengujian Sand Cone</p>\r\n\r\n<p>3.Pengujian Laboratorium.</p>\r\n\r\n<p>4.Kontruksi Butres.</p>\r\n\r\n<p>Adapun temuan untuk tim monitoring timbunan,ada retakan area line 1 selatan.dari tim geotek sudah melakukan koordinasi dengan tim operasi terkait skema pekerjaan di titik jatuh line 1 selatan.</p>\r\n\r\n<p>untuk pengujian CBR hari ini tidak bisa di lakukan di karenakan untuk jam kedua turun hujan.</p>\r\n', '1767173586_WhatsApp Image 2025-12-31 at 18.00.26.jpeg', '2025-12-31 01:33:06', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(32, 0, 6, 11, 'Daily Job Hidro ', '<p>1. Maintenance saluran operasional Comp C P89&nbsp;<br />\r\nPembersihan dari material lumpur pada saluran&nbsp;</p>\r\n\r\n<p>2. Maintenance finger comp B P89&nbsp;</p>\r\n\r\n<p>Pembersihan material lumpur dari saluran akibat longsoran aktifitas di sekitar toba 3 dalam&nbsp;</p>\r\n\r\n<p>3. Monitoring&nbsp;</p>\r\n\r\n<p>*Kondisi lapangan<br />\r\n&lrm;<br />\r\n* &lrm;Finger drain com B p89&nbsp; butuh maintenance untuk mengalirkan air yang tersumbat&nbsp;<br />\r\n&lrm;* Sump Comp C P23 banyak lumpur perlu maintenance&nbsp;<br />\r\n&lrm;*Pengukuran<br />\r\n&lrm;Pengukuran curah hujan manual<br />\r\n40ML<br />\r\n&lrm;<br />\r\n&lrm;* Debit<br />\r\n&lrm;Pengukuran data debit<br />\r\n0,0238 m3/s</p>\r\n\r\n<p><br />\r\n&lrm;Sumur Pantau&nbsp;<br />\r\n&lrm;Gw-07 :4,36m&nbsp;<br />\r\n&lrm;</p>\r\n\r\n<p>Alat&nbsp; yang digunakan&nbsp;</p>\r\n\r\n<p>2 exca long arm&nbsp;</p>\r\n\r\n<p>1 exca 200</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n', '1767242391_WhatsApp Image 2025-12-31 at 07.16.58.jpeg', '2026-01-01 04:39:51', 'Hydrology & Hydrogeology', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(33, 0, 2, 26, 'BA Overshift Geotech Shift Malam', '<p>Daily Job Geotech Shift Malam&nbsp;<br />\r\n*). Instrument dan Monitoring:<br />\r\nMonitoring arah dozzingan titik jatuh Line 1 selatan terdapat temuan:<br />\r\n- Di sisi selatan Masi terlihat ada patahan sedikit, perlu waspada dan continue pematauan<br />\r\n- Di sisi Utara juga ada patahan sedikit, perlu diwaspadai dan dicek berkala&nbsp;<br />\r\n- Di sisi timur ada patahan besar, dan perlu penanganan serius<br />\r\n*). Pengujian Lab<br />\r\nPengujian moisture content dan <strong>b</strong>ulk density dry tailing hasil filter press sukses dilakukan dan sampel dalam tahap pengeringan.&nbsp;<br />\r\nPengambilan sampel titik jatuh untuk pengujian bulanan belum dilakukan karena keterbatasan manpower dan dalam kondisi kurang fit.<br />\r\nPengambilan sampel titik jatuh sebanyak 3 sampel dimulai hari ini. Tujuannya untuk mendapatkan nilai kadar air titik jatuh yang representatif</p>\r\n', '1767216696_WhatsApp Image 2025-12-31 at 20.37.53.jpeg', '2025-12-31 13:31:36', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(34, 0, 1, 28, 'EARTHWORH SHIFT MALAM 31/12/2025', '<p><strong>JOB PENDING:</strong><br />\r\n<span style=\"color:#4e5f70\">1.Line 1 utara mix anrara dosingan dan hauling tailing ke komp A P23</span></p>\r\n\r\n<p><span style=\"color:#4e5f70\">2.Line 2 full hauling dan dumoing tailing di komp B,C dan D</span></p>\r\n\r\n<p><span style=\"color:#4e5f70\">3.Perbaikan jalan hauling dari line 2</span></p>\r\n\r\n<p><span style=\"color:#4e5f70\">4.Lipat taiking di jalan +70</span><br />\r\n<br />\r\n<strong>JUMLAH MANPOPWER:</strong></p>\r\n\r\n<ol>\r\n	<li><span style=\"color:#4e5f70\">Driver DT : 15 Opr</span></li>\r\n	<li><span style=\"color:#4e5f70\">Exca : 15 Opr</span></li>\r\n	<li><span style=\"color:#4e5f70\">Dozer : 13 Opr</span></li>\r\n	<li><span style=\"color:#4e5f70\">Compec : 4 Driver</span></li>\r\n	<li><span style=\"color:#4e5f70\">LT/LV : 2</span></li>\r\n	<li><span style=\"color:#4e5f70\">Cheker : 5</span></li>\r\n	<li><span style=\"color:#4e5f70\">Foreman : 4</span></li>\r\n	<li><span style=\"color:#4e5f70\">Spv 1</span></li>\r\n</ol>\r\n\r\n<p><strong>FOREMAN:</strong></p>\r\n\r\n<ol>\r\n	<li><span style=\"color:#4e5f70\">Ramli Tajuddin&nbsp;</span></li>\r\n	<li><span style=\"color:#4e5f70\">Deni Nugraha</span></li>\r\n	<li><span style=\"color:#4e5f70\">Irfandi Ode</span></li>\r\n	<li><span style=\"color:#4e5f70\">Safaat Umar</span></li>\r\n</ol>\r\n', '1767218080_WhatsApp Image 2025-12-31 at 21.36.30.jpeg', '2025-12-31 21:57:12', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(35, 0, 6, 11, 'Daily Job Hidro ', '<p>Job daily&nbsp;</p>\r\n\r\n<p>1. Maintenance sedimend Pond&nbsp;<br />\r\nMelanjutkan lipat material sedimend ke arah sisi barat kolam untuk di masukan ke drying bed baru</p>\r\n\r\n<p>2. Maintenance saluraan finger drain Comp.B P89&nbsp;<br />\r\nMelanjutkan pengangkatan material lumpur tailing yang masuk ke saluran dan pembuatan bench&nbsp;</p>\r\n\r\n<p>3. Monitoring&nbsp;</p>\r\n\r\n<p>Curah Hujan Ombrometer : 2,83 mm/day (31 Desember 2025)<br />\r\n<br />\r\nDebit Toe Drain&nbsp;<br />\r\n0,04 m3/s</p>\r\n\r\n<p>Pengukuran manual GW 7&nbsp;<br />\r\n35,85 m&nbsp;</p>\r\n\r\n<p>&nbsp;Kondisi lapangan<br />\r\n* Box kontrol comp A p23 sisi utara dan selatan sudah banyak material lumpur harus di maintenance&nbsp;</p>\r\n\r\n<p>* finger drain com C p89 lumpur sudah mulai banyak&nbsp;</p>\r\n\r\n<p>* tanggul finger drain jalan timur rusak dan perlu perbaikan&nbsp;</p>\r\n\r\n<p>* sump comp C banyak lumpur perlu di maintenance</p>\r\n\r\n<p>* sump comp B banyak lumpur perlu di maintenance<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n', '1767260971_WhatsApp Image 2026-01-01 at 07.26.52.jpeg', '2026-01-01 01:49:31', 'Hydrology & Hydrogeology', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(36, 0, 1, 16, 'EARTHWORH SHIFT SIANG 01/01/2026', '<p><strong>JOB PENDDING:</strong></p>\r\n\r\n<ol>\r\n	<li>Line 1 selatan full dozing ke arah Utara dan Selatan</li>\r\n	<li>Line 2 selatan full Hauling - triming di 60,B,C dan tugu batu&nbsp;</li>\r\n	<li>Batu Senggigi kontruksi buttres bP89 batu sedang maintenance jalan line 2</li>\r\n	<li>Cut jalan 70</li>\r\n</ol>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>MANPOWER:</strong><br />\r\nDt 19 orang Exc 17 orang Dozer 10 orang Compac 3 orang LV 2 orang Ceker 9 orang Foreman 6<br />\r\n<br />\r\n<br />\r\n<strong>FOREMAN:</strong></p>\r\n\r\n<ol>\r\n	<li>Elpin Hadi</li>\r\n	<li>Abdu M&nbsp;Hamid</li>\r\n	<li>Budi Setiawan</li>\r\n	<li>Abdul Rahman</li>\r\n	<li>Theodorus Sitohang</li>\r\n	<li>Septiawan Dwi</li>\r\n</ol>\r\n', '1767261282_WhatsApp Image 2026-01-01 at 08.13.07.jpeg', '2026-01-01 01:54:42', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(37, 0, 2, 20, 'BA OFFER SHIFT GEOTEK SHIFT SIANG', '<p>Untuk Pekerjaan Hari ini Tanggal 02/01/2026 Untuk Tim Geotek ,Meliputi :</p>\r\n\r\n<p>1.Monitoring Timbunan All Area</p>\r\n\r\n<p>2.Pengujian Sand Cone</p>\r\n\r\n<p>3.Pengujian Laboratorium.</p>\r\n\r\n<p>&nbsp;</p>\r\n', '1767346144_WhatsApp Image 2026-01-02 at 08.32.06.jpeg', '2026-01-02 09:29:23', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(38, 0, 6, 11, 'Daily Job Hidro ', '<p>1. Maintenance Finger drain Comp B P89&nbsp;<br />\r\nMelanjutkan cutting bench untuk dudukan exca maintenance dan mengeruk lumpur lebih dalam&nbsp;<br />\r\n<br />\r\n2. Monitoring&nbsp;<br />\r\nCurah hujan manual : 0 mL<br />\r\nDebit manual : 0,1800 m3/s<br />\r\nPengukuran manual GW 7 :36,79 m<br />\r\n<br />\r\nKondisi lapangan&nbsp;<br />\r\n* sump C dan B perlu maintenance dari material&nbsp;<br />\r\n* saluran pada comp B dan C perlu maintenance pada beberapa titik&nbsp;<br />\r\n* Saluran operasional pada Comp B P89 perlu maintenance&nbsp;<br />\r\n* Terdapat aliran air yang keluar pada area jalan line 2 dan perlu dilakukan perbaikan&nbsp;<br />\r\n* tanggul saluran jalan dari buttres D P23 kearah jalan 60 ada kerusakan sehingga air ada yang masuk jalan&nbsp;<br />\r\n* Inlet dan outlet pipa di buttres B P89 perlu maintenance&nbsp;<br />\r\n* Beberapa saluran yang baru dibuat (line 2, main buttres selatan atas, dan jalan turunan) sudah tertutup material akibat kegiatan operasional perlu perbaikan untuk kedepan nya&nbsp;</p>\r\n', '1767347675_WhatsApp Image 2026-01-02 at 15.25.29.jpeg', '2026-01-02 01:54:35', 'Hydrology & Hydrogeology', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(39, 0, 2, 26, 'BA Overshift Geotech Shift Malam', '<p>Daily Job Geotech Shift Malam 2 Januari 2025<br />\r\n*). Instrument dan Monitoring:<br />\r\nMonitoring arah dozzingan titik jatuh Line 1 selatan terdapat temuan:<br />\r\n- Di sisi selatan terdapat patahan, perlu waspada dan continue pematauan<br />\r\n- Pengawasan trimingan buttress CP89</p>\r\n\r\n<p>*). Pengujian Lab<br />\r\nPengambilan&nbsp;sampel filterpress sudah dilaksanakan, namun belum dilakukan pengujian dikarenakan keterbatasan manpower shift malam.&nbsp;<br />\r\nPengujian triaxial bulanan line 1 dan 2 sukses diuji. Sampel dalam tahap pengeringan.<br />\r\nPerbaikan pengujian proctor line 1 desember yang belum tuntas sudah diuji. Tinggal menunggu proses pengeringan sampel<br />\r\nPengujian index belum dilanjutkan.<br />\r\nPengambilan sampel titik jatuh sebanyak 3 sampel continue dilakukan. Tujuannya untuk mendapatkan nilai kadar air titik jatuh yang representatif</p>\r\n', '1767388769_WhatsApp Image 2026-01-02 at 20.57.58.jpeg', '2026-01-02 13:19:29', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(40, 0, 6, 11, 'Daily Job Hidro ', '<p>1. Maintenance finger drain comp B P89&nbsp;<br />\r\nMelanjutkan pembersihan material lumpur di saluran, sudah pembuatan bench untuk dudukan exca tinggal pengangkutan material lumpur, kendala bagian hulu saluran masih lembek perlu dikeruk sebagian untuk akses exca<br />\r\n<br />\r\n2. Maintenance operasional drain di comp&nbsp; C dan B P89&nbsp;<br />\r\nPembersihan saluran dari material lumpur di area comp C dan B&nbsp; P89&nbsp;<br />\r\n<br />\r\n3. Monitoring&nbsp;<br />\r\nCurah hujan : 10,7 mm/day&nbsp;</p>\r\n\r\n<p>Debit manual : 0,057 m3/s<br />\r\n<br />\r\nPengukuran manual GW 7 : 36,86 m&nbsp;<br />\r\n<br />\r\nKondisi lapangan&nbsp;</p>\r\n\r\n<p>-Area jalan masuk samping workshop banyak genangan air&nbsp;</p>\r\n\r\n<p>Peremeter samping comp A nol banyak lumpu dan rumput perlu di meintenance</p>\r\n\r\n<p>-box control area comp A p23 sudh banyak lumpur perlu di meintenance</p>\r\n\r\n<p>-finger drain area &nbsp;C p89 masih banyak lumpur perlu di meintenance</p>\r\n', '1767433975_WhatsApp Image 2026-01-03 at 16.04.56.jpeg', '2026-01-03 01:52:55', 'Hydrology & Hydrogeology', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(41, 0, 2, 26, 'BA Overshift Geotech Shift Malam', '<p>Daily Job Geotech Shift Malam 3 Januari 2025<br />\r\n*). Instrument dan Monitoring:<br />\r\nMonitoring arah dozzingan titik jatuh Line 1 selatan secara operasional sudah mengikuti rekomendasi tim Geotech dengan melakukan pemotongan timbunan bench yang mengalami retakan di arah selatan.&nbsp;<br />\r\nSelain itu arah dozzingan sudah cukup baik 2 arah utara dan selatan. Serta dibagian bawah satu dozzer melakukan spreading ke Timur. Operasional berjalan lancar dan aman.</p>\r\n\r\n<p>*). Pengujian Lab<br />\r\nPengambilan&nbsp;sampel filterpress sudah dilaksanakan, dan sudah proses.&nbsp;<br />\r\nPenghalusan sampel proctor line 2 Januari sudah dilakukan, sudah ditimbang 2 kg/kantong, dan telah diuji kadar airnya. Tinggal menunggu proses pengeringan sampel<br />\r\nPengujian index belum dilanjutkan.<br />\r\nPengambilan sampel titik jatuh sebanyak 3 sampel continue dilakukan. Tujuannya untuk mendapatkan nilai kadar air titik jatuh yang representatif</p>\r\n', '1767476080_WhatsApp Image 2026-01-04 at 06.26.53.jpeg', '2026-01-03 13:34:40', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(42, 0, 6, 11, 'Daily Job Hidro ', '<p>1. Maintenance finger drain&nbsp;<br />\r\nmelanjutkan maintenance finger di B p89 , kondisi perlu pembuatan akses ke arah hulu dan kendala material yang masih lembek akibat hujan&nbsp;<br />\r\n&nbsp;</p>\r\n\r\n<p>2. Konstruksi saluran toba 1&nbsp;<br />\r\npembuatan saluran di area toba 1&nbsp;</p>\r\n\r\n<p>3. Pemasangan Pipa di elevasi 70&nbsp;<br />\r\nPemasangan pipa di jalan 70 untuk mengalirkan air dari outlet buttres d p23<br />\r\n<br />\r\nMonitoring</p>\r\n\r\n<p>Curah hujan ombro : 5,48 mm/day</p>\r\n\r\n<p>Debit air manual : 0,074 m3/s<br />\r\n<br />\r\nKondisi lapangan&nbsp;<br />\r\n1. Box control di comp a P23 perlu maintenance&nbsp;<br />\r\n2. Finger timur P 23 perlu perbaikan&nbsp;<br />\r\n3. Saluran operasional B p23 perlu maintenance<br />\r\n4. Sump C P23 perlu maintennace<br />\r\n5. inlet dan outlet buttres B p89 perlu maintenance<br />\r\n6. Saluran outlet Buttres C P89 perlu maintenance&nbsp;<br />\r\n&nbsp;</p>\r\n\r\n<p><br />\r\n<br />\r\n&nbsp;</p>\r\n', '1767520611_WhatsApp Image 2026-01-04 at 17.27.14.jpeg', '2026-01-04 01:56:51', 'Hydrology & Hydrogeology', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(43, 0, 2, 26, 'BA Overshift Geotech Shift Malam', '<p>Daily Job Geotech Shift Malam 4 Januari 2025<br />\r\n*). Instrument dan Monitoring:<br />\r\nMonitoring arah dozzingan titik jatuh Line 1 selatan secara operasional sudah mengikuti rekomendasi tim Geotech.&nbsp;<br />\r\nSelain itu arah dozzingan sudah cukup baik 2 arah utara dan selatan. Serta dibagian bawah satu dozzer melakukan spreading ke Timur. Operasional berjalan lancar dan aman.<br />\r\nLine 1 Selatan kancing</p>\r\n\r\n<p>*). Pengujian Lab<br />\r\nPengambilan&nbsp;sampel filterpress sudah dilaksanakan, dan sudah proses.&nbsp;<br />\r\nPengujian LLPL Line 1 dan 2 sudah diuji.<br />\r\nPengambilan sampel titik jatuh sebanyak 3 sampel continue dilakukan. Tujuannya untuk mendapatkan nilai kadar air titik jatuh yang representatif</p>\r\n', '', '2026-01-04 13:38:17', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(44, 0, 2, 20, 'BA OFFER SHIFT GEOTEK SHIFT SIANG', '<p>Report Kegiatan Geotek Hari Senin , 05/01/2026</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ol>\r\n	<li>Monitoring All Area DSTF</li>\r\n	<li>Pengujian Specific Gravity</li>\r\n	<li>Kalibrasi Pasir Sandcone</li>\r\n	<li>Pembacaan Konsolidasi</li>\r\n	<li>Preparasi sampel Proctor</li>\r\n	<li>Pengambilan dan pengujian Sampel FP</li>\r\n</ol>\r\n', '1767603218_WhatsApp Image 2026-01-05 at 14.43.38.jpeg', '2026-01-05 00:53:38', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(45, 0, 6, 11, 'Daily Job Hidro ', '<p>Kondisi cuaca : Hujan&nbsp;<br />\r\n<br />\r\n1. Maintenance Finger B P89&nbsp;<br />\r\nMelanjutkan pembuatan akses jalan dan cutting material di compartmend B P89&nbsp;<br />\r\n<br />\r\n2. Maintenance sedimend Pond&nbsp;<br />\r\nMelanjutakan lipat material ke bagian barat drying bed&nbsp;</p>\r\n\r\n<p>3. Monitoring&nbsp;</p>\r\n\r\n<p>Curah hujan manual (Ombrometer) : 34,32 mm/day&nbsp;</p>\r\n\r\n<p>Debit manual : 0,1483 m3/s<br />\r\n<br />\r\nPengambilan data GW 7 : 36,9 m<br />\r\n<br />\r\nPengambilan data sumur Pantau GW 6, GW 8 dan GW 10<br />\r\n<br />\r\nKondisi Lapangan&nbsp;<br />\r\n* Area jalan masuk Workshop lama sudah mulai tergenang akibat hujan dan penurunan jalan&nbsp;<br />\r\n* Box control di A P23 sudah penuh material&nbsp;<br />\r\n* Sisi barat saluran operasional comp B 23 perlu maintenance&nbsp;<br />\r\n* Sisi barat saluran di comp C P23 perlu konstruksi saluran&nbsp;<br />\r\n* Perlu maintenance saluran di turunan ke buttres B p89&nbsp;<br />\r\n* Saluran di B dan C P89 sudah mulai tertutup material&nbsp;<br />\r\n* Inlet dan outlet di buttres B dan C P89 perlu maintenance&nbsp;<br />\r\n* Jalan masuk line 2 atas perlu pasang pipa untuk jalur air&nbsp;<br />\r\n* Perimeter bukit nona perlu maintenance karena material sudah hampir selevel dengan jalan&nbsp;<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n', '1767606338_WhatsApp Image 2026-01-05 at 10.21.30.jpeg', '2026-01-05 01:45:38', 'Hydrology & Hydrogeology', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(46, 0, 2, 26, 'BA Overshift Geotech Shift Malam', '<p>Daily Job Geotech Shift Malam 5 Januari 2025<br />\r\n*). Instrument dan Monitoring:<br />\r\nLine 1 Selatan kancing, monitoring diarahkan ke Line 1 Utara dan berjalan cukup baik</p>\r\n\r\n<p>*). Pengujian Lab<br />\r\nPengambilan&nbsp;sampel filterpress sudah dilaksanakan, dan sudah proses.&nbsp;<br />\r\nPenghalusan sampel proctor line 1 sudah selesai dilakukan.&nbsp;</p>\r\n', '1767649311_WhatsApp Image 2026-01-05 at 20.57.03.jpeg', '2026-01-05 13:41:51', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(47, 0, 2, 26, 'BA Overshift Geotech Shift Malam', '<p>Daily Job Geotech Shift Malam 6 Januari 2025<br />\r\n*). Instrument dan Monitoring:<br />\r\nLine 1 Selatan continue monitoring operasional berjalan cukup baik</p>\r\n\r\n<p>*). Pengujian Lab<br />\r\nPengambilan&nbsp;sampel filterpress sudah dilaksanakan, dan sudah pengujian.&nbsp;<br />\r\nSampel proctor line 1 modified sudah diuji.&nbsp;</p>\r\n', '1767735392_WhatsApp Image 2026-01-06 at 21.24.48.jpeg', '2026-01-06 13:36:32', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(48, 0, 2, 26, 'BA Overshift Geotech Shift Siang 7 Januari 2026', '<p>1. PROGRESS HARI INI</p>\r\n\r\n<p>- Pengujian Sandcone Compartment A P23 dan C P89</p>\r\n\r\n<p>- Monitoring Area Operasi</p>\r\n\r\n<p>- Konstruksi Pelebaran Area Buttress D P23 titik Jatuh Line 2 untuk area manuver DT Loading</p>\r\n\r\n<p>- Pengambilan dan Pengujian Sampel Filterpress Line 1 dan Line 2</p>\r\n\r\n<p>- Pengujian Grainsize&nbsp;</p>\r\n\r\n<p>- Mix Air Proctor</p>\r\n\r\n<p>- Preparasi Sampel Jakarta</p>\r\n\r\n<p>- Pembuatan Peta Resiko, Weekly, dan Annual Report</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>2. TEMUAN</p>\r\n\r\n<p>- Kendala di Pengujian CPTu sehingga dilakukan maintenance dan moving ke titik selanjutnya</p>\r\n\r\n<p>- Sampel uji di serahkan ke Teknologi</p>\r\n\r\n<p>- Mulai progress Konstruksi untuk area pelebaran Buttress untuk manuver DT</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>3. JOB PENDING</p>\r\n\r\n<p>- Haluskan Sampel Filterpress Line 1 dan Line 2 di Oven</p>\r\n\r\n<p>- Pengambilan sampel filterpress Line 1 dan Line 2</p>\r\n\r\n<p>- Monitoring area operasi</p>\r\n\r\n<p>- Monitoring konstruksi pelebaran buttress untuk area manuver loading titik jatuh line 2</p>\r\n\r\n<p>- Ulang uji LLPL Line 1 dan Line 2</p>\r\n\r\n<p>- Mobilisasi Shelter CPTu ke titik yang baru</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n', '1767775428_WhatsApp Image 2026-01-07 at 15.38.05.jpeg', '2026-01-07 00:43:48', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(49, 0, 2, 26, 'BA Overshift Geotech Shift Malam', '<p>Daily Job Geotech Shift Malam 7 Januari 2025<br />\r\n1. Pengawasan trimingan mega tower<br />\r\n2. Pengambilan dan pengujian kadar air sampel filterpress&nbsp;<br />\r\n3. Pemindahan shelter cptu<br />\r\n<br />\r\nTemuan<br />\r\n1. Line 1 main di Utara karena keterbatasan unit<br />\r\n&nbsp;</p>\r\n\r\n<p>Job Pending<br />\r\n1. Revisi LLPL<br />\r\n2. Penghalusan sampel proctor<br />\r\n3. Collect weekly all division<br />\r\n&nbsp;</p>\r\n', '1767821017_WhatsApp Image 2026-01-08 at 03.29.41.jpeg', '2026-01-07 21:26:18', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(50, 0, 1, 28, 'EARTHWORH SHIFT MALAM 01/01/2026', '<p><strong>JOB PENDING:</strong></p>\r\n\r\n<p>1.line 1 selatan full dosing dan arah dosingan ke selatan dan timur 2 line</p>\r\n\r\n<p>2 full hauling dan dumping di komp B dan C</p>\r\n\r\n<p>3.kontruksi jln +70</p>\r\n\r\n<p>4.kkntruksi butress B P89</p>\r\n\r\n<p>5.perbaikan jakan hauling</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>MANPOWER:</strong><br />\r\nDriver DT : 19 Opr Exca : 17 Opr Dozer : 14 Opr Compec : 5 Driver LT/LV : 2 Cheker : 8 Foreman : 4 Spv 1</p>\r\n\r\n<p><br />\r\n<br />\r\n<strong>FOREMAN SHIFT MALAM:</strong><br />\r\n1.Ramli T</p>\r\n\r\n<p>2.Irfandi ode</p>\r\n\r\n<p>3.Safaat umar</p>\r\n\r\n<p>4.Deni nugraha<br />\r\n<br />\r\n<br />\r\n<strong>FOREMAN SHIFT SIANG:</strong><br />\r\n1Abdul Rahman<br />\r\n2.Abdu m hamid<br />\r\n3.Elfin hadi s<br />\r\n4.Theodorus s</p>\r\n', '1767826422_WhatsApp Image 2026-01-03 at 01.27.44.jpeg', '2026-01-01 21:00:42', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(51, 0, 1, 28, 'EARTHWORH SHIFT MALAM 02/01/2026', '<p><strong>JOB PENDDING:</strong><br />\r\n<br />\r\n1.line 1 selatan full.dosing arah dosingan ke timur dan selatan</p>\r\n\r\n<p>2.line 2 full hauling dan dumpingan di komp B,Cdan D P89</p>\r\n\r\n<p>3.kontruksi butress B P89<br />\r\n<br />\r\n<br />\r\n<strong>JUMLAH MANPOWER:</strong><br />\r\nDriver DT : 14 Opr Exca : 12 Opr Dozer : 10 Opr Compec : 2 Driver LT/LV : 1 Cheker : 4 Foreman : 3 Spv 1</p>\r\n\r\n<p><br />\r\n<br />\r\n<strong>FOREMAN SHIFT MALAM:</strong></p>\r\n\r\n<p>1.Ramli t</p>\r\n\r\n<p>2.Irfandi ode</p>\r\n\r\n<p>3.Safaat umar</p>\r\n\r\n<p>&nbsp;</p>\r\n', '1767828399_WhatsApp Image 2026-01-02 at 20.58.15 (1).jpeg', '2026-01-02 20:26:39', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(52, 0, 1, 16, 'EARTHWORK SHIFT MALAM  03/01/2026', '<p><strong>JOB PENDING:</strong><br />\r\n<br />\r\nLine 1 selatan full dozing kearah Utara dan Selatan</p>\r\n\r\n<p>Line 2 selatan Hauling dan triming di 60, B, C dan tugu batu</p>\r\n\r\n<p>Batu Senggigi kontruksi buttres bP89 c</p>\r\n\r\n<p>ut tailing jalan 70</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>MANPOWER:</strong></p>\r\n\r\n<p>Dt 21 orang</p>\r\n\r\n<p>Exc 17 orang</p>\r\n\r\n<p>Dozer 12 orang</p>\r\n\r\n<p>Compac 5 orang</p>\r\n\r\n<p>Lt 2 orang</p>\r\n\r\n<p>Ceker 7 orang</p>\r\n\r\n<p>foreman 4 orang<br />\r\n<br />\r\n<strong>FOREMAN SHIFT SIANG:</strong><br />\r\n1.Abdul Rahman</p>\r\n\r\n<p>2.Theodorus Sitohang</p>\r\n\r\n<p>3.Deni Nugraha</p>\r\n\r\n<p>4.Septiawan dwi<br />\r\n<br />\r\n<strong>FOREMAN SHIFT MALAM:</strong><br />\r\n1.Elpin hadi</p>\r\n\r\n<p>2.Abdu m hamid</p>\r\n\r\n<p>3.m safaat umar</p>\r\n\r\n<p>4.Irfandi ode</p>\r\n\r\n<p>5.ramli Tadjuddin<br />\r\n<br />\r\nCATATAN:<br />\r\nð–¤ð–·ð–¢ð–  ð–²ð– ðŸ¥ï¼ðŸ¢ðŸª ð–ºð–½ð–º ð—„ð–¾ð–»ð—ˆð–¼ð—ˆð—‹ð–ºð—‡ oli; ð—Œð–½ð— ð—‰ð–ºð—‹ð—„ð—‚ð—‹ ð–½ð—‚ ð—ð–¾ð—†ð—‰ð–ºð— ð–ºð—†ð–ºð—‡</p>\r\n', '1767829644_WhatsApp Image 2026-01-03 at 08.20.18 (1).jpeg', '2026-01-03 20:47:24', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(53, 0, 1, 28, 'EARTHWORK SHIFT SIANG 04/01/2026', '<p><strong>JOB PENDDING:</strong><br />\r\n<br />\r\n1.line 1 selatan full dosing arah spreadingan ke arah timur dan utara</p>\r\n\r\n<p>2.line 2 full hauling dumpingan di butresd,c ,B dan jalan +60 ujung</p>\r\n\r\n<p>3.kontruksi butress B P89</p>\r\n\r\n<p>4.kontruksi jalan +70</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>JUMLAH MANPOWER:</strong></p>\r\n\r\n<p>Driver DT : 20 Opr</p>\r\n\r\n<p>Exca : 16 Opr</p>\r\n\r\n<p>Dozer : 13 Opr</p>\r\n\r\n<p>Compec : 4</p>\r\n\r\n<p>Driver LT/LV : 1</p>\r\n\r\n<p>Checker : 6</p>\r\n\r\n<p>Foreman : 1 Spv 1<br />\r\n<br />\r\nFOREMAN SHIFT SIANG:<br />\r\nRamli Tajuddin</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>FOREMAN SHIFT MALAM:<br />\r\nIrfandi ode, Safaat umar, Elfin hadi s<br />\r\n&nbsp;</p>\r\n', '1767830813_WhatsApp Image 2026-01-04 at 09.12.28.jpeg', '2026-01-04 08:46:49', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(54, 0, 1, 28, 'EARTHWORK SHIFT SIANG 05/01/2026', '<p><strong>JOB PENDDING:</strong><br />\r\n1.line 1 utara mix antara dosingan dan hauling ke mega tower dan konveyor 10</p>\r\n\r\n<p>2.line 2 full hauling dumpingan di jalan +60 tengah Butress B,C</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>MANPOWER:</strong></p>\r\n\r\n<p>Driver DT : 20 Opr</p>\r\n\r\n<p>Exca : 15 Opr</p>\r\n\r\n<p>Dozer : 12 Opr</p>\r\n\r\n<p>Compec : 4 Driver</p>\r\n\r\n<p>LT/LV : 2</p>\r\n\r\n<p>Cheker : 9</p>\r\n\r\n<p>Foreman : 2</p>\r\n\r\n<ul>\r\n	<li>1.Ramli T</li>\r\n	<li>2.Abdul rahman</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Foreman Shift Malam:</strong></p>\r\n\r\n<p>Abdu m hamid, Theodorus,&nbsp; Safaat umar, Abdu m hamid</p>\r\n', '1767831771_WhatsApp Image 2026-01-05 at 09.08.07 (1).jpeg', '2026-01-05 08:22:51', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(55, 0, 1, 16, 'BA OVER SHIFT EARTHWORK SHIFT MALAM 05/01/2026', '<p><strong>JOB PENDDING:</strong><br />\r\nLine 1 Utara</p>\r\n\r\n<ul>\r\n	<li>dozing keselatan timur</li>\r\n	<li>hauling dan triming di megatower dan comp Ap23</li>\r\n</ul>\r\n\r\n<p>Line 2 selatan</p>\r\n\r\n<ul>\r\n	<li>Hauling dan triming di 60 B,C dan tugu batu</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>MANPOWER:</strong></p>\r\n\r\n<ul>\r\n	<li>Dt 20 orang</li>\r\n	<li>Exc 13 orang</li>\r\n	<li>Dozer 12 orang</li>\r\n	<li>Compac 3 orang</li>\r\n	<li>Lt 2 orang</li>\r\n	<li>Ceker 6 orang</li>\r\n	<li>foreman 5 orang</li>\r\n</ul>\r\n\r\n<p>Foreman:&nbsp;elpin hadi, abdu m hamid, Theodorus Sitohang, m safaat umar, septiawan dwi<br />\r\n<br />\r\nFoeman Shift Siang:&nbsp;Irfandi ode, deni Nugraha, Abdul Rahman, ramli Tadjuddin</p>\r\n', '1767832185_WhatsApp Image 2026-01-05 at 20.56.15.jpeg', '2026-01-05 20:29:45', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(56, 0, 1, 28, 'EARTHWORK SHIFT SIANG 06/01/2026', '<p><strong>JOB PENDDING:</strong><br />\r\n1.line 1 selatan full dosing</p>\r\n\r\n<p>2.line 2 full hauling dumping di komp B dan C P89</p>\r\n\r\n<p>3.kontruksi jalan +70</p>\r\n\r\n<p>4.perapihan titik jatuh line 1 utara untuk manuver DT<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>MANPOWER:</strong></p>\r\n\r\n<p>Driver DT : 20 Opr</p>\r\n\r\n<p>Exca : 18 Opr</p>\r\n\r\n<p>Dozer : 15 Opr</p>\r\n\r\n<p>Compec : 4 Driver</p>\r\n\r\n<p>LT/LV : 2</p>\r\n\r\n<p>Cheker : 10</p>\r\n\r\n<p>Foreman : 3</p>\r\n\r\n<p>Spv 1 orang<br />\r\n<br />\r\nForeman Shift Siang:&nbsp;Abdul rahman, Ramli t, Irfandi ode<br />\r\nForeman Shift Malam:&nbsp;Abdu m hamid, Safaat umar, Theodorus s, Elfin hadi s</p>\r\n', '1767832754_WhatsApp Image 2026-01-06 at 08.59.48.jpeg', '2026-01-06 08:39:14', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL);
