(57, 0, 1, 16, 'EARTHWORK SHIFT MALAM 06/01/2026', '<p><strong>JOB PENDDING:</strong><br />\r\nLine 1 selatan full dozing ke arah Utara dan Selatan</p>\r\n\r\n<p>Line 2 selatan Hauling dan triming di B,C dan tugu batu<br />\r\n<br />\r\n<strong>MANPOWER:</strong><br />\r\nDt 20 orang</p>\r\n\r\n<p>Exc 14 orang</p>\r\n\r\n<p>Dozer 12 orang</p>\r\n\r\n<p>Compac 3 orang</p>\r\n\r\n<p>Lt 3 orang</p>\r\n\r\n<p>Ceker 4 orang</p>\r\n\r\n<p>oreman 4 orang</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Foreman Shift Malam:&nbsp;elpin hadi, abdu m hamid, Theodorus Sitohang, septiawan dwi<br />\r\nForeman Shift Siang:&nbsp;Abdul Rahman, m safaat umar, Irfandi ode, ramli Tadjuddin, deni Nugraha</p>\r\n', '1767833036_WhatsApp Image 2026-01-06 at 20.24.56 (1).jpeg', '2026-01-06 20:43:56', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(58, 0, 1, 28, 'EARTHWORK SHIFT SIANG 07/01/2026', '<p><strong>JOB PENDDING:</strong><br />\r\n1.line 1 utara full hauling dumping ke komp AP23</p>\r\n\r\n<p>2.line 2 full hauling di komp.B,dan D P89<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>JUMLAH MANPOWER:</strong></p>\r\n\r\n<p>Driver DT : 22 Opr</p>\r\n\r\n<p>Exca : 16 Opr</p>\r\n\r\n<p>Dozer : 14 Opr</p>\r\n\r\n<p>Compec : 5 Opr</p>\r\n\r\n<p>Greder. : 1 Driver</p>\r\n\r\n<p>LT/LV : 2</p>\r\n\r\n<p>Cheker : 10</p>\r\n\r\n<p>Foreman : 5</p>\r\n\r\n<p>Spv : 1</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Foreman Shift Siiang:&nbsp;&nbsp;Abdul rahman, Ramli t, Deni N, Irfandi ode, Safaat umar</p>\r\n\r\n<p>Foreman Shift Malam:&nbsp;Abdu m hamid, Elfin hadi s, Theodorus</p>\r\n\r\n<p>PLT Shift malam: Septiawan Dwi Winoto</p>\r\n', '1767833596_WhatsApp Image 2026-01-07 at 10.49.15.jpeg', '2026-01-07 08:53:16', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(59, 0, 1, 16, 'EARTHWORK SHIFT MALAM  07/01/2026', '<p><strong>JOB PENDDING:</strong></p>\r\n\r\n<p>Line 1 Utara Hauling triming di comp Ap23</p>\r\n\r\n<p>Line 2 selatan Hauling triming di B,C comp D p89</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>MANPOWER:</strong></p>\r\n\r\n<p>Dt 19 orang</p>\r\n\r\n<p>Exca 17 orang</p>\r\n\r\n<p>Dozer 16 orang</p>\r\n\r\n<p>Compac 3 orang</p>\r\n\r\n<p>Lt 3 orang</p>\r\n\r\n<p>Ceker 4 orang</p>\r\n\r\n<p>Foreman 4 orang</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>FOREMAN SHIFT MALAM:<br />\r\nelpin hadi, abdu m hamid ,Theodorus Sitohang, septiawan dwi</p>\r\n', '1767856400_WhatsApp Image 2026-01-07 at 19.57.51.jpeg', '2026-01-07 20:13:20', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(60, 0, 2, 26, 'BA Overshift Geotech Shift Malam', '<p>Daily Job Geotech Shift Malam 8 Januari 2025<br />\r\n*). Instrument dan Monitoring:<br />\r\nPengawasan trimingan turunan B P89</p>\r\n\r\n<p>*). Pengujian Lab<br />\r\nPengambilan&nbsp;sampel filterpress sudah dilaksanakan, dan sudah pengujian.&nbsp;<br />\r\nPengujian LLPL line 1 dan 2 revisi</p>\r\n', '1767906392_WhatsApp Image 2026-01-08 at 21.38.06.jpeg', '2026-01-08 13:06:32', 'Instrument & Geotechnical', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(61, 0, 6, 11, 'Daily Job Hidro ', '<p>1. Maintenance Saluran Inlet B p89&nbsp;<br />\r\nPembersihan material lumpur diarea dekat pipa inlet buttres B P89 untuk melancarkan aliran air&nbsp;<br />\r\n<br />\r\n2. Maintenance finger drain Comp C P89&nbsp;<br />\r\nPembersihan material lumpur pada area saluran&nbsp;<br />\r\n<br />\r\n3. Maintenance Finger drain comp B P89&nbsp;<br />\r\nPembentukan bench untuk area pembuangan lumpur diarea finger drain toba 3 dalam dan pelebaran dudukan exca&nbsp;<br />\r\n<br />\r\nAlat berat yang digunakan&nbsp;<br />\r\n<br />\r\n* 2 Long Arm&nbsp;</p>\r\n\r\n<p>4. Monitoring&nbsp;<br />\r\nCurah hujan ombrometer : 7,08 mm/day&nbsp;<br />\r\nDebit manual : 0,076 m3/s<br />\r\nPengukuran manual Gw 7 : 37,12 m&nbsp;<br />\r\n<br />\r\nKondisi lapangan</p>\r\n\r\n<p>1. Area Jalan belakang workshop masih terdapat genangan air perlu perbaikan elevasi jalan&nbsp;<br />\r\n2. Area Operasional drain comp A p23&nbsp; perlu maintenance&nbsp;<br />\r\n3. Box control Comp A P23 sudah penuh material dan perlu maintenance<br />\r\n4. Operasional drain Comp B P23 perlu perbaikan saluran untuk mengalirkan air ke selatan&nbsp;<br />\r\n5. Sump B Sudah penuh lumpur&nbsp;<br />\r\n6. Box control di C P23 sudah penuh lumpur&nbsp;<br />\r\n7. Finger timur P23 ada longsoran pada beberapa titik sehingga air tersumbat<br />\r\n8. Sump&nbsp; P23 sudah mulai penuh lumpur&nbsp;<br />\r\n9. Operasional drain Comp D sudah sebagian ada yang tertutup material dari unit yang melintas&nbsp;<br />\r\n10. Saluran operasional B P89 sebagian ada yang tertutup material&nbsp;<br />\r\n11. Saluran Operasional drain Comp C p89 tertutup material dari trimingan&nbsp;<br />\r\n12. Finger timur B dan C P89 sudah mulai tebal dan perlu maintenance&nbsp;<br />\r\n13. Masih terdapat aliran air dari jalan 60 ke buttres B P89 sehingga perlu perbaikan jalan</p>\r\n', '1767944993_Main c p89 fgr tmr 2.jpeg', '2026-01-08 23:49:53', 'Hydrology & Hydrogeology', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(62, 0, 1, 28, 'EARTHWORH SHIFT SIANG 08/01/2026', '<p><strong>JOB PENDDING:</strong><br />\r\n1.line 1 selatan full dosing arah dosingan ke arah utara,timur dan barat(arah msp)</p>\r\n\r\n<p>2.line full hauling dumping tailing di komp B,C dan D</p>\r\n\r\n<p>3.batu ambil di quari jalan +90 dumping di jalan +70</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>MNAPOWER:</strong><br />\r\nDriver DT : 19 Opr Exca : 15 Opr Dozer : 13 Opr Compec : 4 Driver LT/LV : 2 Cheker : 11 Foreman : 5 Spv 1</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>FOREMAN:<br />\r\nRamli t, Deni n, Abdul rahman, Irfandi ode, Safaat umar</p>\r\n', '1767950843_WhatsApp Image 2026-01-08 at 18.29.54.jpeg', '2026-01-08 08:27:23', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
