(64, 0, 1, 28, 'EARTHWORH SHIFT SIANG 09/01/2026', '<p><strong>JOB PENDDING:</strong></p>\r\n\r\n<ol>\r\n	<li>line 1 selatan full dosing untuk spreading tailing nya</li>\r\n	<li>line 2 full hauling tailing dumping di komp B,C,D P89</li>\r\n	<li>kontruksi jalan +70,laminating jalan dan lipat tailing nya</li>\r\n	<li>benruk tanggul +90 di komp A di jalan belakang work shop sejajar coveyor 10 bila exca lebih</li>\r\n	<li>Lipat tailing titik jatuh line 1 utara bila exca lebih</li>\r\n</ol>\r\n\r\n<p><strong>MANPOWER:</strong><br />\r\nDriver DT : 19 Opr Exca : 15 Opr Dozer : 14 Opr Compec : 4 Driver LT/LV : 2 Cheker : 13 Foreman : 4 Spv 1</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>FOREMAN SHIFT SIANG:</strong><br />\r\nAbdul rahman, Irfandi od,e Ramli t, Safaat umar</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>FOREMAN SHIFT MALAM:</strong><br />\r\nElfin hadi s, Theodorus s, Deni nugraha<br />\r\n<br />\r\n&nbsp;</p>\r\n', '1767951383_WhatsApp Image 2026-01-09 at 09.21.15.jpeg', '2026-01-09 01:36:23', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
