(76, 0, 1, 28, 'BA Overshift Earthwork Shift Malam 12/01/2026', '<p>JOB PENDDING:<br />\r\n1.line 1 utara mix antara dosingan dan hauling ke komp AP23</p>\r\n\r\n<p>2.line 2 full hauling dan dumpinhan tailing di tugu batu(komp.D)butress B arah komp B dan C)jalan +60 tengah dan ujung( arah komp B)P89</p>\r\n\r\n<p>3.kontruksi jalan +70(laminating dan tanggul)</p>\r\n\r\n<p>4.perapihan tailing yg menutup butress C dan B P89<br />\r\n<br />\r\n<br />\r\nMANPOPWER:<br />\r\nDriver DT : 18</p>\r\n\r\n<p>Opr Exca : 16</p>\r\n\r\n<p>Opr Dozer : 13</p>\r\n\r\n<p>Opr Compec : 4</p>\r\n\r\n<p>Driver LT/LV : 2</p>\r\n\r\n<p>Cheker : 8</p>\r\n\r\n<p>Foreman : 3</p>\r\n\r\n<p>Spv 1<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN:<br />\r\nDeni nugraha, Theodorus s,Septian dwi<br />\r\n<br />\r\nFOREMAN SHIFT PAGI:<br />\r\nAbdul rahman, Safaat umar ,Irfandi ode, Elfin hadi s</p>\r\n', '1768179675_WhatsApp Image 2026-01-11 at 20.38.49.jpeg', '2026-01-12 01:01:15', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(77, 0, 1, 17, 'BA Overshift Earthwork Shift Pagi 12/01/2026', '<p>JOB PENDDING:<br />\r\nLINE 2 SELATAN</p>\r\n\r\n<p>Full Hauling</p>\r\n\r\n<p>1. Unloading +60 tenga</p>\r\n\r\n<p>2. Unloading +60 unjung</p>\r\n\r\n<p>3. Unloading Butt B89 timur</p>\r\n\r\n<p>4. Unloading Comp C89 barat</p>\r\n\r\n<p>5. Unloading Butt C23 barat</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>KONSTRUKSI JALAN+70</p>\r\n\r\n<p>1. Laminating akses+70</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>CUTTING +90</p>\r\n\r\n<p>1. Breaker batu</p>\r\n\r\n<p>2. Lipat OB ke arah barat</p>\r\n\r\n<p>3. Loading batu</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>LINE 1 SELATAN</p>\r\n\r\n<p>Full Dozing</p>\r\n\r\n<p>1. Spreading ke arah utara</p>\r\n\r\n<p>2. Dozing ke arah selatan pelebaran dudukan dozer untuk persiapan dozer full satu arah dozing ke selatan<br />\r\n<br />\r\n<br />\r\nMANPOWER:</p>\r\n\r\n<ol>\r\n	<li>DT: 23 Orang</li>\r\n	<li>LT: 1 Orang</li>\r\n	<li>Excavator:21 Orang 4: Buldozer: 14 Orang</li>\r\n	<li>Compact: 5 Orang</li>\r\n	<li>Checker: 9 Orang</li>\r\n	<li>Foreman: 4 Orang</li>\r\n</ol>\r\n\r\n<p>FOREMAN:</p>\r\n\r\n<ol>\r\n	<li>Abdulrahman</li>\r\n	<li>Abdu</li>\r\n	<li>M Safaat</li>\r\n	<li>Irfandi Ode</li>\r\n</ol>\r\n\r\n<p>FOREMAN PELAKSANA:</p>\r\n\r\n<ol>\r\n	<li>Deni Nugraha</li>\r\n	<li>Ste wani</li>\r\n	<li>Theodorus</li>\r\n</ol>\r\n', '1768210503_WhatsApp Image 2026-01-12 at 09.07.39.jpeg', '2026-01-12 09:35:03', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(78, 0, 1, 28, 'BA Overshift Earthwork Shift Malam 13/01/2026', '<p>JOB&nbsp; PENDING:<br />\r\n<br />\r\n1.line 1 selatan full dosing arah spreadingan ke arah msp libas air</p>\r\n\r\n<p>2.line 2 full hauling dumping di komp BC P89</p>\r\n\r\n<p>3.kontruksi jalan +70 laminaring jakan dan lipat tailing utk pelebaran jalan<br />\r\n<br />\r\n<br />\r\nMANPOWER:</p>\r\n\r\n<p>Driver DT : 21 Opr Exca : 14 Opr Dozer : 17 Opr Compec : 4 Driver LT/LV : 2 Cheker : 7 Foreman : 3 Spv 1</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>FOREMAN:<br />\r\nDeni nugraha ,Theodorus s, Stewani T<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN PELAKSANA</p>\r\n\r\n<p>Abdul rahman Septian dwi w Abdu m hamid Safaat umar Eldin hadi s</p>\r\n', '1768256539_WhatsApp Image 2026-01-12 at 20.42.29.jpeg', '2026-01-12 20:22:19', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(80, 0, 1, 17, 'BA Overshift Earthwork Shift Pagi 13/01/2026', '<p><strong>JOB PENDDING:</strong></p>\r\n\r\n<ol>\r\n	<li>Line 1 selatan full dozing ke Utara</li>\r\n	<li>Line 2 selatan full Hauling triming di 60, B, C dan Cp23</li>\r\n	<li>batu lanjut laminating jl 70 cut tailing jl 70 cut tailing 60 ujung dozing ke arah air ( Utara )</li>\r\n</ol>\r\n\r\n<p><strong>MANPOWER HARI INI:</strong></p>\r\n\r\n<ol>\r\n	<li>Dt 23 orang,</li>\r\n	<li>Exc 19 orang,</li>\r\n	<li>Dozer 17 orang,</li>\r\n	<li>Compac 4 orang,</li>\r\n	<li>Wt 1 orang,</li>\r\n	<li>Lt 2 orang ,</li>\r\n	<li>Ceker 11 orang,</li>\r\n	<li>Foreman 4</li>\r\n</ol>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>FOREMAN</strong></p>\r\n\r\n<p>Abdul Rahman m safaat umar Abdu m hamid Septiawan dwi<br />\r\n<br />\r\nSPV: Ardyles Teken<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>FOREMAN PELAKSANA</strong></p>\r\n\r\n<p>deni Nugraha, Theodorus Sitohan,g stewani tununu, Irfandi ode</p>\r\n\r\n<h3>SPV: Nanang Koswara</h3>\r\n', '1768292368_WhatsApp Image 2026-01-13 at 10.02.39.jpeg', '2026-01-13 08:22:47', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(83, 0, 1, 28, 'BA Overshift Earthwork Shift Malam 13/01/2026', '<p><strong>JOB PENDDING:</strong><br />\r\n1.line 1 utara mix antara dosingan dan hauling tailing ke komp A P23</p>\r\n\r\n<p>2.line 2 full hauling dumping butress C p23,jalan +60 dan butress B P89</p>\r\n\r\n<p>3.perbaikan jalan turunan ipal</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>JUMLAH MANPOWER</strong></p>\r\n\r\n<ol>\r\n	<li>Driver DT : 20</li>\r\n	<li>&nbsp;Opr Exca : 11</li>\r\n	<li>Opr Dozer : 15</li>\r\n	<li>Opr Compec : 4</li>\r\n	<li>Driver LT/LV : 2</li>\r\n	<li>Cheker : 8</li>\r\n	<li>Foreman : 5</li>\r\n	<li>Spv 1</li>\r\n</ol>\r\n\r\n<p><strong>FOREMAN Shift Malam:</strong><br />\r\nDeni n, Theodorus s, Irfandi ode, Budi s, Stewani t<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><u><strong>PELAKSANA</strong></u></p>\r\n\r\n<p><strong>FOREMAN</strong>: Elfin hadi s, Abdul rahman, Septian dwi w, Abdu m hamid, Elfin hadi s<br />\r\n<br />\r\n<strong>SPV</strong>: Ardiles Teken</p>\r\n', '1768354391_WhatsApp Image 2026-01-13 at 20.35.53.jpeg', '2026-01-13 21:03:06', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(84, 0, 1, 13, 'BA Overshift Earthwork Shift Pagi 14/01/2026', '<p>JOB PENDDING:<br />\r\n&bull;&bull;Line 1 masih aktivitas Utara</p>\r\n\r\n<p>&bull;Dozingan titik jatuh sisi dalam arah ke timur dan selatan</p>\r\n\r\n<p>&bull;Loadingan Luar Hauling ke Comp.Ap23</p>\r\n\r\n<ol>\r\n	<li>_Bawah megatower</li>\r\n	<li>_Cv 10 parkir</li>\r\n	<li>_Jalan belakang ws(alternative) kondisi TL belum tersedia</li>\r\n</ol>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&bull;&bull;Line 2 selatan Full Hauling _Cp23 _Elevasi 60 _Batress Bp89</p>\r\n\r\n<p>&bull;&bull;Konstruksi Batu elevasi 90 jika man power Cukup dan Hauling ke jalan 70 Bp89 barat<br />\r\n<br />\r\n<br />\r\nMANPOWER:<br />\r\n&nbsp;</p>\r\n\r\n<ol>\r\n	<li>Exavator:18</li>\r\n	<li>BuldoSer:19</li>\r\n	<li>Dumptruck:22</li>\r\n	<li>LT-LV:3</li>\r\n	<li>Compactor:4</li>\r\n	<li>WT:_ tidak beroperasi</li>\r\n	<li>Cheker:11</li>\r\n	<li>Pengawas:4</li>\r\n	<li>Spv:1</li>\r\n</ol>\r\n\r\n<p>FOREMAN:</p>\r\n\r\n<p>_Abdu M hamid _A rahman _Elvin Hadi _Septiawan Dwi<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN PELAKSANA:</p>\r\n\r\n<p>_Stewani T</p>\r\n\r\n<p>_Budi S</p>\r\n\r\n<p>_Irfandi</p>\r\n\r\n<p>_M syafaat</p>\r\n\r\n<p>_Deni N<br />\r\n<br />\r\n<br />\r\nSPV: Nanang Koswara<br />\r\n&nbsp;</p>\r\n', '1768468138_WhatsApp Image 2026-01-14 at 07.40.17.jpeg', '2026-01-14 09:08:58', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(85, 0, 1, 28, 'BA Overshift Earthwork Shift Malam 14/01/2026', '<p><strong>JOB PENDDING:</strong><br />\r\n1.line 1 selatan full dosing arah spreadingan ke arah genangan air</p>\r\n\r\n<p>2.line 2 full hauling tailing dumping di komp B dan C P89</p>\r\n\r\n<p>3.kontruksi jalan +70 lipat tailing dan laminating jalan</p>\r\n\r\n<p>4.perbaiakan jalan turunan ipal</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>JUMLAH MANPOWER</strong></p>\r\n\r\n<p>Driver DT : 19 Opr Exca : 13 Opr Dozer : 17 Opr Compec : 4 Driver LT/LV : 2 Cheker : 8 Foreman : 5 Spv 1</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>FOREMAN</strong></p>\r\n\r\n<p>Denin Stewani t Budi s Irfandi ode Safaat umar</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>FOREMAN PELAKSANA</strong></p>\r\n\r\n<p>Abdul rahman Septian dwi w Abdu m hamid Theodorus s Elfin hadi s<br />\r\n<br />\r\n<strong>SPV</strong>: Ardyles Teken</p>\r\n', '1768468357_WhatsApp Image 2026-01-14 at 19.59.08.jpeg', '2026-01-14 20:12:37', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(86, 0, 1, 13, 'BA Overshift Earthwork Shift Pagi 15/01/2026', '<p><strong>JOB PENDING:</strong><br />\r\n&bull;Line 1 rilis diselatan,Full dozingan ke arah utara</p>\r\n\r\n<p>&bull;Line 2 selatan,Full Hauling ke C89/Bp89/pelebaran Jalan 70</p>\r\n\r\n<p>&bull;Hauling batu sengigi ke Batress Bp89</p>\r\n\r\n<p>&bull;Cut Tailing Bawah megatower dan titik jatuh apabila ada unit lebih</p>\r\n\r\n<p>&bull;Konstrusksi jalan 70 ke arah utara<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>JUMLAH MANPOWER</strong></p>\r\n\r\n<ul>\r\n	<li>Operator exavator:18</li>\r\n	<li>buldozer:17</li>\r\n	<li>Compactor:5</li>\r\n	<li>Driver DT:22</li>\r\n	<li>Driver LT/WT:3</li>\r\n	<li>Cheker:11</li>\r\n	<li>Pengawas:4</li>\r\n	<li>Spv:1</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>FOREMAN</strong></p>\r\n\r\n<p>1.A rahman</p>\r\n\r\n<p>2.Elvin Hadi</p>\r\n\r\n<p>3.Septiawan Dwi</p>\r\n\r\n<p>4.Abdu M hamid<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>FOREMAN PELAKSANA</strong></p>\r\n\r\n<p>1.Stewani T</p>\r\n\r\n<p>2.Budi setiawan</p>\r\n\r\n<p>3.Irfandi Ode</p>\r\n\r\n<p>4.M syafaat u<br />\r\n<br />\r\n<strong>SPV</strong>:Nanang Koswara</p>\r\n', '1768468831_WhatsApp Image 2026-01-15 at 09.17.02.jpeg', '2026-01-15 09:20:31', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(87, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 16/01/2026', '<p><strong>Update 16 Januari 2026:&nbsp;</strong></p>\r\n\r\n<p><br />\r\n<strong>Line 1 ke Line 1 Selatan :</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p>jika Kondisi Emergency Line 1 ke line 1 utara &nbsp; =</p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop&nbsp;</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Arah dorongan titik terendah</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen B P89 dari Butre B P89 arah dorongan ke utara</li>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari buttress B : &nbsp;arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari buttress B : &nbsp;arah dorongan ke Selatan</li>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 16 January 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 trimingan 60 Tengah : elevasi 61-61.5</li>\r\n	<li>- Kompartemen B P89 trimingan 60 ujung : elevasi 63 - 64</li>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi 83-67</li>\r\n	<li>- Kompartemen C P89 Dari buttres C P89 : elevasi 71-70</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '', '2026-01-16 09:35:36', 'Tailing Facility Planning', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(88, 0, 1, 28, 'BA Overshift Earthwork Shift Malam 15/01/2026', '<p><strong>Job Pendding:</strong></p>\r\n\r\n<ol>\r\n	<li>1.line 1 selatan full dosing arah spreading ke utara barat menekan air</li>\r\n	<li>2.line 2 hauling tailing ke komp B dan C P89</li>\r\n	<li>3.lipat tailing dan laminating jalan +70</li>\r\n	<li>4.perbaikan jalan turunan ipal</li>\r\n</ol>\r\n\r\n<p><strong>Jumlah Manpower:</strong></p>\r\n\r\n<p>Driver DT : 16</p>\r\n\r\n<p>Opr Exca : 12</p>\r\n\r\n<p>Opr Dozer : 15</p>\r\n\r\n<p>Opr Compec : 3</p>\r\n\r\n<p>Driver LT/LV : 2</p>\r\n\r\n<p>Cheker : 7</p>\r\n\r\n<p>Foreman : 4</p>\r\n\r\n<p>Spv 1<br />\r\n<br />\r\n<strong>Foreman</strong>:&nbsp;</p>\r\n\r\n<p>Stewani T Budi s Irfandi ode Safaat umar<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>FOREMAN PELAKSANA</strong></p>\r\n\r\n<p>Abdul rahman Septian dwi w Theodorus s Elfin hadi s<br />\r\nSPV: Ardyles Teken</p>\r\n\r\n<p><br />\r\n&nbsp;</p>\r\n', '1768617596_WhatsApp Image 2026-01-15 at 21.29.53.jpeg', '2026-01-15 20:39:56', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(89, 0, 1, 13, 'BA Overshift Earthwork Shift Pagi 16/01/2026', '<p><strong>Job Pendding:</strong><br />\r\n1.Line 1 selatan Full Hauling ke arah genangan air dan ke utara untuk bentuk banch 70</p>\r\n\r\n<p>2.Line 2 selatan Full Hauling ke Comp.B/Cp89</p>\r\n\r\n<p>&bull;Elevasi 60 ujung</p>\r\n\r\n<p>&bull;Elevasi tengah</p>\r\n\r\n<p>3.DT sisa Hauling batu sengigi untuk up batrees Bp89</p>\r\n\r\n<p>4.Cut tailing Bekas titik jatuh line1 selatan ke rencana elevasi 60-65 dan hasil cuttingan dozing ke arah Utara(Tumpuk)<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>JUMLAH MANPOWER</strong></p>\r\n\r\n<p>1.Driver DT :19</p>\r\n\r\n<p>2.LT/LV/WT:3</p>\r\n\r\n<p>3.Exavator:18</p>\r\n\r\n<p>4.Buldozer:15</p>\r\n\r\n<p>5.Compactor:4</p>\r\n\r\n<p>6.Cheker:9</p>\r\n\r\n<p>7.Pengawas:4</p>\r\n\r\n<p>8.Spv:1<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>FOREMAN</strong></p>\r\n\r\n<p>1.A rahman</p>\r\n\r\n<p>2.Abdu M hamid</p>\r\n\r\n<p>3.Deni N</p>\r\n\r\n<p>4.Theodorus</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>FOREMAN PELAKSANA</strong></p>\r\n\r\n<ol>\r\n	<li>Budi s</li>\r\n	<li>Elvin H</li>\r\n	<li>M syafaat U</li>\r\n	<li>Irfandi Ode</li>\r\n</ol>\r\n\r\n<p>SPV: Nanang Koswara<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>CATATAN:</strong><br />\r\nUnit BD</p>\r\n\r\n<ul>\r\n	<li>Buldozer:17</li>\r\n	<li>Compactor:2</li>\r\n	<li>DT:2</li>\r\n	<li>Exavator: -&nbsp;</li>\r\n	<li>Greader:1</li>\r\n</ul>\r\n\r\n<p>Unit ready ada di laporan wag<br />\r\n&nbsp;</p>\r\n', '1768617971_WhatsApp Image 2026-01-16 at 10.03.56.jpeg', '2026-01-16 08:46:11', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(90, 0, 1, 28, 'BA Overshift Earthwork Shift Malam 16/01/2026', '<p><strong>JOB PENDING:</strong><br />\r\n1.line 1 selatan full.dosing arah spreadingan ke utara melibas genangan air</p>\r\n\r\n<p>2.line 2 full hauling dumpingan tailinh di komp C P23,,komp B dan C P89</p>\r\n\r\n<p>3.kontruksi butresss B P89 4.lipat dan dosing tailing komp B di bawah bekas titik jatuh line 1 selatan lama<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>JUMLAH MANPOWER</strong></p>\r\n\r\n<ol>\r\n	<li>Driver DT : 17 Opr</li>\r\n	<li>Exca : 14 Opr Dozer : 15</li>\r\n	<li>Opr Compec : 3</li>\r\n	<li>Driver LT/LV : 2</li>\r\n	<li>Cheker : 7</li>\r\n	<li>Foreman : 4</li>\r\n	<li>Spv 1</li>\r\n</ol>\r\n\r\n<p><strong>FOREMAN</strong></p>\r\n\r\n<p>Elfin hadi s, Budi s , Irfandi ode, Safaat umar<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>FOREMAN PELAKSANA</strong></p>\r\n\r\n<p>Abdul rahman, Septian dwi w, Deni nugraha, Theodorus sitohang, Abdu m hamid</p>\r\n', '1768619579_WhatsApp Image 2026-01-16 at 20.47.57.jpeg', '2026-01-16 20:12:59', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(95, 0, 1, 13, 'BA Overshift Earthwork Shift Pagi 17/01/2026', '<p><strong>JOB PENDDING:</strong><br />\r\n1.Line 1 selatan Full Dozingan ke sisi genangan air</p>\r\n\r\n<p>2.Line 2 selatan Full Hauling ke area &bull;Cp89 dari arah jalan 60 dekat batress C ke arah timur</p>\r\n\r\n<ul>\r\n	<li>Cp89 dari arah jalan 60 sebelum turun Bp89</li>\r\n	<li>Cp23 arah dozingan ke utara dan timur</li>\r\n</ul>\r\n\r\n<p>3.Batu sengigi untuk naikkan batress Bp89</p>\r\n\r\n<p>4.CUT area titik jatuh line1 selatan dan dosingan ke arah utara(sebelum area titik jatuh)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>CUACA:</p>\r\n\r\n<p>Hujan jam 10.15-11.30 (kondisi akses aman)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>CATATAN:</strong></p>\r\n\r\n<p>&bull;Apabila kondisi Hujan dan jalan sengigi licin,alihkan unit loading batu 102 ONC</p>\r\n\r\n<p>&bull;Batu elevasi 90 untuk maintenence jalan jika di butuhkan</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>JUMLAH MANPOWER</strong></p>\r\n\r\n<p>1.Operator Buldoser:16</p>\r\n\r\n<p>2.Operator Exavator:17</p>\r\n\r\n<p>3.DRiver DT:24</p>\r\n\r\n<p>4.Compactor:4</p>\r\n\r\n<p>5.LT/LV:3</p>\r\n\r\n<p>6.WT:1</p>\r\n\r\n<p>7.Cheker:7</p>\r\n\r\n<p>8.Pengawas:5</p>\r\n\r\n<p>9.SpV:1<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>FOREMAN</strong></p>\r\n\r\n<ol>\r\n	<li>A rahman</li>\r\n	<li>Deni N</li>\r\n	<li>Septiawan Dwi</li>\r\n	<li>Theodorus S</li>\r\n</ol>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>FOREMAN PELAKSANA</strong></p>\r\n\r\n<ol>\r\n	<li>1.Elvin Hadi</li>\r\n	<li>2.Abdu M hamid</li>\r\n	<li>3.Stewani T</li>\r\n	<li>4.Irfandi</li>\r\n	<li>5.M syafaat</li>\r\n</ol>\r\n', '1768642728_WhatsApp Image 2026-01-17 at 09.43.53.jpeg', '2026-01-17 08:38:48', 'Earthwork', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(96, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 17/01/2026', '<p><strong>Update 17 Januari 2026:&nbsp;</strong></p>\r\n\r\n<p><br />\r\n<strong>Line 1 ke Line 1 Selatan :</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p>jika Kondisi Emergency Line 1 ke line 1 utara &nbsp; =</p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop&nbsp;</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Arah dorongan titik terendah</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 17 January 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 trimingan 60 Tengah : elevasi 61-61.5</li>\r\n	<li>- Kompartemen B P89 trimingan 60 ujung : elevasi 63 - 64</li>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi 83-67</li>\r\n	<li>- Kompartemen C P89 Dari buttres C P89 : elevasi 71-70</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '', '2026-01-17 10:00:25', 'Tailing Facility Planning', '2026-01-18 00:03:42', NULL, 'pending', NULL, NULL),
(112, 0, 1, 28, 'BA Overshift Earthwork Shift Pagi 18/01/2026', '<p><span class=\"marker\"><strong>Job Pendding:</strong><br />\r\n1.line 1 selatan full dosinga arah spreadingan ke utara menekan air </span></p>\r\n\r\n<p><span class=\"marker\">2.line 2 full hauling dumping tailing ke kompnC P23,Komp B dan C P89 </span></p>\r\n\r\n<p><span class=\"marker\">3.kontruksi butress B P89 4.lipat dan spreading tailing bekas titik jatuh line 1 selatan</span><br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><span class=\"marker\"><strong>JUMLAH MANPOWER</strong></span></p>\r\n\r\n<p><span class=\"marker\">Driver DT/WT=25 orang </span></p>\r\n\r\n<p><span class=\"marker\">Opr excavator 17 orang </span></p>\r\n\r\n<p><span class=\"marker\">Opr bulldozer 17 orang </span></p>\r\n\r\n<p><span class=\"marker\">Opr compactor 5 orang </span></p>\r\n\r\n<p><span class=\"marker\">Driver LT 2 orang </span></p>\r\n\r\n<p><span class=\"marker\">Cheker 6 orang </span></p>\r\n\r\n<p><span class=\"marker\">Foreman 4 orang </span></p>\r\n\r\n<p><span class=\"marker\">Supervisor 1 orang</span><br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><span class=\"marker\">FOREMAN</span></p>\r\n\r\n<p><span class=\"marker\">Septian dwi w Deni nugraha Theodorus s Budi setiawan</span><br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><span class=\"marker\">FOREMAN PELAKSANA</span></p>\r\n\r\n<p><span class=\"marker\">Stewani t Elfin hadi s Irfandi ode Abdu m hamid Safaat umar<br />\r\n<br />\r\nSPV: Ardiles Teken</span></p>\r\n', '1768728922_WhatsApp Image 2026-01-18 at 08.12.46.jpeg', '2026-01-18 09:35:22', 'Earthwork', '2026-01-18 09:35:22', NULL, 'pending', NULL, NULL),
(114, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 18/01/2026', '<p><strong>Line 1 ke Line 1 Selatan :</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p>jika Kondisi Emergency Line 1 ke line 1 utara &nbsp; =</p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop&nbsp;</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Arah dorongan titik terendah</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 18 January 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 trimingan 60 Tengah : elevasi 61-61.5</li>\r\n	<li>- Kompartemen B P89 trimingan 60 ujung : elevasi 63 - 64</li>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi 83-67</li>\r\n	<li>- Kompartemen C P89 Dari buttres C P89 : elevasi 71-70</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1769052652_no-image-icon-6.png', '2026-01-18 09:30:52', 'Tailing Facility Planning', '2026-01-22 03:31:14', NULL, 'pending', NULL, NULL),
(115, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Pagi 19/01/2026', '<p><span style=\"font-family:Comic Sans MS,cursive\">DAILY REPORT TIM GEOTECH</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">1. Pekerjaan Hari Ini</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Uji Kepadatan Area P89</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Monitoring lereng terutama titik jatuh Line 1 dan Line 2</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- CPTu ready to test for tomorrow</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Pengujian di lab fokus konsolidasi dan pengambilan filterpress line 1 dan line 2</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Pengecoran lantai bawah tangga done dan dilanjutkan dengan pengeramikan ruang apd baru</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">2. Temuan dan Info Hari ini</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Line 2 menggunung dan perlu monitoring</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Line 1 masih fokus dozingan arah utara untuk mendorong air</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- 2 titik point survey area titik jatuh lama diambil (karena akan dibongkar untuk mengurangi tumpukan)</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Tatakan titik jatih line 1 lama akan ditambah lagi layer kurang lebih 50 cm</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Buttress B P89 dilanjut dengan batu perimeter</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Penambahan tailing untuk pelebaran buttress b p89 sisi timur</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">3. Job Pending</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Input foto filterpress</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Pencampuran air proctor</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Pengambilan, progress, dan foto filterpress</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Monitoring titik jatuh line 1 dan line</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Konstruksi buttress B P89 dan compact maksimal</span></p>\r\n\r\n<p><span style=\"font-family:Comic Sans MS,cursive\">- Fill tailing untuk pelebaran buttress</span></p>\r\n', '1768811368_LINE 2 - 18 JANUARI 2026.jpg', '2026-01-19 08:29:51', 'Instrument & Geotechnical', '2026-01-19 08:29:51', NULL, 'pending', NULL, NULL),
(116, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 19/01/2026', '<p><strong>Line 1 ke Line 1 Selatan :</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p>jika Kondisi Emergency Line 1 ke line 1 utara &nbsp; =</p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop&nbsp;</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Arah dorongan titik terendah</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 19 January 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 trimingan 60 Tengah : elevasi 61-61.5</li>\r\n	<li>- Kompartemen B P89 trimingan 60 ujung : elevasi 63 - 64</li>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi 83-67</li>\r\n	<li>- Kompartemen C P89 Dari buttres C P89 : elevasi 71-70</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1769052542_no-image-icon-6.png', '2026-01-18 19:29:02', 'Tailing Facility Planning', '2026-01-22 03:30:02', NULL, 'pending', NULL, NULL),
(117, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 20/01/2026', '<p><strong>Line 1 ke Line 1 Selatan :</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p>jika Kondisi Emergency Line 1 ke line 1 utara &nbsp; =</p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop&nbsp;</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Arah dorongan titik terendah</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 20 January 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 trimingan 60 Tengah : elevasi 61-61.5</li>\r\n	<li>- Kompartemen B P89 trimingan 60 ujung : elevasi 63 - 64</li>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi 83-67</li>\r\n	<li>- Kompartemen C P89 Dari buttres C P89 : elevasi 71-70</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '', '2026-01-20 09:41:04', 'Tailing Facility Planning', '2026-01-20 09:41:04', NULL, 'pending', NULL, NULL),
(118, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 21/01/2026', '<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<p>jika Kondisi Emergency Line 1 ke line 1 utara &nbsp; =</p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah (Opsi jika Emergency)</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 21 January 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 87- elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 Dari buttres C P89 turunan jalan 70 : elevasi 71-70</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '', '2026-01-21 09:37:32', 'Tailing Facility Planning', '2026-01-21 09:37:32', NULL, 'pending', NULL, NULL),
(120, 0, 1, 13, 'BA Overshift Earthwork Shift Malam 18/01/2026', '<p>JOB PENDDING:<br />\r\n1.Line 1 selatan,Skema pekerjaan masih full dozing ke arah genangan air</p>\r\n\r\n<p>2.Line 2 selatan Full Hauling ke B/Cp89 dan Cp23</p>\r\n\r\n<p>3.Hauling batu sengigi untuk up batrees Bp89</p>\r\n\r\n<p>4.Breker dan lipat batu untuk kebutuhan bukit perimeter ipal</p>\r\n\r\n<p>5.Cut comp.Bp89 barat untuk persiapan area spreadingan doser</p>\r\n\r\n<p>6.Maintenence dan pelebaran jalan turunan Bp89<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>JUMLAH MANPOWER</p>\r\n\r\n<p>1.operator Buldoser:14</p>\r\n\r\n<p>2.operator Exavator:14</p>\r\n\r\n<p>3.operator Compactor:3</p>\r\n\r\n<p>4.Driver DT:20</p>\r\n\r\n<p>5.Driver LT:1</p>\r\n\r\n<p>6.Driver WT:-</p>\r\n\r\n<p>7.Motor Greader:-(BD)</p>\r\n\r\n<p>8.Pengawas:5</p>\r\n\r\n<p>9.Cheker:6<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN</p>\r\n\r\n<p>1.Stewani T</p>\r\n\r\n<p>2.Abdu M hamid</p>\r\n\r\n<p>3.M syafaat U</p>\r\n\r\n<p>4.Irfandi ode</p>\r\n\r\n<p>5.Elvin Hadi<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN PELAKSANA</p>\r\n\r\n<p>1.A rahman</p>\r\n\r\n<p>2.Budi s</p>\r\n\r\n<p>3.Deni N</p>\r\n\r\n<p>4.Septiawan Dwi<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>SUPERVISOR</p>\r\n\r\n<p>Nanang K</p>\r\n', '1769053336_WhatsApp Image 2026-01-18 at 20.54.30.jpeg', '2026-01-18 20:44:05', 'Earthwork', '2026-01-22 03:45:27', NULL, 'pending', NULL, NULL),
(121, 0, 1, 28, 'BA Overshift Earthwork Shift Pagi 19/01/2026', '<p>JOB PENDDING:<br />\r\n<br />\r\n1.line 1 selatan full.dosing spreading ke arah air</p>\r\n\r\n<p>2.line selatan full hauling dan dumping di komp C P23,komp B dan C P89</p>\r\n\r\n<p>3.lipat tailing titik jatuh line 1 selatan lama</p>\r\n\r\n<p>4.kontruksi butress B P89<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>JUMLAH MANPOWER</p>\r\n\r\n<p>Driver DT : 22</p>\r\n\r\n<p>Opr Exca : 17</p>\r\n\r\n<p>Opr Dozer : 15</p>\r\n\r\n<p>Opr Compec : 4</p>\r\n\r\n<p>Driver LT/LV : 2</p>\r\n\r\n<p>Driver WT : 1</p>\r\n\r\n<p>Cheker : 10</p>\r\n\r\n<p>Foreman : 5</p>\r\n\r\n<p>Spv 1<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN</p>\r\n\r\n<p>Abdul rahman Deni nugraha Septian dwi w Budi s Theodorus s<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN PELAKSANA</p>\r\n\r\n<p>Stewani t Abdu m hamid Safaat umar Elfin hadi s<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>SUPERVISOR</p>\r\n\r\n<p>Ardyles teken</p>\r\n\r\n<p><br />\r\n&nbsp;</p>\r\n', '1769053877_WhatsApp Image 2026-01-19 at 07.54.14.jpeg', '2026-01-19 07:51:42', 'Earthwork', '2026-01-22 03:52:52', NULL, 'pending', NULL, NULL),
(122, 0, 1, 13, 'BA Overshift Earthwork Shift Malam 19/01/2026', '<p>JOB PENDDING:</p>\r\n\r\n<ol>\r\n	<li>1.Line 1 Selatan Skema Full Spreading ke arah genangan air</li>\r\n	<li>2.Line 2 selatan Full Hauling ke comp.B/CP89 dan di comp.Cp23</li>\r\n	<li>3.Batu sengigi Untuk Up batress Bp89</li>\r\n	<li>4.Cut bukit perimeter timur dan turunkan batu ke bawah</li>\r\n	<li>5.Cut Tailing comp.Bp89 barat</li>\r\n	<li>6.Maintenence akses yang krusial</li>\r\n	<li>7.Penyampaian k3 saat briefing<br />\r\n	&nbsp;</li>\r\n</ol>\r\n\r\n<p>JUMLAH MANPOWER</p>\r\n\r\n<ul>\r\n	<li>1.Exavator:15</li>\r\n	<li>2.Buldoser:15</li>\r\n	<li>3.Compactor:4</li>\r\n	<li>4.Driver DT:19</li>\r\n	<li>5.Driver WT:-</li>\r\n	<li>6.Driver LT:1</li>\r\n	<li>7.Greader:-BD</li>\r\n	<li>8.Cheker:7</li>\r\n	<li>9.Pengawas:3</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<ul>\r\n	<li>Unit exavator 300 di titik jatuh Line1 selatan akhir shift mengalami kendala,sehingga material ada menumpuk</li>\r\n	<li>Cylcle Time DT line2 kurang maksimal berhubung kondisi jalan hauling rusak pasca hujan</li>\r\n	<li>Maintenence jalan beberapa titik tidak maksimal karena unit exavator kurang</li>\r\n	<li>Cuttingan titik 1 selatan unit jam 21.30 di pindahkan ke Elevasi 90 Loading batu kualitas bagus untuk laminating akses</li>\r\n</ul>\r\n\r\n<p>FOREMAN</p>\r\n\r\n<p>1.Stewani T</p>\r\n\r\n<p>2.Abdu M hamid</p>\r\n\r\n<p>3.Elvin Hadi<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN PELAKSANA</p>\r\n\r\n<p>1.A rahman</p>\r\n\r\n<p>2.Budi S</p>\r\n\r\n<p>3.Irfandi</p>\r\n\r\n<p>4.Deni N</p>\r\n\r\n<p>5.Theodorus s<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>SUPERVISOR</p>\r\n\r\n<p>Nanang K</p>\r\n', '1769054513_WhatsApp Image 2026-01-19 at 19.05.44.jpeg', '2026-01-19 20:01:53', 'Earthwork', '2026-01-22 04:02:35', NULL, 'pending', NULL, NULL),
(123, 0, 1, 28, 'BA Overshift Earthwork Shift Pagi 20/01/2026', '<p>JOB PENDDING:<br />\r\n1.line 1 selatan full dosing arah spreadingan ke arah genangan air</p>\r\n\r\n<p>2.line 2 full hauling dumping tailing di komp CP23.Bdan C P89</p>\r\n\r\n<p>3.kontruksi butress B pake batu 102 HPAL</p>\r\n\r\n<p>4.lipat tailing titik jatuh line 1 selatan lama<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>JUMLAH MANPOWER&nbsp;</p>\r\n\r\n<p>Driver DT : 24 Opr Exca : 16 Opr Dozer : 16 Opr Compec : 6 Driver LT/LV : 2 Cheker : 11 Foreman : 5 Spv 1<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN</p>\r\n\r\n<p>Abdul rahman Deni nugraha Theodorus s Budi s Irfandi ode<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN PELAKSANA</p>\r\n\r\n<p>Stewani T Elfin hadi s Abdu m hamid Septian dwi w<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>SUPERVISOR</p>\r\n\r\n<p>Ardyles teken</p>\r\n', '1769054817_WhatsApp Image 2026-01-20 at 08.24.04.jpeg', '2026-01-20 07:06:57', 'Earthwork', '2026-01-22 04:07:23', NULL, 'pending', NULL, NULL);
INSERT INTO `berita` (`id_berita`, `iduser`, `id_kategori`, `id_user`, `judul`, `isi_berita`, `gambar`, `tgl_posting`, `plan`, `updated_at`, `deleted_at`, `status`, `approved_by`, `approved_at`) VALUES
(124, 0, 1, 13, 'BA Overshift Earthwork Shift Malam 20/01/2026', '<p>JOB PENDDING<br />\r\n<br />\r\n1.Line 1</p>\r\n\r\n<p>&bull;Opsi Utara,Hauling ke megatower dan belakang ws</p>\r\n\r\n<p>&bull;Opsi selatan masih sama rekomendasi minggu kemarin untuk area Spreadingan</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>2.Line 2 Full hauling ke comp.Cp89 dan Cp23,skema dosingan mengikuti planning sebelumnya</p>\r\n\r\n<p>3.Kontruksi Batress apabila Ketersedian unit ada dan akses k sengigi aman</p>\r\n\r\n<p>4.Konstruksi rencana area titik jatuh line2 di Bp89</p>\r\n\r\n<p>5.Cut perimeter timur ipal dan Sidecast batu ke area loadingan<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>&bull;Batu sengigi Hold berhubung akses tidak aman</p>\r\n\r\n<p>&bull;Akses Hauling kurang maksimal berhubung pasca hujan<br />\r\n<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>JUMLAH MANPOWER</p>\r\n\r\n<p>Operator 1.Exavator:16</p>\r\n\r\n<p>2.Buldozer:15</p>\r\n\r\n<p>3.Compactor:3</p>\r\n\r\n<p>4.Greader:-BD</p>\r\n\r\n<p>5.Driver DT:22</p>\r\n\r\n<p>6.Driver WT:_</p>\r\n\r\n<p>7.Driver LT:2</p>\r\n\r\n<p>8.Cheker:7</p>\r\n\r\n<p>9.Pengawas:4<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN</p>\r\n\r\n<p>1.Abdu M hamid</p>\r\n\r\n<p>2.Elvin Hadi</p>\r\n\r\n<p>3.Septiawan dwi</p>\r\n\r\n<p>4.Stewani T<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN PELAKSANA</p>\r\n\r\n<p>1.A rahman</p>\r\n\r\n<p>2.Budi s</p>\r\n\r\n<p>3.Deni N</p>\r\n\r\n<p>4.Irfandi ode</p>\r\n\r\n<p>5.M syafaat u<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>SUPERVISOR</p>\r\n\r\n<p>Nanang K</p>\r\n', '1769055034_WhatsApp Image 2026-01-20 at 20.37.12.jpeg', '2026-01-20 20:13:00', 'Earthwork', '2026-01-22 04:13:41', NULL, 'pending', NULL, NULL),
(125, 0, 1, 28, 'BA Overshift Earthwork Shift Pagi 21/01/2026', '<p>JOB PENDING:<br />\r\n<br />\r\n1.line 1 utara arah dosingan ke timir selatan dan hauling ke komp AP23</p>\r\n\r\n<p>2.line 2 full hauling dan dumping tailing di kkmp C P23,butress B P89 dan jalan +60 tengah</p>\r\n\r\n<p>3.lipat tailing titik jatuh line 1 selatan lama<br />\r\n&nbsp;</p>\r\n\r\n<p>JUMLAH MANPOWER</p>\r\n\r\n<p>Driver DT : 24 Opr Exca : 17 Opr Dozer : 13 Opr Compec : 6 Driver LT/LV : 3 Cheker : 8 Foreman : 5 Spv 1<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN</p>\r\n\r\n<p>Abdul rahman Deni nugraha Budi setiawan Safaat umar Irfandi ode</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>PELAKSANA TEAM SHIFT MALAM:<br />\r\n&nbsp;</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>SUPERVISOR</p>\r\n\r\n	<p>Ardyles teken</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN PELAKSANA</p>\r\n\r\n	<p>Stewani t Eldin hadi s Septian dwi w Theodorus s Abdu m hamid</p>\r\n	</li>\r\n</ul>\r\n', '1769055662_WhatsApp Image 2026-01-21 at 08.26.28.jpeg', '2026-01-21 08:21:40', 'Earthwork', '2026-01-22 04:22:31', NULL, 'pending', NULL, NULL),
(126, 0, 1, 13, 'BA Overshift Earthwork Shift Malam 21/01/2026', '<p>JOB PENDDING<br />\r\n<br />\r\n1.Line urara Opsi</p>\r\n\r\n<p>&bull; Hauling ke megatower untuk mengisi material Comp.A ke sisi barat dan belakang ws lama untuk mengisi material jalan ke elevasi 85</p>\r\n\r\n<p>&bull;Lodingan dalam opsi Spreading ke doser dan dosing ke sisi timur</p>\r\n\r\n<p>2.Line 2 selatan Full Hauling ke Comp.Cp23/Bp89/Cp89</p>\r\n\r\n<p>3.Perbaikan akses Hauling</p>\r\n\r\n<p>4.Infokan ke all tim untuk progress area yang menjadi temuan obi portal</p>\r\n\r\n<p>5.Briefing keselamatan ke operator</p>\r\n\r\n<p>6.Support pemindahan TL dari batress Ap89 ke belakang ws<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>JUMLAH MANPOWER</p>\r\n\r\n<p>Operator 1.Buldozer:19</p>\r\n\r\n<p>2.Exavator:15</p>\r\n\r\n<p>3.Compactor:3</p>\r\n\r\n<p>4.Greader:_BD</p>\r\n\r\n<p>5.Driver DT:22</p>\r\n\r\n<p>6.Driver WT-</p>\r\n\r\n<p>7.Driver LT:2</p>\r\n\r\n<p>8.Cheker:7</p>\r\n\r\n<p>9.Pengawas:5<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN</p>\r\n\r\n<p>1.Abdu Hamid</p>\r\n\r\n<p>2.Septiawan Dwi</p>\r\n\r\n<p>3.Elvin Hadi</p>\r\n\r\n<p>4.Stewani</p>\r\n\r\n<p>5.Theodorus S<br />\r\n<br />\r\n<br />\r\nPELAKSANA SHIFT SIANG:</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>SUPERVISOR</p>\r\n\r\n	<p>Nanang K</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN PELAKSANA</p>\r\n\r\n	<p>1.A rahman</p>\r\n\r\n	<p>2.Budi S</p>\r\n\r\n	<p>3.Irfandi Ode</p>\r\n\r\n	<p>4.M syafaat U</p>\r\n	</li>\r\n</ul>\r\n', '1769055928_WhatsApp Image 2026-01-21 at 21.13.34.jpeg', '2026-01-21 20:25:28', 'Earthwork', '2026-01-22 04:25:49', NULL, 'pending', NULL, NULL),
(127, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Pagi 22/01/2026', '<p>Info :&nbsp;</p>\r\n\r\n<p>1. Proses pengolah lindi menggunakan 2 pompa ponton speed 50 %<br />\r\n2. Dosing chemical ferosulfate dan pam dari chemical facility<br />\r\n3. Analisa Laboratorium<br />\r\n4. Sampling beberapa saluran kompartemen p89 ( 5 titik )&nbsp;<br />\r\n5. Perbaikan tangga chemical facility&nbsp;<br />\r\n6. Pembuatan tempat kabel pompa<br />\r\n7. Buka Nota Elbow galvanis 2.5&quot; inch 2 pcs<br />\r\n8. Dosing PDMC di toedrain &nbsp;&nbsp;<br />\r\n9. Penyemprotan kolam 1 pengumpul lindi</p>\r\n\r\n<p>Job pending :</p>\r\n\r\n<p>1. Lanjut pemotongan anak tangga chemical facility<br />\r\n2. â pembuatan tempat kabel di panel pompa&nbsp;<br />\r\n3. â penambahan elbow galvanis pada nozzle penyemprotan kolam yang di pengumpul lindi , (bisa di copot dulu)&nbsp;<br />\r\n4. â sampling dan monitoring</p>\r\n', '1769069398_WhatsApp Image 2026-01-22 at 13.17.10.jpeg', '2026-01-23 00:27:44', 'Waste Water Treatment Plant', '2026-01-23 00:27:44', NULL, 'pending', NULL, NULL),
(128, 0, 1, 28, 'BA Overshift Earthwork Shift Pagi 22/01/2026', '<p>JOB PENDDING:<br />\r\n1.line 1 utara arah dosingan keselatan dan timur dan hauling tailing ke komp A P23</p>\r\n\r\n<p>2.line 2 full hauling tailings dan dumping di butress B P89,jakan+60 tengah,dan komp C P23</p>\r\n\r\n<p>3.lipat tailings titik jatuh line 1 selatan lama<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>JUMLAH MANPOWER</p>\r\n\r\n<p>Driver DT : 22 Opr Exca : 16 Opr Dozer : 15 Opr Compec : 5 Driver LT/LV : 3 Cheker : 10 Foreman : 5 Spv 1<br />\r\n<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN</p>\r\n\r\n<p>Abdul rahman Budi s Irfandi ode Safaat umar Deni nugraha<br />\r\n&nbsp;</p>\r\n\r\n<p>FOREMAN PELAKSANA</p>\r\n\r\n<p>Stewani t Septian dwi Theodorus s Abdu m hamid<br />\r\n&nbsp;</p>\r\n\r\n<p>SUPERVISOR</p>\r\n\r\n<p>Ardyles teken</p>\r\n', '1769070007_WhatsApp Image 2026-01-22 at 08.09.41.jpeg', '2026-01-22 08:20:07', 'Earthwork', '2026-01-22 08:20:07', NULL, 'pending', NULL, NULL),
(129, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 22/01/2026', '<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<p>jika Kondisi Emergency Line 1 ke line 1 utara &nbsp; =</p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan&nbsp;</li>\r\n	<li>Cutting material area megatower dan menaikan level tanggul di area belakang workshop</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 22 January 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 84 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 Dari buttres C P89 turunan jalan 70 : elevasi 71-70</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1769073939_Screenshot 2026-01-22 182139.png', '2026-01-22 09:33:45', 'Tailing Facility Planning', '2026-01-22 09:33:45', NULL, 'pending', NULL, NULL),
(130, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Pagi 23/01/2026', '<p>Info&nbsp;<br />\r\n- sampling &amp; monitoring&nbsp;<br />\r\n- pembersihan lumpur kolam 1 pengumpul &amp; toedrain&nbsp;<br />\r\n- perbaikan geomembran yang sobek di dinding kolam 1 pengumpul (sisa bagian bawah, level air kolam sudah naik)<br />\r\n- pemasangan pagar rumah genset&nbsp;<br />\r\n- lanjut instalasi panel ATS</p>\r\n\r\n<p><br />\r\nJob pending&nbsp;<br />\r\n- proses&nbsp;<br />\r\n- sampling &amp; monitoring&nbsp;<br />\r\n- pemasangan pagar rumah genser bagian barat depan</p>\r\n', '', '2026-01-23 00:29:10', 'Waste Water Treatment Plant', '2026-01-23 00:29:10', NULL, 'pending', NULL, NULL),
(131, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 01/01/2026', '<p>Info :<br />\r\n- housekeeping chemical facility, tanki fero full output buat keluarannya kecil jadi belum sempat dikuras<br />\r\n- â proses sampai akhir shift&nbsp;<br />\r\n- â sampling dan monitoring&nbsp;<br />\r\n- â dosing pdmc kolam 1,4 dan toedrain&nbsp;<br />\r\n- â kirim email sampel masuk ke enviro</p>\r\n', '', '2026-01-23 00:49:16', 'Waste Water Treatment Plant', '2026-01-23 00:49:16', NULL, 'pending', NULL, NULL),
