(141, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Pagi 06/01/2026', '<p>Info :&nbsp;<br />\r\n- Proses sampai akhir shift<br />\r\n- Dosing toedrain masih lanjut<br />\r\n- Analisa lab<br />\r\n- Sampling dan monitoring<br />\r\n- Pengecekan panel ponton oleh tim eid<br />\r\n- Cat handrail chemical facility<br />\r\n- Stok batu<br />\r\n- Pompa dosing FeSO4 B bermasalah di kelerengnya, masih belum keluar<br />\r\n- List barang gudang 40ft (baru pipa)<br />\r\n- Lem ulang valve jalur air cp1 dan tandor shelter (masih bocor)<br />\r\n<br />\r\n&nbsp;</p>\r\n', '', '2026-01-23 00:55:14', 'Waste Water Treatment Plant', '2026-01-23 00:55:14', NULL, 'pending', NULL, NULL),
