(144, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 07/01/2026', '<p>Info&nbsp;<br />\r\n- proses sampai akhir shift&nbsp;<br />\r\n- pembersihan jalur FeSO4<br />\r\n- sampling &amp; monitoring&nbsp;<br />\r\n- cat tangga bak penampung &amp; saluran chemical facility&nbsp;<br />\r\n- maintenance das out</p>\r\n', '', '2026-01-23 00:57:15', 'Waste Water Treatment Plant', '2026-01-23 00:57:15', NULL, 'pending', NULL, NULL),
