(147, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Pagi 09/01/2026', '<p>Info :<br />\r\n- proses sampai akhir shift (50:50)<br />\r\n- â dosing fero 25 hz aman keluaran sudah normal , bisa menggunakan 40 hz dlu untuk keluarin angin<br />\r\n- â Dosing pdmc kolam 4 dan toedrain&nbsp;<br />\r\n- â analisa laboratorium&nbsp;<br />\r\n- â pengambilan fero sulfat 2 pallet di water intake&nbsp;<br />\r\n- â pengambilan pdmc 2 pallet di TG 2 &nbsp;<br />\r\n- â pembuatan shelter area samping chemical.&nbsp;<br />\r\n- â sampling dan monitoring</p>\r\n\r\n<p>Job pending:<br />\r\n- Turunkan dan susun fero sulfat di gudang chemical 2 palet&nbsp;<br />\r\n- Bikin pagar pintu bak penampung<br />\r\n- â proses sampai akhi shift&nbsp;<br />\r\n- â dosing pdmc&nbsp;<br />\r\n- â sampling dan monitoring<br />\r\n- â laminating jalan samping chemical facility</p>\r\n', '', '2026-01-23 01:01:54', 'Waste Water Treatment Plant', '2026-01-23 01:01:54', NULL, 'pending', NULL, NULL),
