(155, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Pagi 13/01/2026', '<p>Info :</p>\r\n\r\n<ul>\r\n	<li>sampling &amp; monitoring&nbsp;</li>\r\n	<li>analisa lab&nbsp;</li>\r\n	<li>connect kabel exhaust fan gudang chemical (MCB ikut kabel terminal chemical facility)&nbsp;</li>\r\n	<li>instalasi pompa submersible 3.5 kW di toedrain untuk penyiraman lumpur (keluaran aman normal)</li>\r\n	<li>instalasi ulang jalu kabel terminal shelter ibc toedrain&nbsp;</li>\r\n	<li>pembersihan saluran outlet&nbsp;</li>\r\n	<li>pengurasan air didalam ponton 1 (baru 1 sisi)&nbsp;</li>\r\n	<li>pembersihan lumpur kolam 1 pengumpul lindi</li>\r\n	<li>ganti Y Strainer jalur air bersih pengisian tangki chemical facility</li>\r\n</ul>\r\n\r\n<p>Job Pending :</p>\r\n\r\n<ul>\r\n	<li>proses&nbsp;</li>\r\n	<li>sampling &amp; monitoring&nbsp;</li>\r\n	<li>dosing toedrain &amp; kolam 1&nbsp;</li>\r\n	<li>buatkan nozzle untuk penyemprotan dari selang damkar. Bahan nya udah ada di meja tengah kontainer&nbsp;</li>\r\n	<li>maintenance das out</li>\r\n</ul>\r\n', '', '2026-01-23 01:22:26', 'Waste Water Treatment Plant', '2026-01-23 01:22:26', NULL, 'pending', NULL, NULL),
(156, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 13/01/2026', '<p>Info :</p>\r\n\r\n<ul>\r\n	<li>Proses sampai akhir shift</li>\r\n	<li>Dosing PDMC kolam 1 dan toedrain &nbsp;</li>\r\n	<li>Penomoran lampu pju</li>\r\n	<li>Pembuatan Nozzle penyemprotan dari selang damkar</li>\r\n	<li>Pipa strainer di chemical untuk pengisian tangki lepas lagi&nbsp;</li>\r\n	<li>Sampling dan monitoring&nbsp;</li>\r\n	<li>Shift malam operator excavator terbatas jadi tidak ada yang main long arm</li>\r\n</ul>\r\n', '', '2026-01-23 01:25:55', 'Waste Water Treatment Plant', '2026-01-23 01:25:55', NULL, 'pending', NULL, NULL),
(157, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Pagi 14/01/2026', '<p>Info&nbsp;</p>\r\n\r\n<ul>\r\n	<li>Sampling &amp; monitoring&nbsp;</li>\r\n	<li>Analisa lab&nbsp;</li>\r\n	<li>pembersihan lumpur kolam 1 pengumpul lindi&nbsp;</li>\r\n	<li>perbaikan pipa kamar mandi yang bocor (udah aman)&nbsp;</li>\r\n	<li>setting panel ATS, belum selesai. Masih belum ketemu settingan wiring genset nya, besok dilanjut</li>\r\n	<li>Nota kabel selesai ttd, besok diambil&nbsp;</li>\r\n	<li>Nota besi yang lama sudah di cancel&nbsp;</li>\r\n	<li>Buka nota batre ukuran C. Besok ttd ke GA &amp; ambil barang&nbsp;</li>\r\n	<li>besi plat di simpan di atas kontainer gudang selang&nbsp;</li>\r\n	<li>agitator disimpan di gudang mushola&nbsp;</li>\r\n	<li>assessment dari EID &nbsp;penambahan panel sendiri untuk instalasi submersible kolam 5,6,7 bisa di posisikan di bawah dekat tangga biar kontrol &amp; kabel pompa nya ga terlalu panjang&nbsp;</li>\r\n	<li>maintenance DAS out</li>\r\n</ul>\r\n\r\n<p>Job pending&nbsp;</p>\r\n\r\n<ul>\r\n	<li>proses&nbsp;</li>\r\n	<li>pasang keramik kamar mandi (keramik sudah disiapkan)&nbsp;</li>\r\n	<li>buat 1 nozzle lagi untuk di tanggul CP1</li>\r\n</ul>\r\n', '', '2026-01-23 01:30:35', 'Waste Water Treatment Plant', '2026-01-23 01:30:35', NULL, 'pending', NULL, NULL),
(158, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 14/01/2026', '<p>info :<br />\r\n- proses sampai akhir shift<br />\r\n- Dosing PDMC kolam 1 dan toedrain &nbsp;<br />\r\n- pemasangan keramik kamar mandi<br />\r\n- pembuatan Nozzle &nbsp;penyemprotan dari selang damkar belum dengan gagang&nbsp;<br />\r\n- sampling dan monitoring</p>\r\n', '', '2026-01-23 01:38:12', 'Waste Water Treatment Plant', '2026-01-23 01:38:12', NULL, 'pending', NULL, NULL),
(159, 0, 1, 13, 'BA Overshift Earthwork Shift Malam 22/01/2026', '<p><strong>JOB PENDDING:</strong></p>\r\n\r\n<ol>\r\n	<li>1.Line 1 selatan(Full Dozing) ke genangan air dan bentuk berm apabila ujung spreadingan aman ke dalam genangan air</li>\r\n	<li>2.Line 2 selatan((Full Hauling) ke comp.B-Cp89 dan Cp23</li>\r\n	<li>3.Konstruksi batrees Bp89</li>\r\n	<li>4.Maintenence jalan yang apabila kondisi cuaca cerah</li>\r\n	<li>5.Cut titik jatuh utara untuk perapian dan dozing ke sisi selatan apabila unit tersedia</li>\r\n	<li>6.Cut comp.Bp89 barat titik jatuh lama jika unit tersedia</li>\r\n</ol>\r\n\r\n<p><strong>JUMLAH MANPOWER</strong></p>\r\n\r\n<ol>\r\n	<li>1.Exavator:16</li>\r\n	<li>2.Buldoser:16</li>\r\n	<li>3.Compactor:4</li>\r\n	<li>4.Driver DT:22</li>\r\n	<li>5.Driver LT:1</li>\r\n	<li>6.WT:1</li>\r\n	<li>7.Cheker:7</li>\r\n	<li>8.Pengawas:4</li>\r\n</ol>\r\n\r\n<p><strong>TEMUAN</strong></p>\r\n\r\n<p>&bull;Ketersedian Unit BD masih signifikan,sehingga tonase produksi tidak balance dengan operasional</p>\r\n\r\n<p><strong>NOTE:</strong></p>\r\n\r\n<p>&bull;Tanggul jalan 70 perlu di bentuk safety berm untuk close temuan &bull;Turunan ipal perlu setting grade jalannya menghindari saat hujan air melimpas ke area ipal</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>FOREMAN</strong></p>\r\n\r\n<p>1.Abdu Hamid</p>\r\n\r\n<p>2.Septiawan dwi</p>\r\n\r\n<p>3.Theodorus S</p>\r\n\r\n<p>4.Stewani T</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>PELAKSANA:</strong></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>SUPERVISOR: Nanang K</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN PELAKSANA</p>\r\n\r\n	<p>1.Budi S</p>\r\n\r\n	<p>2.A rahman</p>\r\n\r\n	<p>3.M syafaat U</p>\r\n	</li>\r\n</ul>\r\n', '1769134146_WhatsApp Image 2026-01-22 at 20.00.34.jpeg', '2026-01-22 20:16:50', 'Earthwork', '2026-01-23 09:44:18', NULL, 'approved', 28, '2026-01-23 07:16:50'),
