(174, 0, 1, 28, 'BA Overshift Earthwork Shift Pagi 23/01/2026', '<p><strong>JOB PENDDING:</strong><br />\r\n1.line 1 selatan full dosing arah dosingan ke arah air membentuk tanggul</p>\r\n\r\n<p>2.line 2 full hauling tailing dumping di komp C P23(2 ttk)butress B P89=(1 ttk) Dan jalan+60 tengah (2 ttk)</p>\r\n\r\n<p>3.kontruksi butress B sisi barat</p>\r\n\r\n<p>4.pembuatan tanggul sd +90 depan workshop baru<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>FOREMAN</p>\r\n\r\n	<p>Safaat umar Budi s Abdul rahman</p>\r\n	</li>\r\n	<li>\r\n	<p>JUMLAH MANPOWER</p>\r\n\r\n	<p>Driver DT : 23 Opr Exca : 18 Opr Dozer : 17 Opr Compec : 5 Driver LT/LV : 2 Cheker : 11 Foreman : 3 Spv 1</p>\r\n	</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>PELAKSANA SHIFT MALAM:</strong></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>SUPERVISOR</p>\r\n\r\n	<p>Ardyles teken</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN&nbsp;</p>\r\n\r\n	<p>Stewani T Seprian dwi w Theodorus s Deni nugraha</p>\r\n	</li>\r\n</ul>\r\n', '1769157048_WhatsApp Image 2026-01-23 at 09.28.58.jpeg', '2026-01-23 09:21:10', 'Earthwork', '2026-01-23 09:21:10', NULL, 'approved', 13, '2026-01-23 18:21:10'),
(175, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Pagi 23/01/2026', '<p>Info :&nbsp;</p>\r\n\r\n<ul>\r\n	<li>Proses Menggunakan 2 pompa&nbsp; (speed 50:50)&nbsp;</li>\r\n	<li>Analisa Laboratorium&nbsp;</li>\r\n	<li>Sampling dan monitoring&nbsp;</li>\r\n	<li>Pembacaan Vnotch&nbsp;</li>\r\n	<li>Perbaikan tangga chemical facility&nbsp;</li>\r\n	<li>Pengambilan besi siku dari B60 dan N1&nbsp;</li>\r\n</ul>\r\n', '1769157852_WhatsApp Image 2026-01-23 at 11.22.03.jpeg', '2026-01-23 08:44:12', 'Waste Water Treatment Plant', '2026-01-23 08:44:12', NULL, 'pending', NULL, NULL),
(176, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 23/01/2026', '<p><strong>Line 1 ke Line 1 Selatan :</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p>jika Kondisi Emergency Line 1 ke line 1 utara &nbsp; =</p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan&nbsp;</li>\r\n	<li>Cutting material area megatower dan menaikan level tanggul di area belakang workshop (Jika ada Unit Lebih)</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 23 January 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 84 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 Dari buttres C P89 turunan jalan 70 : elevasi 71-70</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1769161577_Screenshot 2026-01-23 184444.jpg', '2026-01-23 09:46:17', 'Tailing Facility Planning', '2026-01-23 09:46:17', NULL, 'pending', NULL, NULL),
(177, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Malam 22/01/2026', '<p>Info<br />\r\n1. Sampling dan monitoring&nbsp;<br />\r\n2. Pembacaan v-notch&nbsp;<br />\r\n3. Selesai pemotongan besi siku anak tangga chemical facility&nbsp;<br />\r\n4. Perapihan kabel yg masuk ke panel chemical facility (tidak perlu buat tempat gulungan kabel)<br />\r\n5. Pengelasan elbow pada nozzle penyemprotan kolam 1 pengumpul lindi utara dan selatan</p>\r\n', '1769168653_WhatsApp Image 2026-01-23 at 06.32.11.jpeg', '2026-01-23 11:44:13', 'Waste Water Treatment Plant', '2026-01-23 11:44:13', NULL, 'pending', NULL, NULL),
(178, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Malam 23/01/2026', '<p>Info<br />\r\n- proses sampai akhir shift, 1 pompa speed 70 (akhir shift sudah tersedot lumpur)<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- penyemprotan area pipa ponton depan toe drain<br />\r\n- cor plester akses bypass timur</p>\r\n\r\n<p>Pengawas : ius</p>\r\n\r\n<p>Jumlah man power : 6 orang</p>\r\n', '1769202172_WhatsApp Image 2026-01-24 at 00.37.57.jpeg', '2026-01-23 21:02:52', 'Waste Water Treatment Plant', '2026-01-23 21:02:52', NULL, 'pending', NULL, NULL),
(179, 0, 1, 13, 'BA Overshift Earthwork Shift Malam 23/01/2026', '<p><strong>Job Pendding:</strong><br />\r\n<br />\r\n1.Line 1 selatan skema Full Dozing ke bawah titik genangan air</p>\r\n\r\n<p>2.Line 2 selatan Full hauling ke Cp23/Cp89/Bp89</p>\r\n\r\n<p>3.Konstruksi Batress Bp89</p>\r\n\r\n<p>4.Cut tailing mega tower dan bentuk tanggul 90 samping ws</p>\r\n\r\n<p>5.Perbaikan grade jalan Hauling di line2 yg berlubang persiapan Hauling saat musim hujan<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>Manpower:</strong></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>FOREMAN</p>\r\n\r\n	<p>1.Stewani T</p>\r\n\r\n	<p>2.Deni N</p>\r\n\r\n	<p>3.Septiawan Dwi</p>\r\n\r\n	<p>4.Theodorus S</p>\r\n	</li>\r\n	<li>\r\n	<p>JUMLAH MANPOWER</p>\r\n\r\n	<p>1.Exavator:16</p>\r\n\r\n	<p>2.Buldoser:15</p>\r\n\r\n	<p>3.Compactor:3</p>\r\n\r\n	<p>4.Greader:BD</p>\r\n\r\n	<p>5.DT:22</p>\r\n\r\n	<p>6.LT/WT:2</p>\r\n\r\n	<p>7.Cheker:7</p>\r\n\r\n	<p>8.pengawasan:5<br />\r\n	<br />\r\n	&nbsp;</p>\r\n\r\n	<p>FOREMAN PELAKSANA</p>\r\n\r\n	<p>1.A rahman</p>\r\n\r\n	<p>2.Budi</p>\r\n\r\n	<p>3.M syafaat u</p>\r\n\r\n	<p>4.Abdu M<br />\r\n	<br />\r\n	SPV: Nanang Koswara</p>\r\n	</li>\r\n</ul>\r\n', '1769223338_WhatsApp Image 2026-01-23 at 20.28.23.jpeg', '2026-01-23 20:55:38', 'Earthwork', '2026-01-24 02:56:07', NULL, 'pending', NULL, NULL),
(180, 0, 1, 28, 'BA Overshift Earthwork Shift Pagi 24/01/2026', '<p>Job Pendding:<br />\r\n<br />\r\n1.line 1 selatan full dosing arah spreadingan ke arah air membentuk tanggul</p>\r\n\r\n<p>2.line 2 full hauling titik dumpingan di komp C P23(2 ttk),komp C(butress B dan jalan+70(dekat titik jatuh)dan jalan +60= 2 Dozer yg di butuhkan 5 unit</p>\r\n\r\n<p>3.lipat tailing membentuk bench+90 depan work shop baru</p>\r\n\r\n<p>4.lipat dan dosing tailing titik line 1 selatan lama(tergantungan ketersedian alat)</p>\r\n\r\n<p>5.kontruski butress B P89 bagian barat sisi selatan</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>FOREMAN</p>\r\n\r\n	<p>Abdul rahman, Safaat uamar, Budi setiawan, Abdu m hamid</p>\r\n	</li>\r\n	<li>\r\n	<p>JUMLAH MANPOWER</p>\r\n\r\n	<ol>\r\n		<li>Driver HDT-HO = 21</li>\r\n		<li>LT/LV = 2</li>\r\n		<li>WT = 1</li>\r\n		<li>Op. Excavator = 17</li>\r\n		<li>Op. Bulldoser = 17</li>\r\n		<li>Op. Compactor = 4</li>\r\n		<li>Checker = 10</li>\r\n		<li>Foreman = 5</li>\r\n		<li>SPV = 1</li>\r\n	</ol>\r\n	</li>\r\n</ul>\r\n\r\n<p>PELAKSANA:</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>PLT SUPERVISOR</p>\r\n\r\n	<p>Septian dwi w</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN PELAKSANA</p>\r\n\r\n	<p>Deni nugraha, Stewani T, Theodorus s</p>\r\n	</li>\r\n</ul>\r\n', '1769241341_WhatsApp Image 2026-01-24 at 08.55.28.jpeg', '2026-01-24 07:56:47', 'Earthwork', '2026-01-24 07:56:47', NULL, 'pending', NULL, NULL),
(181, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Pagi 24/01/2026', '<p><strong>Info :&nbsp;</strong></p>\r\n\r\n<ul>\r\n	<li>Analisa Laboratorium&nbsp;</li>\r\n	<li>Sampling dan Monitoring&nbsp;</li>\r\n	<li>Pengecheckan Vnotch outlet pintu air&nbsp;</li>\r\n	<li>Pembuatan modifikasi pompa lumpur&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Note :</strong></p>\r\n\r\n<ul>\r\n	<li>Jonathan tidak masuk ijin sakit&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Job Pending :&nbsp;</strong></p>\r\n\r\n<ul>\r\n	<li>Cor area kabel dekat taman, Sudah dipasang pipa</li>\r\n	<li>Proses sampai akhir shift&nbsp;</li>\r\n	<li>Sampling dan monitoring&nbsp;</li>\r\n	<li>Dosing pdmc pada toedrain&nbsp;</li>\r\n</ul>\r\n', '1769244764_WhatsApp Image 2026-01-24 at 11.43.25.jpeg', '2026-01-24 08:52:44', 'Waste Water Treatment Plant', '2026-01-24 08:52:44', NULL, 'pending', NULL, NULL),
(182, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Pagi 24/01/2026', '<p>1. PROGRESS HARI INI</p>\r\n\r\n<p>- Pengujian Sandcone Kompartemen C P89 dan B P89</p>\r\n\r\n<p>- Preparasi Hidrometer dan Sieve</p>\r\n\r\n<p>- Pengambilan, Photo, dan Progress Sampel Filterpress Line 1 dan Line 2</p>\r\n\r\n<p>- CPTu titik 16</p>\r\n\r\n<p>- Pengujian Konsolidasi</p>\r\n\r\n<p>- Pengujian PPO Kompartemen B P90</p>\r\n\r\n<p>- Konstruksi Buttress B P89</p>\r\n\r\n<p>- Pembersihan Picnometer</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>2. TEMUAN</p>\r\n\r\n<p>- Titik Jatuh Line 2 menggunung</p>\r\n\r\n<p>- Spreading masih dilakukan menuju arah utara (Titik Jatuh Line 1 Selatan)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>3. JOB PENDING</p>\r\n\r\n<p>- Penggantian Nama Picnometer, diurutkan dari 1 - terakhir.</p>\r\n\r\n<p>- Pengambilan Akuades di Teknologi</p>\r\n\r\n<p>- Pengambilan, Foto, dan Progress Sampel Filterpress Line 1 dan Line 2</p>\r\n\r\n<p>- Housekeeping</p>\r\n\r\n<p>- Monitoring area operasi</p>\r\n\r\n<p>- Pengolahan data CPTu</p>\r\n\r\n<p>- Pembersihan Konus</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n', '1769246576_White Grey Simple Minimalist Photo Management Organisation Graph.png', '2026-01-24 09:23:56', 'Instrument & Geotechnical', '2026-01-24 09:23:56', NULL, 'pending', NULL, NULL),
(183, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 24/01/2026', '<p><strong>Line 1 ke Line 1 Selatan :</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p>jika Kondisi Emergency Line 1 ke line 1 utara &nbsp; =</p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan&nbsp;</li>\r\n	<li>Cutting material area megatower dan menaikan level tanggul di area belakang workshop (Jika ada Unit Lebih)</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 24 January 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 84 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 Dari buttres C P89 turunan jalan 70 : elevasi 71-70</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1769247247_Screenshot 2026-01-23 184444.jpg', '2026-01-24 09:34:07', 'Tailing Facility Planning', '2026-01-24 09:34:07', NULL, 'pending', NULL, NULL);
INSERT INTO `berita` (`id_berita`, `iduser`, `id_kategori`, `id_user`, `judul`, `isi_berita`, `gambar`, `tgl_posting`, `plan`, `updated_at`, `deleted_at`, `status`, `approved_by`, `approved_at`) VALUES
(184, 0, 7, 33, 'BA Overshift Waste Water Treatment Plant Shift Malam 24/01/2026', '<p>Info Pekerjaan&nbsp;</p>\r\n\r\n<p>- Sampling &amp; Monitoring&nbsp;</p>\r\n\r\n<p>- Pembacaan Debit V Notch</p>\r\n\r\n<p>- Pengurasan kolam 2 Pengolah Lindi&nbsp;</p>\r\n\r\n<p>- Warming up Genset&nbsp;</p>\r\n\r\n<p>- Progres perakitan komponen mini dredging pump</p>\r\n', '1769280563_WhatsApp Image 2026-01-25 at 02.02.20.jpeg', '2026-01-24 18:49:23', 'Waste Water Treatment Plant', '2026-01-24 18:49:23', NULL, 'pending', NULL, NULL),
(185, 0, 1, 16, 'BA Overshift Earthwork Shift Malam 24/01/2026', '<p>Job Pendding:</p>\r\n\r\n<ol>\r\n	<li>Line 1 selatan full dozing kearah Utara</li>\r\n	<li>Line 2 selatan full Hauling triming di C p23, 60, buttres bP89 dan bP89 comp c</li>\r\n	<li>lanjut cut tailing di titik jatuh line 1 selatan lama</li>\r\n	<li>kontruksi buttres bP89 pembuatan tanggul di belakang workshop</li>\r\n</ol>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>FOREMAN</p>\r\n\r\n	<p>Theodorus Sitohang, Stewani tununu, Deni Nugraha, Septiawan dwi</p>\r\n	</li>\r\n	<li>\r\n	<p>JUMLAH MANPOWER</p>\r\n\r\n	<p>Dt 24 orang Exc 15 orang Dozer 18 orang Compac 5 orang Lt 2 orang Ceker 7 orang Foreman 4 orang</p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Pelaksana Shift Berikut:</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>SUPERVISOR</p>\r\n\r\n	<p>p.nanang Koswara</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN PELAKSANA</p>\r\n\r\n	<p>abdu m hamid m safaat umar Irfandi ode Budi Setiawan Abdul Rahman</p>\r\n	</li>\r\n</ul>\r\n', '1769311069_WhatsApp Image 2026-01-24 at 20.08.49.jpeg', '2026-01-25 03:19:30', 'Earthwork', '2026-01-24 20:17:49', NULL, 'pending', NULL, NULL),
(186, 0, 1, 36, 'BA Overshift Earthwork Shift Pagi 25/01/2026', '<p>Job pendding:<br />\r\n&nbsp;</p>\r\n\r\n<p>1.Line 1 Selatan Full Dozing ke arah utara; fokus fill genangan air</p>\r\n\r\n<p>2.Line 2 selatan hauling ke 5 titik trimingan:</p>\r\n\r\n<ul>\r\n	<li>Elevasi 60 Tengah</li>\r\n	<li>Buttress B P89 Dalam</li>\r\n	<li>Kompartement C P89&nbsp;</li>\r\n	<li>&nbsp;Dua Titik ke Buttress C P234.</li>\r\n</ul>\r\n\r\n<p>3.Hauling Batu sengigi damping ke butreess B P89 untuk naikan level Buttress</p>\r\n\r\n<p>4.Cut Tailing elevasi 70 titik line 1 Selatan lama<br />\r\n<br />\r\n<br />\r\nManpower:</p>\r\n\r\n<ol>\r\n	<li>Driver DT= 24</li>\r\n	<li>LT/LV = 2</li>\r\n	<li>WT = 1</li>\r\n	<li>Op. Excavator = 19</li>\r\n	<li>Op. Bulldoser = 14</li>\r\n	<li>Op. Compactor = 5</li>\r\n	<li>Checker = 9</li>\r\n	<li>Foreman = 3</li>\r\n	<li>SPV =&nbsp;</li>\r\n</ol>\r\n\r\n<p>Foreman:</p>\r\n\r\n<p>Pak Abdul rahman,&nbsp; Safaat Umar, Abdu M hamid<br />\r\n<br />\r\n<br />\r\nPelaksana Shift Malam:<br />\r\nSPV:&nbsp; Nanang Koswara Bin Wagimin<br />\r\n<br />\r\nForeman: Dwi Septiawan, Deni Nugraha, Budi Setiawan, Theodi=orus Sitohang</p>\r\n', '1769316992_WhatsApp Image 2026-01-25 at 08.58.38.jpeg', '2026-01-25 04:56:32', 'Earthwork', '2026-01-25 04:56:32', NULL, 'pending', NULL, NULL),
(187, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Pagi 25/01/2026', '<p>PROGRESS HARI INI</p>\r\n\r\n<p>1. Monitoring lereng area kerja</p>\r\n\r\n<p>2. Kalibrasi Picknometer</p>\r\n\r\n<p>3. Pengambilan dan progress sampel filterpress line 1 dan line 2</p>\r\n\r\n<p>4. Pengujian konsolidasi</p>\r\n\r\n<p>5. Pengujian hidrometer</p>\r\n\r\n<p>6. Pengambilan sampel CPTu</p>\r\n\r\n<p>7. Sandcone kompartemen B dan C P89</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>1. Awal Shift terdapat retakan besar pada area Line 1 Selatan</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>JOB PENDING</p>\r\n\r\n<p>1. Pengambilan, Foto, dan Progress Sampel Filterpress</p>\r\n\r\n<p>2. Kalibrasi Piknometer</p>\r\n\r\n<p>3. Pengujian Sieve</p>\r\n\r\n<p>4. Extrude Sampel CPTu</p>\r\n\r\n<p>5. Monitoring area kerja terutama area spreading titik jatuh line 1 selatan</p>\r\n\r\n<p>6. QC Buttress</p>\r\n', '1769333984_Zulfitra Than.jpg', '2026-01-25 09:39:44', 'Instrument & Geotechnical', '2026-01-25 09:39:44', NULL, 'pending', NULL, NULL),
(188, 0, 7, 33, 'BA Overshift Waste Water Treatment Plant Shift Malam 25/01/2026', '<p>Info Pekerjaan&nbsp;</p>\r\n\r\n<p><br />\r\n- Sampling &amp; monitoring&nbsp;</p>\r\n\r\n<p>- Proses Pengolahan Lindi&nbsp;<br />\r\n- Perbaikan jalur pipa air bersih&nbsp;</p>\r\n', '1769372634_WhatsApp Image 2026-01-26 at 05.22.26.jpeg', '2026-01-25 20:23:54', 'Waste Water Treatment Plant', '2026-01-25 20:23:54', NULL, 'pending', NULL, NULL),
(189, 0, 1, 28, 'BA Overshift Earthwork Shift Malam 25/01/2026', '<p><strong>MANPOWER:</strong></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>JUMLAH MANPOWER</p>\r\n\r\n	<p>DT - 22 Exca - 16 Dozer - 14 Compack - 4 Lt -3 Checker - 9 Foreman - 4 SPV - 1</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN:</p>\r\n\r\n	<p>Deni nugraha, Septian dwi w, Theodorus s Budi s</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><strong>Job Pendding:</strong></p>\r\n\r\n<p>1.line 1 selatan full dosing arah spreadingan ke arah arah membentuk tanggul</p>\r\n\r\n<p>2.line 2 full hauling dumping tailing di komp C P23,BP89,dan C P89</p>\r\n\r\n<p>3.kontruksi butress B P89 sisi timur</p>\r\n\r\n<p>4.lipat dan dosing tailing titik jatuh line 1 selatan lama<br />\r\n&nbsp;</p>\r\n\r\n<p>PELAKSANA:<br />\r\n&nbsp;</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>SUPERVISOR</p>\r\n\r\n	<p>Ardyles teken</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN&nbsp;</p>\r\n\r\n	<p>Abdul rahman, Stewani t,&nbsp; Abdu m hamid, Safaat umar, Irfandi ode</p>\r\n	</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n', '1769381062_WhatsApp Image 2026-01-25 at 21.19.16.jpeg', '2026-01-25 22:44:22', 'Earthwork', '2026-01-25 22:44:22', NULL, 'pending', NULL, NULL),
(190, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Pagi 25/01/2026', '<p>Info<br />\r\n- analisa lab&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch&nbsp;<br />\r\n- lanjut konstruksi mini drage pump<br />\r\n- perbaikan valve 2 inchi jalur air bersih yg pecah<br />\r\n- buka nota baut M16 (baut 24) 50 set<br />\r\n- FU IM EID, sudah di PAS Mr. SWT</p>\r\n\r\n<p>Job pending&nbsp;<br />\r\n- proses&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch</p>\r\n', '1769415545_WhatsApp Image 2026-01-25 at 14.48.51.jpeg', '2026-01-26 08:19:05', 'Waste Water Treatment Plant', '2026-01-26 08:19:05', NULL, 'pending', NULL, NULL),
(191, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 26/01/2026', '<p><strong>Line 1 ke Line 1 Selatan :</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p>jika Kondisi Emergency Line 1 ke line 1 utara &nbsp; =</p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan&nbsp;</li>\r\n	<li>Cutting material area megatower &nbsp;(Jika ada Unit Lebih)</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 26 January 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 84 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 Dari buttres C P89 turunan jalan 70 : elevasi 71-70</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1769418584_Screenshot 2026-01-23 184444.jpg', '2026-01-26 09:09:44', 'Tailing Facility Planning', '2026-01-26 09:09:44', NULL, 'pending', NULL, NULL),
(192, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Pagi 26/01/2026', '<p>PROGRESS HARI INI</p>\r\n\r\n<p>1. Pengambilan, Foto, dan Progress Filterpress Line 1 dan Line 2</p>\r\n\r\n<p>2. Pengujian Sieve dan Hidrometer</p>\r\n\r\n<p>3. Kalibrasi Pycnometer</p>\r\n\r\n<p>4. Preparasi Sampel CPTu</p>\r\n\r\n<p>5. Monitoring Area Operasi</p>\r\n\r\n<p>6. Pengujian Sandcone Kompartemen A dan B P23</p>\r\n\r\n<p>7. Preparasi Pasir Uji</p>\r\n\r\n<p>8. Konstruksi Buttress B P89</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>1. Konstruksi Safety Berm Jalan 70</p>\r\n\r\n<p>2. Kondisi Titik Jatuh Line 2 Tinggi, dapat dikontrol dan dimonitoring untuk mengurangi tumpukan</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>JOB PENDING</p>\r\n\r\n<p>1. Pengambilan Sampel Filterpress Line 1 dan Line 2</p>\r\n\r\n<p>2. Lanjut Kalibrasi Piknometer</p>\r\n\r\n<p>3. Atteberg Limit Sampel CPTu</p>\r\n\r\n<p>4. Extrude Sampel CPTu</p>\r\n\r\n<p>5. Monitoring Area Operasional</p>\r\n', '1769419228_Zulfitra Than (1).jpg', '2026-01-26 09:20:28', 'Instrument & Geotechnical', '2026-01-26 09:20:28', NULL, 'pending', NULL, NULL),
(193, 0, 1, 13, 'BA Overshift Earthwork Shift Pagi 26/01/2026', '<p><strong>Job Pendding:</strong><br />\r\n1.Line 1 selatan skema masih seperti pola minggu lalu,Spreading ke arah genangan air untuk press ke finger dan bentuk single tanggul di tengah</p>\r\n\r\n<p>2.Line 2 selatan Full Hauling ke</p>\r\n\r\n<p>&bull;Elevasi 60 tengah (1-2 Titik) dosingan ke arah timur</p>\r\n\r\n<p>&bull;Batress Bp89 timur mengisi ke arah Comp.Cp89</p>\r\n\r\n<p>&bull;Comp.Cp89 pertama dari titik jatuh dan spreading ke timur</p>\r\n\r\n<p>&bull;Com.Cp23 (2) titik dan skema dosingan ke utara dan timur</p>\r\n\r\n<p>3.Konstruksi Batress Bp89 dari arah timur naikkan elevasi samping sump Hidro</p>\r\n\r\n<p>4.Cut titik jatuh line1 selatan<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>Temuan</strong></p>\r\n\r\n<p>-Cuaca cerah tetapi Polusi debu berhubung WT breakdown on progres</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Manpower:</strong></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>JUMLAH MANPOWER</p>\r\n\r\n	<p>Operator Exavator:18</p>\r\n\r\n	<p>Buldoser:16</p>\r\n\r\n	<p>Compactor:5</p>\r\n\r\n	<p>DT:25</p>\r\n\r\n	<p>LT:2</p>\r\n\r\n	<p>Cheker:9</p>\r\n\r\n	<p>Pengawas:4</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN</p>\r\n\r\n	<p>1.Stewani T</p>\r\n\r\n	<p>2.Abdu Hamid</p>\r\n\r\n	<p>3.A rahman</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><strong>Pelaksana Shift Malam:</strong><br />\r\n&nbsp;</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>SUPERVISOR</p>\r\n\r\n	<p>Nanang K</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN PELAKSANA</p>\r\n\r\n	<p>1.Budi S</p>\r\n\r\n	<p>2.Deni N</p>\r\n\r\n	<p>3.M syafaat</p>\r\n\r\n	<p>4.Theodorus</p>\r\n	</li>\r\n</ul>\r\n', '1769420405_WhatsApp Image 2026-01-26 at 08.08.42.jpeg', '2026-01-26 09:40:05', 'Earthwork', '2026-01-26 09:40:05', NULL, 'pending', NULL, NULL),
(194, 0, 1, 28, 'BA Overshift Earthwork Shift Malam 26/01/2026', '<p><strong>Job Pendding:</strong></p>\r\n\r\n<ol>\r\n	<li>1.line 1 selatan full dosing arah spreadingan ke arah utara (genangan air)</li>\r\n	<li>2.line 2 full hauling dan dumping railing di komp C P23.BP89 dan C P89</li>\r\n	<li>3.kontruksi butress B P89</li>\r\n	<li>4.potong tailing titik jatuh line 1 selatan lama(komp B P89)</li>\r\n</ol>\r\n\r\n<p><strong>Jjumlah Manpower:</strong></p>\r\n\r\n<ul>\r\n	<li>DT - 21 Exca - 13 Dozer - 13 Compack - 5 Lt -3 Checker - 8 Foreman - 4 SPV - 1</li>\r\n	<li>FOREMAN: Budi setiawan, Deni nugraha, Theodorus s, Safaat umar</li>\r\n</ul>\r\n\r\n<p><strong>Pelaksana</strong>:</p>\r\n\r\n<ul>\r\n	<li>SUPERVISOR: Ardyles teken</li>\r\n	<li>FOREMAN PELAKSANA: Stewani t, Abdul rahman, Irfandi ode, Abdu m hamid, Septian dwi w</li>\r\n</ul>\r\n', '1769466844_WhatsApp Image 2026-01-26 at 20.46.27.jpeg', '2026-01-26 22:39:07', 'Earthwork', '2026-01-26 20:34:04', NULL, 'pending', NULL, NULL),
(195, 0, 1, 13, 'BA Overshift Earthwork Shift Pagi 27/01/2026', '<p><strong>Job Pendding:</strong></p>\r\n\r\n<p>1.Line 1 utara Full Hauling ke</p>\r\n\r\n<p>&bull;Megatower Dosingan ke arah samping ws</p>\r\n\r\n<p>&bull;Akses 85 belakang ws</p>\r\n\r\n<p>2.Line 2 selatan Full Hauling Dan Dosing</p>\r\n\r\n<p>&bull;Elevasi 60 skema dozingan ke timur</p>\r\n\r\n<p>&bull;Comp.Cp89 dari arah batress Bp89 dosingan ke arah selatan</p>\r\n\r\n<p>&bull;Comp.Cp89 pertama dari titik jatuh arah dozingan ke timur</p>\r\n\r\n<p>&bull;Comp.Cp23 skema dosingan ke utara an timur</p>\r\n\r\n<p>&bull;Loadingan dalam spreading ke arah selatan</p>\r\n\r\n<p>3.Cut comp.B barat bekas titik jatuh</p>\r\n\r\n<p>4.Pemadatan batress Bagian timur</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>TEMUAN</strong></p>\r\n\r\n<p>Kondisi Tidak aman</p>\r\n\r\n<p>&bull;WT status BD dan polusi debu tinggih d area Hauling</p>\r\n\r\n<p>&bull;Pukul 17.30 unit 1 selatan bergeser ke utara terkait CV 14 terjadi kerusakan</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Manpower:</strong></p>\r\n\r\n<p>Cheker:7</p>\r\n\r\n<p>Exavator:16</p>\r\n\r\n<p>Buldozer:14</p>\r\n\r\n<p>Compactor:4</p>\r\n\r\n<p>DT:27</p>\r\n\r\n<p>LT:2</p>\r\n\r\n<p>WT:BD</p>\r\n\r\n<p>Pengawas:4</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>FOREMAN</strong>:</p>\r\n\r\n<p>1.Stewani T</p>\r\n\r\n<p>2.A rahman</p>\r\n\r\n<p>3.Septiawan dwi</p>\r\n\r\n<p>4.Abdu M hamid</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Pelaksana:</strong></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>SUPERVISOR</p>\r\n\r\n	<p>Nanang K</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN PELAKSANA</p>\r\n\r\n	<p>1.Budi S</p>\r\n\r\n	<p>2.M syafaat U</p>\r\n\r\n	<p>3.Irfandi Ode</p>\r\n\r\n	<p>4.Deni N</p>\r\n	</li>\r\n</ul>\r\n', '1769506407_WhatsApp Image 2026-01-27 at 10.11.28.jpeg', '2026-01-27 09:33:27', 'Earthwork', '2026-01-27 09:33:27', NULL, 'pending', NULL, NULL),
