(199, 0, 1, 28, 'BA Overshift Earthwork Shift Malam 27/01/2026', '<p><strong>Job Pendding:</strong><br />\r\n<br />\r\n1.line 1 utara mix antara dosingan ke arah timur selatan dan hauling tailing ke komp A P23</p>\r\n\r\n<p>2.line 2 full hauling tailing dan dumping tailing di komp C P23.BP89 dan komp C P89</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>manpower:</strong></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Foreman</p>\r\n\r\n	<p>Deni nugraha, Budi s, Irfandi ode , Safaat umar, Theodorus s</p>\r\n	</li>\r\n	<li>\r\n	<p>Jml Seluruh</p>\r\n\r\n	<p>DT - 18 Exca - 12 Dozer - 14 Compack - 5 Lt -3 Checker - 7 Foreman - 5 SPV - 1</p>\r\n	</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>DISERAHKAN KE</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>SHIFT</p>\r\n\r\n	<p>Siang</p>\r\n	</li>\r\n	<li>\r\n	<p>HARI/TANGGAL</p>\r\n\r\n	<p>28-01-2026</p>\r\n	</li>\r\n	<li>\r\n	<p>SUPERVISOR</p>\r\n\r\n	<p>Ardyles teken</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN PELAKSANA</p>\r\n\r\n	<p>Stewani t, Abdul rahman, Septian dwi&nbsp;w, Abdu m hamid</p>\r\n	</li>\r\n</ul>\r\n', '1769553639_WhatsApp Image 2026-01-27 at 21.09.28.jpeg', '2026-01-27 20:40:39', 'Earthwork', '2026-01-27 22:40:56', NULL, 'pending', NULL, NULL),
(200, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Pagi 26/01/2026', '<p>Info Pekerjaan<br />\r\n- analisa lab&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch&nbsp;<br />\r\n- lanjut konstruksi mini drage pump (selesai, tinggal di sambung, kurang baut dan lubang baut)<br />\r\n- pasang valve 2 inchi jalur pipa chemical &gt; tangki air bersih&nbsp;<br />\r\n- fogging dan pemberian racun tikus area Toba 1<br />\r\n- pasang sign tangga bak penampung dan bypass utara&nbsp;<br />\r\n- IM EID sudah full TTD, sudah diterima admin EID&nbsp;<br />\r\n- IM FeSO4 dan kalibrasi alat DSTF sudah di PAS Mr. SWT<br />\r\n- cek pipa DN 450, besok bisa di ambil pakai DT (panjang 5 meter)<br />\r\n- buka nota sign 3 poin contact dan sign awas ada pipa air bersih ditanam</p>\r\n\r\n<p>Job pending&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch&nbsp;<br />\r\n- lanjut konstruksi mini drage pump<br />\r\n- JCC 1 orang</p>\r\n', '1769585236_WhatsApp Image 2026-01-26 at 11.19.27.jpeg', '2026-01-28 07:27:16', 'Waste Water Treatment Plant', '2026-01-28 07:27:16', NULL, 'pending', NULL, NULL),
(201, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Pagi 27/01/2026', '<p>Info<br />\r\n- analisa lab&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch&nbsp;<br />\r\n- pengangkutan steel pipe DN450<br />\r\n- lanjut konstruksi mini drage pump&nbsp;<br />\r\n- buka nota baut M8 untuk mini drage pump<br />\r\n- sambung pipa air bersih ke tandon air yg lepas<br />\r\n- IM FeSO4 sudah full TTD, besok antar ke Enviro</p>\r\n\r\n<p>Job pending&nbsp;<br />\r\n- lanjut proses&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch&nbsp;<br />\r\n- lanjut konstruksi mini drage pump<br />\r\n- â pengambilan aquades di teknologi&nbsp;<br />\r\n- â weekly report bisa tambahkan dokumentasi ada di raw data dan buatkan list permintaan APD januari yang ke safety ada di folder sharing : apd dstf/lampiran pengajuan APD /2026/ januari</p>\r\n', '1769585599_WhatsApp Image 2026-01-27 at 10.46.10.jpeg', '2026-01-28 07:33:19', 'Waste Water Treatment Plant', '2026-01-28 07:33:19', NULL, 'pending', NULL, NULL),
(202, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 28/01/2026', '<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 28 January 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 84 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 Dari buttres C P89 turunan jalan 70 : elevasi 71-70</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1769590333_skema opras 28 januari.jpg', '2026-01-28 08:52:13', 'Tailing Facility Planning', '2026-01-28 08:52:13', NULL, 'pending', NULL, NULL),
(203, 0, 2, 26, 'BA Overshift Instrument & Geotechnical Shift Pagi 28/01/2026', '<p>Daily Report:<br />\r\nPengujian LLPL CPTu 15 BP23 Depth 4.00 - 4.50 m, 8.00 - 8.50 m , dan 14.00 - 14.50 m<br />\r\nPengujian Grainsize CPTu 16&nbsp;BP23&nbsp; All depth<br />\r\nPengambilan dan progress sampel filterpress shift siang<br />\r\nPreparasi sampel Konsolidasi CPTu BP23 16 Depth 4.00.4.50 m<br />\r\n<br />\r\nJob Pending:<br />\r\nLLPL CPTu 15 BP23 Depth 18.00 - 18.50 m<br />\r\nGrainsize CPTu 16 BP23 All Depth<br />\r\nPengambilan dan progress sampel filterpress shift malam</p>\r\n', '1769593018_WhatsApp Image 2026-01-28 at 12.48.09.jpeg', '2026-01-28 09:36:58', 'Instrument & Geotechnical', '2026-01-28 09:36:58', NULL, 'pending', NULL, NULL),
(204, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Malam 28/01/2026', '<p>PROGRESS HARI INI :</p>\r\n\r\n<p>1. Monitoring Lereng Area Operasional, Line 1 barjalan aman, namun untuk Line 2&nbsp;</p>\r\n\r\n<p>2. Pengolahan FK</p>\r\n\r\n<p>3. Lanjut Progress SG</p>\r\n\r\n<p>4. Lanjut pembacaan hidrometer</p>\r\n\r\n<p>5. Pengambilan, foto, dan progress sampel filterpress</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>1. Titik Jatuh Line 2 Menggunung</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>JOB PENDING</p>\r\n\r\n<p>1. Progress MC CPTu.14</p>\r\n\r\n<p>2. LLPL Sampel CPTu</p>\r\n\r\n<p>3. Lanjut SG</p>\r\n\r\n<p>4. Monitoring Area Operasional</p>\r\n\r\n<p>5. Siapkan Pasir Sandcone Sebanyak banyak nya</p>\r\n\r\n<p>6. Monthly</p>\r\n', '1769635425_WhatsApp Image 2026-01-29 at 03.25.52.jpeg', '2026-01-28 21:23:45', 'Instrument & Geotechnical', '2026-01-28 21:23:45', NULL, 'pending', NULL, NULL),
(205, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 28/01/2026', '<p>Info :&nbsp;</p>\r\n\r\n<ul>\r\n	<li>Proses akhir shift speed (60:60)</li>\r\n	<li>Sampling dan Monitoring&nbsp;</li>\r\n	<li>JCC 1 orang dengan Ikbal sebagai sampel&nbsp;</li>\r\n	<li>Pembersihan karung bekas jumbo bag pam dan bekas fero di gudang chemical , ditaruh samping tempat sampah kalau bisa ditimbun&nbsp;</li>\r\n	<li>Inspeksi APD</li>\r\n	<li>Cicil Weekly Report&nbsp;</li>\r\n	<li>Cicil Monthly Report</li>\r\n	<li>Lanjut pengurasan kolam dengan pompa 5,6,7 on</li>\r\n</ul>\r\n', '', '2026-01-28 21:47:55', 'Waste Water Treatment Plant', '2026-01-28 21:47:55', NULL, 'pending', NULL, NULL),
(206, 0, 2, 26, 'BA Overshift Instrument & Geotechnical Shift Pagi 29/01/2026', '<p>Daily Report:<br />\r\nPengujian LLPL CPTu 15 BP23 Depth 15.00 - 15.50 m,17.00 - 17.50 m dan 24.00 - 24.50 m<br />\r\nPengambilan dan progress sampel filterpress shift siang<br />\r\nPengujian Triaxial CPTu 16 BP23 Depth 4, 8, dan 12<br />\r\nPembacaan Konsolidasi CPTu BP23 16 Depth 4.00.4.50 m<br />\r\nKonstruksi Buttress B P89<br />\r\nMonitoring line 1 dan 2&nbsp;<br />\r\n<br />\r\nJob Pending:<br />\r\nGrainsize CPTu 15 BP23 Depth 18, 14, dan 24<br />\r\nPengambilan dan progress sampel filterpress shift malam</p>\r\n', '1769677438_WhatsApp Image 2026-01-29 at 13.46.30.jpeg', '2026-01-29 09:03:58', 'Instrument & Geotechnical', '2026-01-29 09:03:58', NULL, 'pending', NULL, NULL),
(207, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 29/01/2026', '<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 28 January 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 84 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 Dari buttres C P89 turunan jalan 70 : elevasi 71-70</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1769678633_skema opras 28 januari.jpg', '2026-01-29 09:23:53', 'Tailing Facility Planning', '2026-01-29 09:23:53', NULL, 'pending', NULL, NULL),
(208, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Malam 29/01/2026', '<p>PROGRESS HARI INI :</p>\r\n\r\n<p>1. Finish Pembacaan Hydrometer</p>\r\n\r\n<p>2. Vacum Piknometer</p>\r\n\r\n<p>3. Pengambilan sampel filtterpress shift siang line 1, shift malam line 1 dan line 2</p>\r\n\r\n<p>4. Analisis FK</p>\r\n\r\n<p>5. Monitoring area operasi</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>1. Tumpukan line 2 tinggi</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>JOB PENDING</p>\r\n\r\n<p>1. JCC Tim, kurang 2</p>\r\n\r\n<p>2. Progress Hydrometer</p>\r\n\r\n<p>3. Pembacaan Konsolidasi</p>\r\n\r\n<p>4. Pengujian LLPL</p>\r\n\r\n<p>5. Monitoring area operasi</p>\r\n', '1769721092_WhatsApp Image 2026-01-30 at 01.21.04.jpeg', '2026-01-29 21:11:32', 'Instrument & Geotechnical', '2026-01-29 21:11:32', NULL, 'pending', NULL, NULL),
(209, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 29/01/2026', '<p>Info :</p>\r\n\r\n<ul>\r\n	<li>Sampling dan Monitoring&nbsp;</li>\r\n	<li>Lanjut pengurasan kolam pengolah lindi&nbsp;</li>\r\n	<li>Susun bata saluran geotube</li>\r\n	<li>Cicil Monthly&nbsp;</li>\r\n</ul>\r\n', '1769723091_WhatsApp Image 2026-01-30 at 06.44.07.jpeg', '2026-01-29 21:44:51', 'Waste Water Treatment Plant', '2026-01-29 21:44:51', NULL, 'pending', NULL, NULL),
(210, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Pagi 30/01/2026', '<p>Info<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- analisa lab&nbsp;<br />\r\n- pengangkutan LB3 1 drum dari tim enviro&nbsp;<br />\r\n- IM Permintaan FeSO4 Enviro sudah dititip ke bu Lilis&nbsp;<br />\r\n- lanjut konstruksi mini drage&nbsp;<br />\r\n- tim EID konek kabel power dan kabel pompa di panel baru depan kolam 5<br />\r\n- pompa kolam 2,5,6,7 on<br />\r\n- Weekly report sudah diupdate (data enviro, grafik dan PPT)</p>\r\n\r\n<p>Job pending&nbsp;<br />\r\n- proses&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- cek lagi weekly report&nbsp;<br />\r\n- lanjut monthly report<br />\r\n- off pompa kolam 2,5,6 (akhir shift on pompa kolam 5,6,7)</p>\r\n', '1769748868_WhatsApp Image 2026-01-28 at 10.57.59.jpeg', '2026-01-30 04:57:39', 'Waste Water Treatment Plant', '2026-01-30 04:57:39', NULL, 'pending', NULL, NULL),
