(212, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Malam 30/01/2026', '<p>Pekerjaan Malam ini<br />\r\n- Monitoring area operasi titik (titik jatuh line 1 dan line 2)<br />\r\n- Pengujian SG CPTu 14<br />\r\n- Preparasi Grain Size CPTu 14<br />\r\n- Pengambilan, foto progress sampel filterpress<br />\r\n- KOnstruksi Buttress B P89</p>\r\n\r\n<p>Temuan<br />\r\n- Titik jatuh line 2 tinggi menggunung</p>\r\n\r\n<p>JOB PENDING<br />\r\n- Pengujian SG CPtu 14<br />\r\n- Pengujian Grainsize CPTu 15<br />\r\n- Konsolidasi<br />\r\n- Konstruksi Buttress B P89 (shelter dipindahkan)<br />\r\n- Triaxial</p>\r\n', '1769806754_WhatsApp Image 2026-01-31 at 03.52.57.jpeg', '2026-01-31 04:32:43', 'Instrument & Geotechnical', '2026-01-31 04:32:43', NULL, 'approved', 37, '2026-01-31 13:32:43'),
(213, 0, 1, 28, 'BA Overshift Earthwork Shift Malam 30/01/2026', '<p>JOB PENDDING:</p>\r\n\r\n<p>1.line 1 selatan full dosingan ny arah spreadingan ke arah utara menekan air</p>\r\n\r\n<p>2.line 2 ada rencana mau kancing,bisa ngurangi titik jatuh,titik dumpingan jalan +60 =2 ttk,butress B 1 ttk dan komp C P23= 2 ttk</p>\r\n\r\n<p>3.batu 102 kontruksi butress B timur dan batu sengigi kontruksi butress B barat</p>\r\n\r\n<p>4.lipat tailing titik jatuh lime 1 selatan lama di komp B P89<br />\r\n<br />\r\n<br />\r\nMANPOWER<br />\r\n&nbsp;</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>FOREMAN</p>\r\n\r\n	<p>Budi s Safaat umar Irfandi ode Abdu m hamid</p>\r\n	</li>\r\n	<li>\r\n	<p>JUMLAH MANPOWER SHIFT MALAM</p>\r\n\r\n	<p>Driver DT : 21 Opr Exca : 16 Opr Dozer : 15 Opr Compec : 3 Driver LT/LV : 2 Cheker : 8 Foreman : 4 Spv 1</p>\r\n	</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>DISERAHKAN KE SHIFT SIANG</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>HARI/TANGGAL</p>\r\n\r\n	<p>31-01-2026</p>\r\n	</li>\r\n	<li>\r\n	<p>SUPERVISOR</p>\r\n\r\n	<p>Ardyles teken</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN PELAKSANA</p>\r\n\r\n	<p>Stewani t, Abdul rahman, Theodorus sitohang, Deni nugraha</p>\r\n	</li>\r\n</ul>\r\n', '1769847005_WhatsApp Image 2026-01-30 at 20.32.11.jpeg', '2026-01-30 20:10:05', 'Earthwork', '2026-01-31 08:10:35', NULL, 'pending', NULL, NULL),
(214, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Pagi 30/01/2026', '<p>Info<br />\r\n- sampling dan monitoring<br />\r\n- pembacaan v-notch&nbsp;<br />\r\n- analisa lab&nbsp;<br />\r\n- pembersihan saluran dalam chemical facility<br />\r\n- kuras kolam 2,5,6,7 (akhir shift pompa kolam 7 off, sudah surut)<br />\r\n- lanjut susun bata saluran air buangan geotube&nbsp;<br />\r\n- perapihan/poles tangga chemical facility&nbsp;<br />\r\n- buka nota di warehouse (obeng plus dan mata gurinda potong, besok diambil)</p>\r\n\r\n<p>Job pending&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch<br />\r\n- lanjut susun bata saluran air buangan geotube<br />\r\n- lanjut kuras kolam 2,5,6</p>\r\n', '1769848262_WhatsApp Image 2026-01-30 at 11.29.37.jpeg', '2026-01-31 08:31:02', 'Waste Water Treatment Plant', '2026-01-31 08:31:02', NULL, 'pending', NULL, NULL),
(215, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 31/01/2026', '<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 31 January 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 84 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1769850276_skema oprasi februari 2026.jpg', '2026-01-31 09:04:36', 'Tailing Facility Planning', '2026-01-31 09:04:36', NULL, 'pending', NULL, NULL),
(216, 0, 2, 37, 'BA Overshift Instrument & Geotechnical Shift Pagi 31/01/2026', '<p><u><strong>TEMUAN</strong></u></p>\r\n\r\n<ol>\r\n	<li>Preparasi pengujian SG cptu.14 BP23 (7,14,24)</li>\r\n	<li>Pengujian TXL cptu.15 BP23 (8-8.5,14-14.5)</li>\r\n	<li>Pengujian hidrometer cptu.15 BP23 (4-4.5, 8.8.5)</li>\r\n	<li>Pembacaan konsolidasi</li>\r\n	<li>Preparasi hidrometer CPTu.15 BP23 (14,18,24)</li>\r\n	<li>Pergerakan bertambah pada point survei titik jatuh line 1 selatan</li>\r\n	<li>MC FP daily</li>\r\n	<li>Pembersihan laboratorium</li>\r\n	<li>Persiapan pelatihan welding</li>\r\n</ol>\r\n\r\n<p><strong><u>JOB PENDING</u></strong></p>\r\n\r\n<ol>\r\n	<li>Pengujian MC FP</li>\r\n	<li>Olah data pengujian laboratorium</li>\r\n	<li>Pengawasan titik jatuh</li>\r\n	<li>FK Daily</li>\r\n	<li>Pembacaan konsolidasi</li>\r\n	<li>Pengujian SG yang sudah siap</li>\r\n</ol>\r\n', '1769850597_WhatsApp Image 2026-01-31 at 17.21.23.jpeg', '2026-01-31 09:09:57', 'Instrument & Geotechnical', '2026-01-31 09:09:57', NULL, 'pending', NULL, NULL),
(217, 0, 1, 13, 'BA Overshift Earthwork Shift Pagi 31/01/2026', '<p><strong>JOB PENDDING:</strong></p>\r\n\r\n<ol>\r\n	<li>\r\n	<p>1.Line 1 selatan Full Spreading ke genangan air dan apabila emergency ke area banch utara</p>\r\n	</li>\r\n	<li>\r\n	<p>2.Line 2 selatab Full Hauling ke &bull;Elevasi 60 tengah(2 Titik)dosingan mengarah ke timur &bull;Comp.Cp89(1 Titik) arah batress Bp89 dozingan mengarah ke barat dan selatan &bull;Comp.Cp23(2 Titik) dozingan ke arah timut dan utara</p>\r\n	</li>\r\n	<li>\r\n	<p>3.Up layer batress dari Arah timur ke barat pakai batu sengigi dan 102 untuk Lipat ke arah dinding bawah pos</p>\r\n	</li>\r\n	<li>\r\n	<p>4.Perbaikan jalan hauling</p>\r\n	</li>\r\n	<li>\r\n	<p>5.Cut Bp89 titik jatuh lama jika ada unit</p>\r\n	</li>\r\n</ol>\r\n\r\n<p><strong>TEMUAN</strong></p>\r\n\r\n<p>&bull;Cuaca hujan Pukul 11.20-12.30</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>JUMLAH MANPOWER</strong></p>\r\n\r\n<p>1.Operator Buldozer:16</p>\r\n\r\n<p>2.Operator Exavator:18</p>\r\n\r\n<p>3.Operator Compactor:4</p>\r\n\r\n<p>4.Driver DT:25</p>\r\n\r\n<p>5.Driver LT:3</p>\r\n\r\n<p>6.Pengawas:4</p>\r\n\r\n<p>7.Cheker:8</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>FOREMAN SHIFT SIANG:</strong></p>\r\n\r\n<p>1.Stewani T</p>\r\n\r\n<p>2A rahman</p>\r\n\r\n<p>3.Theodorus S</p>\r\n\r\n<p>4.Deni N</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>PELAKSANA SHIFT MALAM</strong><br />\r\n&nbsp;</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>PLT SUPERVISOR</p>\r\n\r\n	<p>Septiawan dwi</p>\r\n	</li>\r\n	<li>\r\n	<p>FOREMAN PELAKSANA</p>\r\n\r\n	<p>1.Budi S</p>\r\n\r\n	<p>2.Irfandi ode</p>\r\n\r\n	<p>3.M syafaat</p>\r\n\r\n	<p>4.Abdu Hamid</p>\r\n	</li>\r\n</ul>\r\n', '1769851235_WhatsApp Image 2026-01-31 at 08.14.46.jpeg', '2026-01-31 09:21:36', 'Earthwork', '2026-01-31 09:21:36', NULL, 'pending', NULL, NULL),
(219, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 01/02/2026', '<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65&nbsp;</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 01 Februari 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 84 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1769937022_skema oprasi februari 2026.jpg', '2026-02-01 09:10:22', 'Tailing Facility Planning', '2026-02-01 09:10:22', NULL, 'pending', NULL, NULL),
(220, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Pagi 01/02/2026', '<p>- PROGRESS HARI INI</p>\r\n\r\n<p>1. Monitoring area operasi</p>\r\n\r\n<p>2. Konstruksi buttress b p89</p>\r\n\r\n<p>3. Preparasi sampel proctor</p>\r\n\r\n<p>4. Pengambilan sampel filterpress line 1 dan line 2</p>\r\n\r\n<p>5. Sandcone comp A P23 sisi timur</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>- TEMUAN</p>\r\n\r\n<p>1. Retakan di timbunan titik jatuh line 1&nbsp;</p>\r\n\r\n<p>2. Tumpukan tinggi titik jatuh line 2</p>\r\n\r\n<p>3. Hujan di sore hari</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>-JOB PENDING</p>\r\n\r\n<p>1. LLPL Line 1 dan Line 2, sampel di dalam oven</p>\r\n\r\n<p>2. Pengambilan filterpress line 1 dan line 2</p>\r\n\r\n<p>3. Monitoring area operasi</p>\r\n\r\n<p>4. Analisis FK</p>\r\n\r\n<p>5. QC Buttress B P89</p>\r\n', '1769937575_WhatsApp Image 2026-02-01 at 09.24.30.jpeg', '2026-02-01 09:19:35', 'Instrument & Geotechnical', '2026-02-01 09:19:35', NULL, 'pending', NULL, NULL),
(221, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 30/01/2026', '<p>info :&nbsp;</p>\r\n\r\n<ul>\r\n	<li>Sampling dan monitoring&nbsp;</li>\r\n	<li>Pengurasan kolam pengolah lindi ( pompa kolam 2 masih on, 5,6 off)&nbsp;</li>\r\n	<li>Lanjut susun bata saluran geotube</li>\r\n	<li>Pembacaan Vnotch pintu air outlet</li>\r\n</ul>\r\n', '1769979565_WhatsApp Image 2026-01-30 at 23.31.53.jpeg', '2026-02-01 20:59:25', 'Waste Water Treatment Plant', '2026-02-01 20:59:25', NULL, 'pending', NULL, NULL),
(222, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 31/01/2026', '<p>Info :</p>\r\n\r\n<ul>\r\n	<li>Sampling dan Monitoring&nbsp;</li>\r\n	<li>Proses Pengolah lindi Speed P1 50 : P2 50&nbsp;</li>\r\n	<li>Warming up genset 500 kva dan 250 kva</li>\r\n	<li>Pengerjaan Laporan&nbsp;Monthly</li>\r\n	<li>Pengukuran Voleme kolam pengolah lindi&nbsp;</li>\r\n</ul>\r\n', '1769979412_WhatsApp Image 2026-02-01 at 00.07.20.jpeg', '2026-02-01 20:56:52', 'Waste Water Treatment Plant', '2026-02-01 20:56:52', NULL, 'pending', NULL, NULL),
(223, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 01/02/2026', '<p>Info :</p>\r\n\r\n<p><br />\r\n&bull; Proses menggunakan speed P1 50:50 Sampai akhir shift</p>\r\n\r\n<p>&bull; Pembersihan strainer Tangki ferosulfat</p>\r\n\r\n<p>&bull; Sampling dan monitoring</p>\r\n\r\n<p>&bull; Pembacaan vnotch</p>\r\n\r\n<p>&bull; Hujan dari jam 05:30<br />\r\n<br />\r\n&nbsp;</p>\r\n', '1769979870_WhatsApp Image 2026-02-01 at 23.30.42.jpeg', '2026-02-01 21:04:30', 'Waste Water Treatment Plant', '2026-02-01 21:04:30', NULL, 'pending', NULL, NULL),
(224, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Pagi 02/02/2026', '<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- Pengujian CBR di Buttress B P89</p>\r\n\r\n<p>- Pengujian CPTu Kompartemen B P89</p>\r\n\r\n<p>- Pengujian Sandcone Kompartemen B P89</p>\r\n\r\n<p>- Pengujian Triaxial CPtu</p>\r\n\r\n<p>- Pengambilan MC Filterpress</p>\r\n\r\n<p>- Preparasi Pasir Uji Densitas</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>- Titik Jatuh Line 2 Tinggi</p>\r\n\r\n<p>- Cuaca Cerah</p>\r\n\r\n<p>- Nilai daya dukung Buttress masih kurang</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>JOB PENDING</p>\r\n\r\n<p>- Kompaksi maksimal Buttress B P89 untuk dilakukan pengujian di pagi nya</p>\r\n\r\n<p>- Monitoring titik jatuh line 1 dan line 2 dan area operasi</p>\r\n\r\n<p>- Pembersihan Konus CPTu</p>\r\n\r\n<p>- Pengolahan data CPTu</p>\r\n\r\n<p>- Pengujian SG dan Hydro Titik Jatuh Line 1 dan Line 2</p>\r\n\r\n<p>- Timbang dan ambil kering sampel proctor line 1</p>\r\n\r\n<p>- Menghaluskan sampel proctor line 2<br />\r\n<br />\r\n- Weekly report</p>\r\n', '1770022623_WhatsApp Image 2026-02-02 at 11.16.31.jpeg', '2026-02-02 09:39:08', 'Instrument & Geotechnical', '2026-02-02 09:39:08', NULL, 'pending', NULL, NULL),
(225, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 02/02/2026', '<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65 (Prioritas)</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan (Prioritas)</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 02 Februari 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 84 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1770022952_skema oprasi februari 2026.jpg', '2026-02-02 09:02:32', 'Tailing Facility Planning', '2026-02-02 09:02:32', NULL, 'pending', NULL, NULL),
(226, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 02/02/2026', '<p>Info :&nbsp;</p>\r\n\r\n<ul>\r\n	<li>Houskeeping Chemical Facility&nbsp;</li>\r\n	<li>Lanjut susun bata dan bobok tanggul jalur overtopping</li>\r\n	<li>Sampling dan monitoring&nbsp;</li>\r\n	<li>Kuras Kolam dengan pompa 5,6,7 kondisi pompa kolam 2 tidak menyala&nbsp;</li>\r\n	<li>Pembacaan Vnotch&nbsp;</li>\r\n</ul>\r\n', '1770063527_WhatsApp Image 2026-02-02 at 22.50.13.jpeg', '2026-02-02 20:20:27', 'Waste Water Treatment Plant', '2026-02-02 20:20:27', NULL, 'pending', NULL, NULL),
(227, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 02/02/2026', '<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65 (Prioritas)</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan (Prioritas)</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 03 Februari 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 84 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1770108869_skema oprasi februari 2026.jpg', '2026-02-03 08:54:29', 'Tailing Facility Planning', '2026-02-03 08:54:29', NULL, 'pending', NULL, NULL),
(228, 0, 6, 18, 'BA Overshift Hydrology & Hydrogeology Shift Pagi 03/02/2026', '<p>Job 3 Februari 2026</p>\r\n\r\n<p>&nbsp; &nbsp;1. Cut tailing bp89 --- Midun &amp; arnol<br />\r\n2. â Monitoring all area + Housekeeping --- tison<br />\r\n3. Tanggul underdrain --- ari &amp; kris<br />\r\n4. Maintenance sedpond -- chandra</p>\r\n\r\n<p>*Notes Pekerjaan Harian*<br />\r\n- 2 long arm&nbsp;<br />\r\n- â 1 exca 200 &amp; bulldozer</p>\r\n\r\n<p>Bulldozer start kerja jam 10.00<br />\r\nexca 200 breakdown jam 14.00 sampai akhir shift</p>\r\n\r\n<p>*Pelanggaran / Izin*&nbsp;</p>\r\n\r\n<p>*Job Pending*<br />\r\n1. Cross cut pipa jalan 60 -70 --- menunggu ganti area trimingan + unit<br />\r\n2. Pembuatan Perimeter Timur P89 --- &nbsp;on proggress&nbsp;<br />\r\n3. Saluran jalan 70 ---- Buat ulang karna ditimbun<br />\r\n4. Pemasangan gorong gorong baja di C P89 dan setting ulang --- Menunggu Unit<br />\r\n5. Pembuatan saluran di jalan baru sisi barat kolam Pengolah Lindi --- Menunggu unit&nbsp;<br />\r\n6. â Tanggul underdrain -- menunggu unit</p>\r\n\r\n<p>*Peralatan Pendukung*<br />\r\n1. Buat Pipa yg rencana dipakai (kalau bisa) tanyakan rika sampai mana progressnya</p>\r\n\r\n<p>*Remark*<br />\r\n1. Cek rembesan dari area Comp All<br />\r\n2. Cek Pipa vertikal (Khususnya area comp B P89) dan saluran<br />\r\n3. Kawal area Operasional khususnya area saluran (Saluran baru di jalan barat toba 1 dicek dan buatkan saluran agar air dari jalan masuk ke toe drain dahulu)</p>\r\n\r\n<p>*UR*</p>\r\n\r\n<p>*Umum*</p>\r\n\r\n<p>1. Clamp ukuran besar dan kecil habis di hpl + onc<br />\r\n2. Pengganti eten masih coba dicarikan sama IR cuman info dari pak rizky mungkin bakalan lama&nbsp;</p>\r\n\r\n<p>*Anggota job tambahan*&nbsp;<br />\r\n1. Ingatkan untuk lebih inisiatif terutama ketika ada pengawasnya atau pengawas lain (biar g main hp/game)<br />\r\n2. Ingatkan green card ( Wajib ada dan tekan kan buat) jika tidak ada pengurangan nilai (GPI)<br />\r\n3. lebih peka dengan kondisi sekitar (dozingan alat, assesment area, dan pekerjaan yg akan dilakukan)</p>\r\n\r\n<p>*Notes Besok*&nbsp;<br />\r\n1. Cut Tailing sampai level 54 buat rata dulu<br />\r\n2. kopdar dengan tim EID untuk installasi genset<br />\r\n3. â buat tanggul sepanjang kompartmen C P89 timur untuk batas spreading dozer</p>\r\n', '1770109137_WhatsApp Image 2026-02-03 at 16.53.40.jpeg', '2026-02-03 08:58:57', 'Hydrology & Hydrogeology', '2026-02-03 08:58:57', NULL, 'pending', NULL, NULL);
