(229, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Pagi 31/01/2026', '<p>Info<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- analisa lab&nbsp;<br />\r\n- kuras kolam 2,5,6,7 (sudah off)<br />\r\n- lanjut susun bata saluran air buangan geotube (stok batako 3 bucket long arm)<br />\r\n- penyemprotan lumpur kolam 2 pengolah lindi</p>\r\n\r\n<p>Job pending&nbsp;<br />\r\n- proses (speed 50:50)<br />\r\n- hitung waktu overflow tiap kolam<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch</p>\r\n', '1770153051_WhatsApp Image 2026-01-31 at 09.48.48.jpeg', '2026-02-03 21:10:51', 'Waste Water Treatment Plant', '2026-02-03 21:10:51', NULL, 'pending', NULL, NULL),
(230, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Pagi 01/02/2026', '<p>Info<br />\r\n- proses sampai akhir shift&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch&nbsp;<br />\r\n- analisa lab&nbsp;<br />\r\n- lanjut susun bata saluran geotube&nbsp;<br />\r\n- perlengkapan training Welder sudah dibawa ke workshop Geotek</p>\r\n\r\n<p>Job pending&nbsp;<br />\r\n- bersihkan saringan/strainer tangki FeSO4 (disamping panel, dibawah tangga)<br />\r\n- lanjut proses&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch</p>\r\n', '1770154172_WhatsApp Image 2026-02-01 at 12.17.26.jpeg', '2026-02-03 21:29:32', 'Waste Water Treatment Plant', '2026-02-03 21:29:32', NULL, 'pending', NULL, NULL),
(231, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Pagi 02/02/2026', '<p>Info<br />\r\n- proses<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- analisa lab<br />\r\n- sampling pemantauan perlindian flash<br />\r\n- lanjut susun bata saluran geotube&nbsp;<br />\r\n- ambil mara gurinda potong (masih digeotek, besok dibagi)<br />\r\n- buka nota kawat las 100 kg (20 box), nota masih di TKA, besok diinfo<br />\r\n- ambil sign rumah genset (FU temuan MWT)</p>\r\n\r\n<p>Job pending&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch&nbsp;<br />\r\n- kuras kolam 2,5,6,7<br />\r\n- lanjut susun bata saluran geotube&nbsp;<br />\r\n- kuras tangki dan pembersihan jalur pipa dosing FeSO4 dan PAM</p>\r\n', '1770154344_WhatsApp Image 2026-02-02 at 12.17.34.jpeg', '2026-02-03 21:32:24', 'Waste Water Treatment Plant', '2026-02-03 21:32:24', NULL, 'pending', NULL, NULL),
(232, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Malam 03/02/2026', '<p>Info<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch&nbsp;<br />\r\n- kuras kolam 5,6,7<br />\r\n- lanjut susun bata saluran geotube</p>\r\n', '1770154537_WhatsApp Image 2026-02-03 at 23.15.18.jpeg', '2026-02-03 21:35:37', 'Waste Water Treatment Plant', '2026-02-03 21:35:37', NULL, 'pending', NULL, NULL),
(233, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 04/02/2026', '<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65 (Prioritas)</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan (Prioritas)</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 04 Februari 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 83 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1770194917_WhatsApp Image 2026-02-04 at 17.47.03.jpeg', '2026-02-04 08:48:37', 'Tailing Facility Planning', '2026-02-04 08:48:37', NULL, 'pending', NULL, NULL),
(234, 0, 2, 26, 'BA Overshift Instrument & Geotechnical Shift Pagi 04/02/2026', '<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- Persiapan CPTu Kompartemen B P89</p>\r\n\r\n<p>- Pengujian Sandcone Kompartemen B P89</p>\r\n\r\n<p>-&nbsp;Pengujian Densitas dan MC Filterpress</p>\r\n\r\n<p>- Penurunan konsolidasi CPTu 16 B P23 kedalaman 4 - 4.5 m</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>- Titik Jatuh Line 2 tinggi</p>\r\n\r\n<p>- Jam kedua baru compact di buttress B P89</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>JOB PENDING</p>\r\n\r\n<p>- Kompaksi maksimal Buttress B P89 untuk dilakukan pengujian SR relatif dan CBR di pagi nya</p>\r\n\r\n<p>- Monitoring titik jatuh line 1 dan line 2 dan area operasi</p>\r\n\r\n<p>- Campur air proctor line 1 dan 2 modified</p>\r\n\r\n<p>- Sieve dan baca hidro CPTu B.13 P23 Kedalaman 5 - 5.5 m</p>\r\n', '1770196468_WhatsApp Image 2026-02-04 at 14.34.50.jpeg', '2026-02-04 10:33:55', 'Instrument & Geotechnical', '2026-02-04 10:33:55', NULL, 'approved', 37, '2026-02-04 19:33:55'),
(235, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Pagi 04/02/2026', '<p><strong>info :&nbsp;</strong><br />\r\n<br />\r\n- Analisa Laboratorium&nbsp;<br />\r\n- Sampling dan monitoring<br />\r\n- Sampling GW 6,7,8,9,10 (kondisi GW 9 kering)<br />\r\n- Pembacaan Vnotch&nbsp;<br />\r\n- Lanjut susun bata saluran geotube<br />\r\n- Tim Plan melakukan survey dan ukur elevasi di chemical facility<br />\r\n<br />\r\n<strong>Job pending :&nbsp;</strong><br />\r\n<br />\r\n- Lanjut Susun Bata Saluran Geotube<br />\r\n- Sampling dan monitoring&nbsp;<br />\r\n- Pembacaan Vnotch</p>\r\n', '1770198343_WhatsApp Image 2026-02-04 at 10.56.56.jpeg', '2026-02-04 09:45:43', 'Waste Water Treatment Plant', '2026-02-04 09:45:43', NULL, 'pending', NULL, NULL),
(236, 0, 2, 37, 'BA Overshift Instrument & Geotechnical Shift Malam 05/02/2026', '<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- Campur air proctor line 1 dan 2 modified.<br />\r\n- Sieve dan baca hidro CPTu B.13 P23 Kedalaman 5 - 5.5 m.<br />\r\n- Konstruksi dan pemadatan buttress B P89 sisi Timur.<br />\r\n- Uji MC FP.<br />\r\n- Pembersihan area Geotech.<br />\r\n- Pembacaan konsolidasi.<br />\r\n- Olah data SC dan CBR.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>- Compact di B P89 BD jam 22.00 WIT.<br />\r\n- Kualitas batu bagus.<br />\r\n- Material dari FP kering.<br />\r\n- Lereng DT line 2 Selatan terjal.<br />\r\n- Safety berm sisi Timur buttress BP89 kurang layak.<br />\r\n- Selter Buttress BP89 rusak.<br />\r\n- Disarankan pengujian SR relatif dilakukan ketika CBR sisi timur sudah masuk. Agar pengujian hanya dilakukan satu kali untuk layer RL 61 mdpl.</p>\r\n\r\n<p><br />\r\n&nbsp;</p>\r\n\r\n<p>JOB PENDING<br />\r\n- Pemadatan layer batu di jam I dan uji CBR di jam II sisi Timur bagian Selatan buttress B P89. Kode gembok <strong>055</strong>.<br />\r\n- Pembersihan oven.<br />\r\n- Maintance tanki air, vacuum, kompresor, volume change TXL.<br />\r\n- Ingatkan untuk slopping titik jatuh line 2 Selatan.&nbsp;<br />\r\n- Perbaiki safety berm buttress B P89.<br />\r\n- Cek geometri buttress hasil pekerjaan malam.<br />\r\n- Perbaikan selter buttress B P89.</p>\r\n', '1770229167_WhatsApp Image 2026-02-04 at 19.57.06.jpeg', '2026-02-04 18:40:45', 'Instrument & Geotechnical', '2026-02-04 18:40:45', NULL, 'pending', NULL, NULL),
(237, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Malam 04/02/2026', '<p>Info<br />\r\n- lanjut susun bata saluran geotube (sudah konek)<br />\r\n- semprot tanggul overflow kolam 2-3 dan bikin pijakan pakai karung slag<br />\r\n- sampling dan monitoring (outlet sudah tidak keluar di v-notch)<br />\r\n- lanjut buat weekly (sudah word, PPT dan foto job)</p>\r\n', '1770240421_WhatsApp Image 2026-02-04 at 22.21.50.jpeg', '2026-02-04 21:27:01', 'Waste Water Treatment Plant', '2026-02-04 21:27:01', NULL, 'pending', NULL, NULL),
(238, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Pagi 05/02/2026', '<p><br />\r\n&nbsp;<strong>info :</strong></p>\r\n\r\n<p>&bull; Analisa Laboratorium</p>\r\n\r\n<p>&bull; Sampling dan monitoring</p>\r\n\r\n<p>&bull; Stock material pengecoran di depan chemical facility ( batu dan Semen )</p>\r\n\r\n<p>&bull; Pembersihan Kolam Pengolah lindi kolam 6 dan kolam 7</p>\r\n\r\n<p>&bull; Buka Nota (Semen, batako, pasir ) belum di ttd karena LT cuma 1 dan sibuk</p>\r\n\r\n<p>&bull; Pengecheckan dan Perawatan panel shelter dan panel ponton dari tim EID automacion<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n', '1770283127_WhatsApp Image 2026-02-05 at 13.16.45.jpeg', '2026-02-05 09:18:47', 'Waste Water Treatment Plant', '2026-02-05 09:18:47', NULL, 'pending', NULL, NULL),
(239, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 05/02/2026', '<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65 (Prioritas)</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan (Prioritas)</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 05 Februari 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 83 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1770283219_skema oprasi februari 2026.jpg', '2026-02-05 09:20:19', 'Tailing Facility Planning', '2026-02-05 09:20:19', NULL, 'pending', NULL, NULL),
(240, 0, 2, 37, 'BA Overshift Instrument & Geotechnical Shift Malam 05/02/2026', '<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- Uji proctor line 1 &nbsp;modified.<br />\r\n- Pembacaan akhir Sieve dan baca hidro CPTu B.13 P23 Kedalaman 5 - 5.5 m.<br />\r\n- Konstruksi dan pemadatan buttress B P89 sisi Timur. Pelurusan geometri sisi Utara bagian Timur di perlukan, sudah dicicil malem ini.<br />\r\n- Ambil sampel MC FP.<br />\r\n- Pembersihan area Geotech.<br />\r\n- Monitoring area aktif.<br />\r\n-&nbsp;</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>- Adanya banyak lendutan di kaki timbunan line 1 selatan.<br />\r\n- Adanya retakan DD NW dekat point survey line 1 selatan.<br />\r\n- Kualitas batu bagus.<br />\r\n- MC drytail disekitar 36%. Grafik di share ke semua grup yang membutuhkan beserta keterangan nilainya.<br />\r\n- Kondisi titik jatuh line 2 mengkhawatirkan.<br />\r\n- Geometri buttress BP89 sisi Timur bisa di sesuaikan lagi.</p>\r\n\r\n<p><br />\r\n&nbsp;<br />\r\nJOB PENDING<br />\r\n- Pemadatan layer batu di jam I dan uji SR di jam II sisi Timur bagian Selatan buttress B P89.<br />\r\n- Uji proctor modif line 2.<br />\r\n- Maintance tanki air, vacuum, kompresor, volume change TXL.<br />\r\n- Ingatkan untuk slopping titik jatuh line 2 Selatan.&nbsp;<br />\r\n- Stackout untuk pelebaran sisi Selatan buttress BP89 bagian Timur.<br />\r\n- Cek geometri buttress hasil pekerjaan malam.<br />\r\n- Maintance hidrolik CBR ke fabrikasi dan test hidrolik warna abu.<br />\r\n- Pembersihan oven.<br />\r\n- Tanyakan apakah kita sudah ada meeting mengenai penyesuaian banyaknya material mesin FP dengan alat berat kita. Jika ada MOMnya bisa kirim untuk disosialisasikan.<br />\r\n- Uji MC FP shift malam.</p>\r\n', '1770316787_Screenshot 2026-02-06 033832.jpg', '2026-02-05 18:39:47', 'Instrument & Geotechnical', '2026-02-05 18:39:47', NULL, 'pending', NULL, NULL),
(241, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 06/02/2026', '<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65 (Prioritas)</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan (Prioritas)</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 06 Februari 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 83 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1770369559_skema oprasi februari 2026.jpg', '2026-02-06 09:19:19', 'Tailing Facility Planning', '2026-02-06 09:19:19', NULL, 'pending', NULL, NULL),
(242, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Pagi 06/02/2026', '<p><strong>Info :&nbsp;</strong></p>\r\n\r\n<ul>\r\n	<li>Analisa laboratorium&nbsp;</li>\r\n	<li>Sampling dan monitoring&nbsp;</li>\r\n	<li>Nota Semen, batako, pasir sudah aman di buka nota. Tinggal pengambilan&nbsp;</li>\r\n	<li>Plester dinding dalam saluran geotube&nbsp;</li>\r\n	<li>Pembersihan kolam 3 dan 4 pengolah lindi&nbsp;</li>\r\n	<li>Pompa kolam 6 sudah di angkat ke samping rumah gense, belum di ganti.</li>\r\n	<li>Revisi jadwal roster</li>\r\n	<li>Kirim email monitoring ke enviro</li>\r\n</ul>\r\n\r\n<p><br />\r\n<strong>Job Pending :</strong><br />\r\n&nbsp;</p>\r\n\r\n<ul>\r\n	<li>Proses sampai akhir shift</li>\r\n	<li>Sampling dan monitoring</li>\r\n	<li>Sebelum proses pompa kolam 2 bisa di setting dulu&nbsp;</li>\r\n	<li>Lanjut plester dinding saluran geotube</li>\r\n</ul>\r\n', '1770369837_WhatsApp Image 2026-02-06 at 12.58.27.jpeg', '2026-02-06 09:23:57', 'Waste Water Treatment Plant', '2026-02-06 09:23:57', NULL, 'pending', NULL, NULL),
(243, 0, 2, 37, 'BA Overshift Instrument & Geotechnical Shift Malam 06/02/2026', '<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- Uji MC FP Line 1 shift siang<br />\r\n- Konstruksi dan pemadatan buttress B P89 sisi Timur. Pelurusan geometri sisi Utara bagian Timur di perlukan, sudah dicicil malem ini.<br />\r\n- Ambil dan uji sampel FP.<br />\r\n- Pembersihan area Geotech.</p>\r\n\r\n<p><br />\r\nTEMUAN</p>\r\n\r\n<p>- Adanya banyak lendutan di kaki timbunan line 1 selatan.<br />\r\n- Adanya retakan DD NW dekat point survey line 1 selatan.<br />\r\n- Kualitas batu bagus.<br />\r\n- MC drytail disekitar 36%. Grafik di share ke semua grup yang membutuhkan beserta keterangan nilainya.<br />\r\n- Kondisi titik jatuh line 2 mengkhawatirkan.<br />\r\n- Geometri buttress BP89 sisi Timur bisa di sesuaikan lagi.<br />\r\n- Planning konstruksi tim siang dan malam dari tim operasi berbeda, mengikuti planning shift siang.</p>\r\n\r\n<p><br />\r\n&nbsp;<br />\r\nJOB PENDING</p>\r\n\r\n<p>- Pengujian QC Buttress BP89<br />\r\n- Maintance tanki air, vacuum, kompresor, volume change TXL.(bisa?)<br />\r\n- Ingatkan untuk slopping titik jatuh line 2 Selatan. Terutama untuk posisi exca yang berapa di 1 line<br />\r\n- Stackout untuk pelebaran sisi Selatan buttress BP89 bagian Timur.<br />\r\n- Cek geometri buttress hasil pekerjaan malam.<br />\r\n- Maintance hidrolik CBR ke fabrikasi dan test hidrolik warna abu. (URGENT)<br />\r\n- Pembersihan oven. (Kembali ke shift malam)<br />\r\n- Tanyakan apakah kita sudah ada meeting mengenai penyesuaian banyaknya material mesin FP dengan alat berat kita. Jika ada MOMnya bisa kirim untuk disosialisasikan. (ada?)<br />\r\n- Perbaiki manajement folder data lab</p>\r\n\r\n<p>440/m3 split<br />\r\n250/m3 rangkas&nbsp;</p>\r\n', '1770400510_Screenshot 2026-02-07 025111.jpg', '2026-02-06 17:55:10', 'Instrument & Geotechnical', '2026-02-06 17:55:10', NULL, 'pending', NULL, NULL),
(244, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 07/06/2026', '<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65 (Prioritas)</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan (Prioritas)</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 07 Februari 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 83 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1770454725_skema oprasi februari 2026.jpg', '2026-02-07 08:58:45', 'Tailing Facility Planning', '2026-02-07 08:58:45', NULL, 'pending', NULL, NULL),
(245, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Pagi 07/02/2026', '<p><strong>Info :</strong></p>\r\n\r\n<ul>\r\n	<li>07.30 seluruh anggota inspeksi K3LH all area DSTF P23 dan P89</li>\r\n	<li>proses dimulai 11.15, off 18.00</li>\r\n	<li>kuras kolam 5 &amp; 7 bekas shift malam stop 11.15, on kembali 18.10 sampai akhir shift tetap on</li>\r\n	<li>analisa lab</li>\r\n	<li>pengecoran lantai depan kontainer Toba 1</li>\r\n	<li>baterai HORIBA sempat lowbat dan sudah diganti baterainya</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Job Pending :</strong></p>\r\n\r\n<ul>\r\n	<li>lanjut proses sampai akhir shift</li>\r\n	<li>stop pengurasan sebelum proses jalan</li>\r\n	<li>sampling dan monitoring</li>\r\n	<li>akhir shift pompa lanjut kuras kolam 5 &amp; 7</li>\r\n	<li>lanjut cor bagian depan kontainer sampai ujung (tangga depan papan monitoring) ; kemiringan coran lantai landai ke arah saluran (selatan</li>\r\n</ul>\r\n', '1770481719_WhatsApp Image 2026-02-07 at 18.13.35.jpeg', '2026-02-07 16:28:39', 'Waste Water Treatment Plant', '2026-02-07 16:28:39', NULL, 'pending', NULL, NULL),
(246, 0, 2, 24, 'BA Overshift Instrument & Geotechnical Shift Malam 07/02/2026', '<p>Kegiatan Hari Ini:</p>\r\n\r\n<p>- Monitoring Titik Jatuh Line 1 dan 2</p>\r\n\r\n<p>- Tumbuk sampel kering untuk Proctor</p>\r\n\r\n<p>- Pengawasan Kontruksi Buttress BP89</p>\r\n\r\n<p>- Pengambilan Sampel dan Progress MC Line 1 dan 2</p>\r\n\r\n<p>- Olah data CPTu tanggal 2 dan 5 Februari</p>\r\n\r\n<p>- House Keeping</p>\r\n\r\n<p>Temuan :</p>\r\n\r\n<p>- Titik Jatuh Line 2 Masih Tinggi</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Job Pending :</p>\r\n\r\n<p>- Monitoring Titik JAtuh LIne 1 dan 2</p>\r\n\r\n<p>- Pemadatan Buttress B P89</p>\r\n\r\n<p>- Pembuatan area Pengujian CPTu di B P89</p>\r\n\r\n<p>- Pemindahan Shelter dan CPTu ke titik uji selanjutnya</p>\r\n\r\n<p>- Pengujian kepadatan di Buttress dan Timbunan Dry Tail</p>\r\n', '1770499372_WhatsApp Image 2026-02-07 at 21.30.49 (1).jpeg', '2026-02-07 21:22:52', 'Instrument & Geotechnical', '2026-02-07 21:22:52', NULL, 'pending', NULL, NULL),
