(251, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 07/02/2026', '<p><strong>Info :</strong><br />\r\n<br />\r\n- lanjut proses sampai 03:00<br />\r\n- sampling dan monitoring<br />\r\n- akhir shift pompa lanjut kuras kolam 5 &amp; 7<br />\r\n- cor bagian depan kontainer sampai ujung tangga</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n', '', '2026-02-08 21:09:46', 'Waste Water Treatment Plant', '2026-02-08 21:09:46', NULL, 'pending', NULL, NULL),
