(253, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Pagi 08/02/2026', '<p>Info<br />\r\n- pengambilan semen &amp; pasir (dumping depan rumah genset)<br />\r\n- pengambilan batako 2000 pcs untuk dinding Lab (dumping dekat Mega tower)<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- analisa lab&nbsp;<br />\r\n- cuti Ikbal dari Nikel sulfat yg atur, besok diinfokan dari firman nya, pak Ricko</p>\r\n\r\n<p>Job pending&nbsp;<br />\r\n- setting pompa kolam 2 (pasang lagi selangnya, buang yg bekas bocornya)<br />\r\n- lanjut kuras kolam 2, 5, 7<br />\r\n- pengecoran tanggul overflow kolam 2-3<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch</p>\r\n', '1770626690_WhatsApp Image 2026-02-08 at 11.55.40.jpeg', '2026-02-09 08:44:50', 'Waste Water Treatment Plant', '2026-02-09 08:44:50', NULL, 'pending', NULL, NULL),
