(257, 0, 2, 26, 'BA Overshift Instrument & Geotechnical Shift Pagi 11/02/2026', '<p>Job Hari ini:<br />\r\nSC BP23 dan CP23<br />\r\nMaintenance CBR<br />\r\nPembacaan konsolidasi<br />\r\nSieve CPTu B.14 kedalaman 18<br />\r\nSieve Line 1 dan 2<br />\r\nFinishing pembacaan hidro&nbsp;<br />\r\nPengujian proctor modif revisi line 1 (1-3)<br />\r\nPemadatan buttress B P89<br />\r\nPengujian triaxial line 2<br />\r\nPengujian triaxial revisi CPTu<br />\r\n<br />\r\nTemuan:<br />\r\nTumpukan line 2 tinggi<br />\r\n<br />\r\nJob pending:<br />\r\nAbsensi tanggal 1-10 februari<br />\r\nMaintenance hammer proctor modif<br />\r\nPengujian proctor line 1 (Kadar air 30%)<br />\r\nPembersihan lab</p>\r\n', '1770802095_WhatsApp Image 2026-02-11 at 10.09.05.jpeg', '2026-02-11 09:33:50', 'Instrument & Geotechnical', '2026-02-11 09:33:50', NULL, 'pending', NULL, NULL),
(258, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Malam 11/02/2026', '<p>Pekerjaan Hari ini</p>\r\n\r\n<p>&bull; Proctor Lanjutan</p>\r\n\r\n<p>&bull; Preparasi Hidrometer</p>\r\n\r\n<p>&bull; Pengambilan dan progress FIlterpress LIne 1 dan Line 2</p>\r\n\r\n<p>&bull; Pemadatan, QC, dan Konstruksi Buttress B P89</p>\r\n\r\n<p>&bull; Monitoring Titik Jatuh Line 1 dan Line 2</p>\r\n\r\n<p>Temuan</p>\r\n\r\n<p>&bull; Hujan hingga pukul 12 malam</p>\r\n\r\n<p>&bull; Titik jatuh line 2 memggunung</p>\r\n\r\n<p>Job Pending</p>\r\n\r\n<p>&bull; Cek titik jatuh Line 1 selatan, pasca hujan semalam sudah di cutting material lembek, perlu di cek lagi apakah ada pergerakan atau retakan</p>\r\n\r\n<p>&bull; Kompaksi maksimal dan uji buttress B P89</p>\r\n\r\n<p>&bull; Sieve Sampel Hidro</p>\r\n\r\n<p>&bull; Pembersihan Mold Permeability</p>\r\n\r\n<p>&bull; Weekly kita yang gabungin, planner dan hidro udah, kurang geotek dan ipal</p>\r\n\r\n<p>&bull; Olahan data cptu diskusi w/ pak agus</p>\r\n\r\n<p>&bull; Cek absensi</p>\r\n', '1770843679_WhatsApp Image 2026-02-12 at 02.02.39.jpeg', '2026-02-11 21:01:19', 'Instrument & Geotechnical', '2026-02-11 21:01:19', NULL, 'pending', NULL, NULL),
(259, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Malam 11/02/2026', '<p>Pekerjaan Hari ini</p>\r\n\r\n<p>&bull; Proctor Lanjutan</p>\r\n\r\n<p>&bull; Preparasi Hidrometer</p>\r\n\r\n<p>&bull; Pengambilan dan progress FIlterpress LIne 1 dan Line 2</p>\r\n\r\n<p>&bull; Pemadatan, QC, dan Konstruksi Buttress B P89</p>\r\n\r\n<p>&bull; Monitoring Titik Jatuh Line 1 dan Line 2</p>\r\n\r\n<p>Temuan</p>\r\n\r\n<p>&bull; Hujan hingga pukul 12 malam</p>\r\n\r\n<p>&bull; Titik jatuh line 2 memggunung</p>\r\n\r\n<p>Job Pending</p>\r\n\r\n<p>&bull; Cek titik jatuh Line 1 selatan, pasca hujan semalam sudah di cutting material lembek, perlu di cek lagi apakah ada pergerakan atau retakan</p>\r\n\r\n<p>&bull; Kompaksi maksimal dan uji buttress B P89</p>\r\n\r\n<p>&bull; Sieve Sampel Hidro</p>\r\n\r\n<p>&bull; Pembersihan Mold Permeability</p>\r\n\r\n<p>&bull; Weekly kita yang gabungin, planner dan hidro udah, kurang geotek dan ipal</p>\r\n\r\n<p>&bull; Olahan data cptu diskusi w/ pak agus</p>\r\n\r\n<p>&bull; Cek absensi</p>\r\n', '1770843679_WhatsApp Image 2026-02-12 at 02.02.39.jpeg', '2026-02-11 21:01:19', 'Instrument & Geotechnical', '2026-02-11 21:01:19', NULL, 'pending', NULL, NULL),
(260, 0, 2, 26, 'BA Overshift Instrument & Geotechnical Shift Pagi 12/02/2026', '<p>Job Hari ini:<br />\r\nPengujian sieve<br />\r\nPembersihan Mold Permeability<br />\r\nWeekly udah direvisi dan dicollect. Tinggal PPT, Pak agus selesai review jam 6 sore<br />\r\nAbsensi done<br />\r\nPengujian triaxial B.02 P89 kedalaman 14 - 14.5 m<br />\r\nPengujian direct shear CPTu B.01 kedalaman 10 - 10.5 m<br />\r\n<br />\r\nJob pending:<br />\r\nPembacaan hidro CPTu B.02 P89<br />\r\nLanjut proctor<br />\r\nPembacaan reloading konsol<br />\r\nLanjut dumping slag di A P23</p>\r\n', '1770887540_WhatsApp Image 2026-02-12 at 15.57.59 (1).jpeg', '2026-02-12 09:12:20', 'Instrument & Geotechnical', '2026-02-12 09:12:20', NULL, 'pending', NULL, NULL),
(261, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 12/02/2026', '<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres B P89 RL 60-65 (Prioritas)</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan (Prioritas)</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 12 Februari 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 83 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1770888593_skema oprasi februari 2026.jpg', '2026-02-12 09:29:53', 'Tailing Facility Planning', '2026-02-12 09:29:53', NULL, 'pending', NULL, NULL),
(262, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 11/02/2026', '<p>info :</p>\r\n\r\n<ul>\r\n	<li>Sampling dan Monitoring</li>\r\n	<li>Pengecoran Tanggul Overflow kolam 2-3 (baru di bikin pondasi dan isi dasar sedikit) masih harus nunggu kering, pembikinan pondasi lama karena tidak ada material batu (batu yang distock kecil)</li>\r\n	<li>Valve sudah di dekat chemical fasility belum di pasang dikarenakan longgar dan sudah disesuaikan posisinya. pemasangan bisa nanti</li>\r\n	<li>Cicil Laporan Weekly report</li>\r\n	<li>Outlet kondisi air sudah tidak keluar</li>\r\n	<li>Kirim email sampel masuk ke enviro</li>\r\n</ul>\r\n', '1770929711_photo_6086682130269278637_y.jpg', '2026-02-12 20:55:11', 'Waste Water Treatment Plant', '2026-02-12 20:55:11', NULL, 'pending', NULL, NULL),
(263, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 12/02/2026', '<p>Info :</p>\r\n\r\n<ul>\r\n	<li>Sampling dan monitoring</li>\r\n	<li>Stock pasir 3 bucket di depan chemical facility</li>\r\n	<li>Plester saluran dalam chemical facility</li>\r\n</ul>\r\n', '1770929859_sa.jpeg', '2026-02-12 20:57:39', 'Waste Water Treatment Plant', '2026-02-12 20:57:39', NULL, 'pending', NULL, NULL),
(264, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Malam 12/02/2026', '<p>Pekerjaan Hari Ini<br />\r\n- Pembacaan Hidrometer<br />\r\n- Reloading konsolidasi<br />\r\n- Direct Shear Line 2<br />\r\n- Monitoring Area Operasi<br />\r\n- Konstruksi Buttress B P89<br />\r\n- Pengambilan, Foto, dan Progress Filterpress<br />\r\n- Stock Slag<br />\r\nTemuan<br />\r\n- Air di Konveyor<br />\r\n- Tumpukan tinggi Line 2<br />\r\n- Slurry sempat ke 12 meter</p>\r\n\r\n<p>Job Pending<br />\r\n- Coba uji hidrometer sampel yang sama menggunakan tabung yang beda, kek beda gitu bacanya<br />\r\n- Lanjut Direct Shear<br />\r\n- Rev Layer CPTu, misal udah fix masukin ke weekly yang udah di compile<br />\r\n- Reloading Konsolidasi, beban terakhir, lanjut setting. Keknya tanah dasar di B P89 dulu deh</p>\r\n', '1770931597_WhatsApp Image 2026-02-13 at 00.46.30.jpeg', '2026-02-12 21:26:37', 'Instrument & Geotechnical', '2026-02-12 21:26:37', NULL, 'pending', NULL, NULL),
(265, 0, 2, 37, 'BA Overshift Instrument & Geotechnical Shift Malam 17/02/2026', '<p>Divisi: Geotek<br />\r\nTanggal:18 Februari 2026<br />\r\nShift: Malam</p>\r\n\r\n<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- Uji MC FP shift malam<br />\r\n- Pembersihan area Geotech<br />\r\n- Konstruksi Buttress BP89<br />\r\n- Monitoring area aktif<br />\r\n- Nyicil FK weekly</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>- Area spreadingan masih aman. Namun, banyak area yang kurang terkompaksi<br />\r\n- Lokasi trimingan ada di comp C P23 area tengah bagian selatan.<br />\r\n- Layer batu pada sisi Timur Buttress B P89 bagian bawah.<br />\r\n- Material sudah didorong dengan dozer pada area titik jatuh line 2 Selatan.<br />\r\n- Hasil kalibrasi pycnometer ada yang tidak masuk akal.<br />\r\n- Data TXL UU dan Probabilitas februari 2026 belum ada, sudah tanggal 18 Feb.<br />\r\n- FK CB, CC, CD P89 sudah di kerjakan, ada di file biasanya N:\\DSTF\\06. Geotech Engineering\\1. DSTF\\4.Geotech Engineering\\4. Safety Factor Compartment</p>\r\n\r\n<p><br />\r\n&nbsp;<br />\r\nJOB PENDING</p>\r\n\r\n<p>- QC Buttress BP89 dan infokan jangan terlalu tebal ketika layernya. Uji CBR biar ada datanya kalo tidak hujan.<br />\r\n- Area yang kurang di kompaksi tolong di kompak dengan dozer.<br />\r\n- Lereng dibawah bukit tanjung harus dimaintance, dan pasang safety line 2 meter dari toe.<br />\r\n- Pastikan lagi area terdampak di line 1 selatan.<br />\r\n- Infokan untuk pembuatan bench pada timbunan titik jatuh. Setidaknya ada bench terlebih dahulu. atau kasih safety line.<br />\r\n- Minta pipa ke fabrikasi dekat 101 untuk SC.<br />\r\n- Kalibrasi ulang pycnometer.<br />\r\n- progress data prob dan txl uu Feb 2026, sampai sekarang belum ada datanya.</p>\r\n', '', '2026-02-18 10:44:53', 'Instrument & Geotechnical', '2026-02-18 10:44:53', NULL, 'pending', NULL, NULL),
(266, 0, 2, 37, 'BA Overshift Instrument & Geotechnical Shift Malam 16/02/2026', '<p>Divisi: Geotek<br />\r\nTanggal:16 Februari 2026<br />\r\nShift: Malam</p>\r\n\r\n<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- Uji MC FP shift malam<br />\r\n- Pembersihan area Geotech<br />\r\n- Dumping Slag<br />\r\n- Konstruksi Buttress BP89<br />\r\n- Perbantuan area trimingan<br />\r\n- Monitoring area aktif<br />\r\n- Pengujian SF CPTu 03 BP89 (h 6&amp;8m)<br />\r\n- Input dan analisis data SC dan ritasi</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>- lokasi dumping slag pindah sebanyak 3 kali.<br />\r\n- Lokasi trimingan ada di comp C P23 area tengah bagian selatan.<br />\r\n- Layer batu pada sisi Timur Buttress B P89.<br />\r\n- Area titik jatuh line 2 bagian timbunan dekat jalan turunan masih belum ada bench. Terdapat retakan memanjang.<br />\r\n- Material cukup baik. Namun, PA buruk sehingga material menumpuk sampai Cut.<br />\r\n- Hasil kalibrasi pycnometer ada yang tidak masuk akal.</p>\r\n\r\n<p><br />\r\n&nbsp;<br />\r\nJOB PENDING</p>\r\n\r\n<p>- Infokan untuk planning area dumpingan ke tim planner agar info tim siang dan malam tidak beda.<br />\r\n- QC Buttress BP89 dan infokan jangan terlalu tebal ketika layernya. Uji CBR biar ada datanya<br />\r\n- Infokan untuk pembuatan bench pada timbunan titik jatuh. Setidaknya ada bench terlebih dahulu.<br />\r\n- Minta pipa ke fabrikasi dekat 101 untuk SC.<br />\r\n- Cek apakah tumpukan material line 2 makin bertambah lagi.<br />\r\n- Pindah shelter comp BP23 ke sisi Barat Butt BP23<br />\r\n- Kalibrasi ulang pycnometer.</p>\r\n', '', '2026-02-18 10:44:12', 'Instrument & Geotechnical', '2026-02-18 10:44:12', NULL, 'pending', NULL, NULL),
(267, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 20/02/2026', '<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres A P89 RL 60-65 (Prioritas)</li>\r\n	<li>Fill batu di parkiran (Jika buttress A Belum Ready)</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan (Prioritas)</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 20 Februari 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 83 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1771579934_WhatsApp Image 2026-02-18 at 18.27.25.jpeg', '2026-02-20 09:32:14', 'Tailing Facility Planning', '2026-02-20 09:32:14', NULL, 'pending', NULL, NULL),
(268, 0, 2, 24, 'BA Overshift Instrument & Geotechnical Shift Malam 22/02/2026', '<p>Divisi: Geotek<br />\r\nTanggal:21 Februari 2026<br />\r\nShift: Malam</p>\r\n\r\n<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- Uji MC FP shift malam<br />\r\n- Extrude sampel CPTu<br />\r\n- Pembersihan area Geotech<br />\r\n- Perbantuan Trimingan Buttress B P89<br />\r\n- Pembersihan konus CPTu<br />\r\n- Monitoring area aktif<br />\r\n- Pengambilan sampel Filter Press dan Progress sampel FP</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>- Titik jatuh line 2 Masih Tinggi<br />\r\n- Hujan Deras Di Jam Ke 2</p>\r\n\r\n<p>JOB PENDING<br />\r\n- Penyempurnaan kail pengambil sampel cptu, &nbsp;tambah lubang baut lagi dan lubang slingnya diperdalam&nbsp;<br />\r\n- Pindah CPTu dan pengambilan sampel &nbsp;03 (kedalaman 08,11,16)<br />\r\n- Cptu servis koordinasi dengan nuel terkait filtersolarnya karena saat ini low power (Setelah pengambilan sampel)<br />\r\n- Persiapkan titik cptu di compartment C<br />\r\n&nbsp;</p>\r\n', '1771709554_WhatsApp Image 2026-02-21 at 21.16.56.jpeg', '2026-02-21 21:33:29', 'Instrument & Geotechnical', '2026-02-21 21:33:29', NULL, 'pending', NULL, NULL),
(269, 0, 2, 37, 'BA Overshift Instrument & Geotechnical Shift Pagi 22/02/2026', '<p>Divisi: Geotek<br />\r\nTanggal:22 Februari 2026<br />\r\nShift: Siang</p>\r\n\r\n<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- Uji MC FP shift siang<br />\r\n- Pembersihan area Geotech<br />\r\n- Perbantuan tim EW<br />\r\n- Pemantauan titik jatuh line 1 dan 2<br />\r\n- Monitoring area aktif<br />\r\n- Pengujian laboratorium<br />\r\n- CPTu</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>- Sistem tekanan angin TXL bocor semenjak maintance oleh bu Susett. Kompresor lebih intens menyala.<br />\r\n- Material basah ketika hujan dan kering ketika hujan berhenti.<br />\r\n- Exca di area parkiran depan ditarik ke elv 90mdpl, sehingga tidak bisa maintance saluran dan perapihan slag.<br />\r\n- Perbantuan di BP89.<br />\r\n- Shelter CPTu sudah pindah dan sudah ambil sampel.<br />\r\n- Pengujian DST, Density, MC, Hidro, dan konsolidasi.<br />\r\n- Lereng drytail banyak yang meleleh.<br />\r\n- Hujan di pagi hari, jadi ga SC.</p>\r\n\r\n<p><br />\r\nJOB PENDING</p>\r\n\r\n<p>- Monitoring titik jatuh line 1 dan 2<br />\r\n- Pengujian LLPL CPTU.04 P89<br />\r\n- Halusin sampel proctor yang sudah kering<br />\r\n- Pembersihan laboratorium.<br />\r\n- Masukin data SC yang ada di meja.</p>\r\n', '', '2026-02-22 09:28:35', 'Instrument & Geotechnical', '2026-02-22 09:28:35', NULL, 'pending', NULL, NULL),
(270, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Pagi 22/02/2026', '<p>Info<br />\r\n- proses sampai akhir shift (valve tanggul overflow kolam 2-3 sudah ditutup)<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- analisa lab&nbsp;<br />\r\n- angkat pompa submersible kolam 5, kondisi pompa normal (EID belum sempat cek)<br />\r\n- stok bata di dekat saluran geotube&nbsp;<br />\r\n- stok semen 1 jumbo bag di dekat saluran geotube&nbsp;<br />\r\n- masker, sarung tangan krisbow, sarung tangan kuning sudah dibagikan, yg shift malam sudah ditulis namanya)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Job pending&nbsp;<br />\r\n- lanjut proses&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- susun bata saluran geotube (material pasir, semen, bata sudah siap)</p>\r\n', '1771837420_WhatsApp Image 2026-02-22 at 12.06.34.jpeg', '2026-02-23 09:03:40', 'Waste Water Treatment Plant', '2026-02-23 09:03:40', NULL, 'pending', NULL, NULL),
(271, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 23/02/2026', '<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling line 2 : Kompartemen C P89 dari turunan buttress C&nbsp;: &nbsp;arah dorongan ke utara</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P89 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres A P89 RL 60-65 (Prioritas)</li>\r\n	<li>Fill batu di parkiran (Jika buttress A Belum Ready)</li>\r\n	<li>Cutting material tailing titik jatuh lama line 1 selatan (Prioritas)</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 20 Februari 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 83 - elevasi dekat air 62</li>\r\n	<li>- Kompartemen C P89 dari jl 70 tengah : &nbsp;elevasi 68,5-69,5</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '', '2026-02-23 09:11:22', 'Tailing Facility Planning', '2026-02-23 09:11:22', NULL, 'pending', NULL, NULL),
(272, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 23/02/2026', '<p><strong>Info :</strong>&nbsp;</p>\r\n\r\n<ul>\r\n	<li>Proses dari jam 23:00 sampai akhir shift&nbsp;</li>\r\n	<li>Pampling dan monitoring&nbsp;</li>\r\n	<li>Pemantauan vnotch&nbsp;</li>\r\n	<li>Jcc 1 orang : fendi&nbsp;</li>\r\n	<li>Pengelasan tiang handrail&nbsp;</li>\r\n	<li>Konstruksi saluran geotube</li>\r\n</ul>\r\n', '1771881658_WhatsApp Image 2026-02-24 at 02.36.37.jpeg', '2026-02-23 21:20:58', 'Waste Water Treatment Plant', '2026-02-23 21:20:58', NULL, 'pending', NULL, NULL);
INSERT INTO `berita` (`id_berita`, `iduser`, `id_kategori`, `id_user`, `judul`, `isi_berita`, `gambar`, `tgl_posting`, `plan`, `updated_at`, `deleted_at`, `status`, `approved_by`, `approved_at`) VALUES
(273, 0, 8, 32, 'BA Overshift Tailing Facility Planning Shift Pagi 24/02/2026', '<p><strong>Line 1 ke Line 1 Selatan&nbsp;:</strong></p>\r\n\r\n<ul>\r\n	<li>Spreading line 1 Selatan menekan ke arah&nbsp;air&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 1 ke Line 1 Utara :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 1 Utara : Jalan samping workshop (Prioritas)</li>\r\n	<li>Hauling line 1 Utara : kompartemen A megatower Arah dorongan WS baru</li>\r\n	<li>Hauling line 1 Utara : kompartemen A portal Point view Arah dorongan titik terendah&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Line 2 :</strong></p>\r\n\r\n<ul>\r\n	<li>Hauling Line 2 : Komprtemen C P23 jalur gaza : Arah dorongan ke timur</li>\r\n	<li>Hauling Line 2 : Komprtemen C P23 : Arah dorongan ke barat</li>\r\n	<li>Hauling Line 2 : Kompartemen C P23 dari jalan samping titik jatuh : arah dorongan ke timur&nbsp;</li>\r\n	<li>Hauling line 2 : Kompartemen D P89 : Arah dorongan ke timur (Opsi emergency jika hujan)&nbsp;</li>\r\n</ul>\r\n\r\n<p><strong>Konstruksi :</strong></p>\r\n\r\n<ul>\r\n	<li>Konstruksi Butres A P89 RL 60-65 (Prioritas)</li>\r\n	<li>Fill batu di parkiran (Opsi)</li>\r\n	<li>Cutting material tailing titik jatuh lama line 2 &nbsp;(Prioritas)</li>\r\n</ul>\r\n\r\n<p><strong>Update Elevasi Topo 20 Februari 2026:</strong></p>\r\n\r\n<ul>\r\n	<li>- Kompartemen B P89 titik jatuh line 1 selatan baru : elevasi titik jatuh 83 - elevasi dekat air 54</li>\r\n	<li>- Kompartemen C P23 dari jalur gaza : 89-86</li>\r\n	<li>- Kompartemen A P23 Megatower = 88- 89</li>\r\n	<li>- Kompartemen B P23 (titik jatuh utara) = 89-88</li>\r\n</ul>\r\n', '1771923024_skema oprasi week3 feb.jpeg', '2026-02-24 08:50:24', 'Tailing Facility Planning', '2026-02-24 08:50:24', NULL, 'pending', NULL, NULL),
(274, 0, 2, 37, 'BA Overshift Instrument & Geotechnical Shift Pagi 25/02/2026', '<p>Divisi: Geotek<br />\r\nTanggal:25 Februari 2026<br />\r\nShift: Siang</p>\r\n\r\n<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- MC FP shift siang<br />\r\n- SG, DSTF, dan Hidro sampel CPTu. 03 P89 h 10m<br />\r\n- Pembacaan konsolidasi<br />\r\n- Timbang dan MC sampel proctor line 2<br />\r\n- Mencari masalah di sistem kompresor triaxial<br />\r\n- Monitoring line 1 dan 2<br />\r\n- Trimming batu di buttress AP89<br />\r\n- Perbantuan perbaikan jalan di CP89<br />\r\n- SC dan SR di BP89<br />\r\n- Pengambilan pollywood bersama tim IPAL</p>\r\n\r\n<p>TEMUAN<br />\r\n- Pengujian Laboratorium SG, hidro, DST CPTu 04 h 14 meter<br />\r\n- Preparasi hidrometer<br />\r\n- Timbang sampel proctor line 2 dan ambil MC<br />\r\n- MC FP<br />\r\n- HK<br />\r\n- Shelter CPTu miring, monitoring dan pasang safety line<br />\r\n- SR dan SC di BP89<br />\r\n- Terdapat ppergerakan masif di line 1 Selatan<br />\r\n- Polywood dan pasir otawa 20 karung akan diambil besok dengan DT. Biar sekalian</p>\r\n\r\n<p><br />\r\nJOB PENDING<br />\r\n- Lanjut pembacaan konsolidasi<br />\r\n- Maintance jalur kompresor<br />\r\n- SG h 10 dan 14 meter. Ukur suhu dan timbang berat pycnometer<br />\r\n- Monitoring all area karena habis hujan besar<br />\r\n- Cek keborocan kompresor dengan bantuan air sabun. tandai saja besok pagi di maintance<br />\r\n- MC FP shift malam<br />\r\n- Cek weekly, kalo oke pindahkan ke folder report DSTF<br />\r\n&nbsp;</p>\r\n', '', '2026-02-25 08:36:47', 'Instrument & Geotechnical', '2026-02-25 08:36:47', NULL, 'pending', NULL, NULL),
(275, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 25/02/2026', '<p><strong>Info :</strong></p>\r\n\r\n<ul>\r\n	<li>Lanjut proses</li>\r\n	<li>Sampling dan monitoring&nbsp;</li>\r\n	<li>Pembacaan v-notch&nbsp;</li>\r\n	<li>Analisa Sampel air lindi DSTF&nbsp;</li>\r\n	<li>Sampel dekat gorong&quot; belum bisa di ambil , tidak ada turunan dan areanya tinggi</li>\r\n	<li>Kirim email sampel masuk ke enviro</li>\r\n</ul>\r\n', '1772052733_WhatsApp Image 2026-02-25 at 00.17.52.jpeg', '2026-02-25 20:52:13', 'Waste Water Treatment Plant', '2026-02-25 20:52:13', NULL, 'pending', NULL, NULL),
(276, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 26/02/2026', '<p><strong>Info :&nbsp;</strong></p>\r\n\r\n<ul>\r\n	<li>Proses sampai akhir shfit&nbsp;</li>\r\n	<li>Sampling dan monitoring&nbsp;</li>\r\n	<li>Pembacaan Vnotch &nbsp;</li>\r\n	<li>pengisian pam ke 7 karung ( di gudang chemical )</li>\r\n</ul>\r\n', '1772052790_WhatsApp Image 2026-02-26 at 00.15.57.jpeg', '2026-02-25 20:53:10', 'Waste Water Treatment Plant', '2026-02-25 20:53:10', NULL, 'pending', NULL, NULL),
(277, 0, 2, 37, 'BA Overshift Instrument & Geotechnical Shift Pagi 26/02/2026', '<p>Divisi: Geotek<br />\r\nTanggal:26 Februari 2026<br />\r\nShift: Siang</p>\r\n\r\n<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- Mencari masalah di sistem kompresor triaxial<br />\r\n- Monitoring line 1 dan 2<br />\r\n- Bantu trimingan di area AP23<br />\r\n- Pengambilan pollywood dan pasir otawa bersama tim IPAL<br />\r\n- Pengecatan area DSTF<br />\r\n- Pengujian laboratorium<br />\r\n- Pengukuran area yang mau di keramik<br />\r\n- Evakuasi shelter dan CPTu<br />\r\n- HK<br />\r\n- Inspeksi</p>\r\n\r\n<p>TEMUAN<br />\r\n- Pengujian Laboratorium SG (Suhu terlalu rendah jadi ulang di 26), sudah di oven, tinggal timbang kering besok pagi. Sampel CPTu.04 h 10 dan 14 m<br />\r\n- Konsolidasi di jam set 2 penambahan beban<br />\r\n- Proctor line 2 standar 3 layer @25 pukulan<br />\r\n- JCC hold karena inspeksi. kalo bisa malam<br />\r\n- Inspeksi area DSTF<br />\r\n- Progress MC FP<br />\r\n- Terdapat pergerakan masif di line 1 Selatan<br />\r\n- Ukuran yang mau di keramik XX<br />\r\n- Kebutuhan APD bulanan geotek bisa update di N:\\DSTF\\06. Geotech Engineering\\1. DSTF\\12. Administrasi\\7. APD &amp; ATK\\APD\\2026\\1. Kebutuhan APD Bulanan. Untuk Maret sudah di update.<br />\r\n- SC, ritasi, MC sudah di rekap<br />\r\n- Pencucian cawan<br />\r\n- Preparasi sampel hidrometer CPTu.04 BP89 h 10 dan 14 m<br />\r\n- Kompresor belum di pegang, tapi udah di matikan.<br />\r\n- Ada batu menggantung di elv 90 Barat BP89<br />\r\n- Adanya lelehan material di titik jatuh line 2 Selatan.<br />\r\n- CPTu sudah di kontener<br />\r\n- Barang warehouse sudah di ambil semua</p>\r\n\r\n<p><br />\r\nJOB PENDING</p>\r\n\r\n<p>- Pengambilan aquades (Saran yang di lapangan 1 orang aja atau full di lab. karena jalan licin)<br />\r\n- Ingetin yang udah selesai pengujian ceklis di kertas lab<br />\r\n- Hitung banyak penambahan air proctor dan pengujian proctor<br />\r\n- Monthly PPT cicil sebisanya<br />\r\n- K3LH di rekap dulu lah</p>\r\n', '', '2026-02-26 08:07:01', 'Instrument & Geotechnical', '2026-02-26 08:07:01', NULL, 'pending', NULL, NULL),
(278, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 27/02/2026', '<p>Info : &nbsp;</p>\r\n\r\n<p><br />\r\n- konstruksi tanggul overflow kolam 2-3 dan sudah selesai<br />\r\n- proses 50:50 sampai akhir shift&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch<br />\r\n- belum lem pipa yg bocor.</p>\r\n', '1772397416_WhatsApp Image 2026-02-28 at 06.52.23.jpeg', '2026-03-01 20:36:56', 'Waste Water Treatment Plant', '2026-03-01 20:36:56', NULL, 'pending', NULL, NULL),
(279, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 28/02/2026', '<p><strong>Info:&nbsp;</strong></p>\r\n\r\n<ul>\r\n	<li>Proses sampai akhir shift 50:50&nbsp;</li>\r\n	<li>Sampling dan monitoring&nbsp;</li>\r\n	<li>Pembacaan vnotch&nbsp;</li>\r\n	<li>Perapian depan chemical facility&nbsp;</li>\r\n	<li>Perapian area depan rumah genset&nbsp;</li>\r\n	<li>Pembagian penilaian (arul, andiman, rahdin, efrindo, awang, daurih)</li>\r\n	<li>Sosialisasi tentang connec wifi dan obicard</li>\r\n</ul>\r\n', '1772397594_WhatsApp Image 2026-03-01 at 04.42.33.jpeg', '2026-03-01 20:39:54', 'Waste Water Treatment Plant', '2026-03-01 20:39:54', NULL, 'pending', NULL, NULL),
(280, 0, 7, 23, 'BA Overshift Waste Water Treatment Plant Shift Malam 01/03/2026', '<p>info:&nbsp;<br />\r\n<br />\r\n- Proses sampai akhir shift 50:50&nbsp;<br />\r\n- Sampling dan monitoring&nbsp;<br />\r\n- Pembacaan vnotch&nbsp;<br />\r\n- Perapian kabel pompa bypass<br />\r\n- Sosialisasi training Safety K3L</p>\r\n', '1772397990_WhatsApp Image 2026-03-02 at 00.20.45.jpeg', '2026-03-01 20:46:30', 'Waste Water Treatment Plant', '2026-03-01 20:46:30', NULL, 'pending', NULL, NULL),
(283, 0, 7, 33, 'BA Overshift Waste Water Treatment Plant Shift Malam 07/03/2026', '<p>Pekerjaan&nbsp;<br />\r\n- Sampling &amp; Monitoring&nbsp;<br />\r\n- Pengecoran Chemical Facility&nbsp;</p>\r\n\r\n<p>- Pembersihan Chemical Facility</p>\r\n', '1772913194_WhatsApp Image 2026-03-07 at 21.15.58.jpeg', '2026-03-07 19:53:14', 'Waste Water Treatment Plant', '2026-03-07 19:53:14', NULL, 'pending', NULL, NULL),
