(285, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Pagi 12/03/2026', '<p>Divisi: Geotek<br />\r\nTanggal:12 Maret 2026<br />\r\nShift: Siang</p>\r\n\r\n<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- Monitoring line 1 dan 2<br />\r\n- Bantu trimingan batu di AP89<br />\r\n- Pengujian laboratorium<br />\r\n- Maintance alat<br />\r\n- HK</p>\r\n\r\n<p>TEMUAN<br />\r\n- HK<br />\r\n- Monitoring line 1 dan 2&nbsp;<br />\r\n- Olah ritasi dan fragmentasi batu<br />\r\n- Belum bisa cuci piezocone<br />\r\n- Pembacaan konsolidasi<br />\r\n- Alat sikat galon diambil oleh Ius<br />\r\n- Spesifikasi UR sudah di sesuaikan<br />\r\n- Crane pending karena full jadwal<br />\r\n- Semua FP kancing<br />\r\n- LLPL CPTu04 h 11 CP23<br />\r\n- Hidrometer CPTu 04 h 11 dan 17. Besok pembacaan<br />\r\n- Maintance triaxial. Namun, kompresor belum<br />\r\n- Sampel GS CPTu 04 h 5 dan 11 CP23<br />\r\n- Pengambilan MC CPTu 04 h 14 17 21 CP23<br />\r\n- Oven LLPL sampel CPTu<br />\r\n- CPTu salah masukin data</p>\r\n\r\n<p>JOB PENDING</p>\r\n\r\n<p>- Monitoring line 1 dan 2&nbsp;<br />\r\n- FP line 1 dan 2<br />\r\n- Olah data CPTu 05 CP23<br />\r\n- Jika ada yang mau di UR bisa dimasukin ke folder UR Geotech<br />\r\n- Masukin data lab dan monitoring yang belum diinput<br />\r\n- pisahkan form yang udah di input dan belum, biar siang kita beresin<br />\r\n- Ambil aquades sebanyak&quot;nya sampe kembung<br />\r\n- Pembacaan reloading konsolidasi<br />\r\n- HK<br />\r\n- MC FP untuk ke teknologi mesin 10, belum di ambil. sisanya seperti biasa<br />\r\n- Proctor</p>\r\n', '1773305560_WhatsApp Image 2026-03-12 at 16.29.14.jpeg', '2026-03-12 08:52:40', 'Instrument & Geotechnical', '2026-03-12 08:52:40', NULL, 'pending', NULL, NULL),
(287, 0, 7, 33, 'BA Overshift Waste Water Treatment Plant Shift Malam 13/03/2026', '<p>Info Pekerjaan</p>\r\n\r\n<p>- Proses Pengolahan lindi&nbsp;<br />\r\n- Sampling &amp; Monitoring&nbsp;<br />\r\n&nbsp;</p>\r\n', '1773436220_WhatsApp Image 2026-03-13 at 23.10.28.jpeg', '2026-03-13 21:10:20', 'Waste Water Treatment Plant', '2026-03-13 21:10:20', NULL, 'pending', NULL, NULL),
