(289, 0, 7, 22, 'BA Overshift Waste Water Treatment Plant Shift Pagi 25/02/2026', '<p>Info<br />\r\n- proses sampai akhir shift&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- analisa lab<br />\r\n- tim EID pengecekan pompa submersible kolam 5 (impeller dan electrical pompa aman)</p>\r\n\r\n<p>Job pending&nbsp;<br />\r\n- proses&nbsp;<br />\r\n- sampling dan monitoring&nbsp;<br />\r\n- pembacaan v-notch</p>\r\n', '1773499082_WhatsApp Image 2026-02-25 at 11.45.16.jpeg', '2026-03-14 14:38:02', 'Waste Water Treatment Plant', '2026-03-14 14:38:02', NULL, 'pending', NULL, NULL),
