(305, 0, 2, 20, 'BA Overshift Instrument & Geotechnical Shift Malam 14/03/2026', '<p>PEKERJAAN HARI INI</p>\r\n\r\n<p>- Kalibrasi Pycno</p>\r\n\r\n<p>- Monitoring Area Line 1</p>\r\n\r\n<p>- QC Buttress</p>\r\n\r\n<p>- MC Filterpress</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>JOB PENDING</p>\r\n\r\n<p>- Pekerjaan Lab&nbsp; =&nbsp;<br />\r\nSpecific Gravity Line 2<br />\r\nLLPL CP23.04 1, 5, 8<br />\r\nDirect Shear 1,5 , 8 , 11<br />\r\n- Untuk obi card digemborkan lagi, belum ada penambahan lagi</p>\r\n\r\n<p>- Sandcone di area line 1 misalkan ada orang</p>\r\n', '', '2026-03-14 21:22:46', 'Instrument & Geotechnical', '2026-03-14 21:22:46', NULL, 'pending', NULL, NULL),
(306, 0, 2, 37, 'BA Overshift Instrument & Geotechnical Shift Pagi 14/03/2026', '<p>Divisi: Geotek<br />\r\nTanggal: 14 Maret 2026<br />\r\nShift: Siang</p>\r\n\r\n<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- Monitoring line 1 dan 2<br />\r\n- Konstruksi buttress BP89<br />\r\n- Pengujian laboratorium<br />\r\n- Maintance alat<br />\r\n- HK</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>- Olah ritasi dan fragmentasi batu<br />\r\n- Belum bisa cuci piezocone<br />\r\n- Maintance triaxial. Namun, kompresor belum. Kalo agak senggang bisa minta ke fabrikasi buat maintance<br />\r\n- Preparasi konsolidasi CPTu 04 CCP23 h 21-21.5m<br />\r\n- SPL tim tanggal 1-10 aman<br />\r\n- Buat word untuk CPTu 1 tahun<br />\r\n- IM Poster&nbsp;<br />\r\n- PS tidak mendapat alat<br />\r\n- UR CPTu aman<br />\r\n- UR filter solar aman, tinggal FU ke Jakarta<br />\r\n- Report CPTu besok malam dikerjakan<br />\r\n- kalibrasi pasir bulan Maret 2026<br />\r\n- Pembersihan halaman depan<br />\r\n- Pengujian CBR dan SR. Area tengah ke timur tidak masuk. tengah ke barat masuk<br />\r\n- Proctor line 2 modif sudah di proses<br />\r\n- Kalibrasi pynometer, belum semua<br />\r\n- Air aquades minta ke IPAL, kalo udah senggang akan ambil aquades<br />\r\n- Preparasi sampel GS CPTu 04 CP23 h (17 dan 21m)<br />\r\n- Pengujian LLPL CPTu 04 CP23 h 14m<br />\r\n- Pembacaan konsolidasi CPTu 04 CP23 h 21m<br />\r\n- Pembacaan Hidrometer CPTU 04 CP23 h 11 dan 17m<br />\r\n- Timbang proctor line 2 standar. MC sudah di ambil<br />\r\n- MC FP<br />\r\n- QC Buttress, kualitas kebanyakan OB, harus di tegur biar banyak gravel dan cobble<br />\r\n- Konstruksi di butt BP89<br />\r\n- Perbaikan atap oleh tim fabrikasi, crane sudah ada<br />\r\n- Monitoring line 1 dan 2<br />\r\n- Sudah laporan hasil pengujian MC FP line 1 mesin 10 ke teknologi oleh Erika<br />\r\n- Masalah barang reject di warehouse ONC udah clear</p>\r\n\r\n<p>JOB PENDING</p>\r\n\r\n<p>- Monitoring line 1 dan 2&nbsp;<br />\r\n- FP line 1 dan 2<br />\r\n- Jika ada