(318, 0, 2, 37, 'BA Overshift Instrument & Geotechnical Shift Pagi 20/03/2026', '<p>Divisi: Geotek<br />\r\nTanggal: 18 Maret 2026<br />\r\nShift: Siang</p>\r\n\r\n<p>PEKERJAAN HARI INI :</p>\r\n\r\n<p>- Monitoring line 1 dan 2<br />\r\n- Konstruksi buttress BP89<br />\r\n- Pengujian laboratorium<br />\r\n- perbantuan divisi&nbsp;<br />\r\n- Pekerjaan atap<br />\r\n- HK</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>- MC FP line 1 dan 2<br />\r\n- HK<br />\r\n- Atap udah di cat sebagian<br />\r\n- Nota sedang di fabrikasi dan Equip<br />\r\n- SG CPTu 04 CP23 h 5 dan 11m, tunggu mengendap<br />\r\n- cat atap dan potong<br />\r\n- PL CPTu CP23 h 5 m<br />\r\n- Pembacaan kosolidasi sisa unloading<br />\r\n- Obi card ada yang nyici;<br />\r\n- Penilaian tim selesai<br />\r\n&nbsp;-Nota dan IM semua clear<br />\r\n-&nbsp;</p>\r\n\r\n<p><br />\r\nJOB PENDING</p>\r\n\r\n<p>- HK<br />\r\n- Obi card<br />\r\n- Monitoring line 1 dan 2&nbsp;<br />\r\n- FP line 1 dan 2</p>\r\n\r\n<p>- Perapihan tailing sisi Utara dan selatan buttress CP89. WAJIB<br />\r\n- Campur air proctor line 1 standar<br />\r\n- Buat excel di share folder, jangan di sheet. Biar foreman copy juga progress mereka sampe mana. Kru biar sampaikan ke foreman<br />\r\n- Tabel lab diubah lagi, biar lebih mudah jika ada anomali di datanya. Agar ketika ada anomali, terlihat apakah di pengujian lainnya akan berubah juga. DLL. Jangan grafik anak SD.<br />\r\n- Mulai cari materi tentang density,MC, berhubungan dengan SG e n dari pengujian mekanik. C E Phi dari zona PI, Permea ddengan lainnya. Nantinya bisa jadi tabel validasi sekunder jika butuh perhitungan cepat tanpa pengujian aktual.<br />\r\n- Info perapihan sisi Utara CP89 apa? kenapa masih berantakan?<br />\r\n- SPL Tim<br />\r\n- List siapa aja yang masuk jam 7 10 dll, kirim ke pak kipli.</p>\r\n', '', '2026-03-20 09:42:07', 'Instrument & Geotechnical', '2026-03-20 09:42:07', NULL, 'pending', NULL, NULL),
(319, 0, 6, 18, 'BA Overshift Hydrology & Hydrogeology Shift Pagi 21/03/2026', '<p>Job 21 Maret 2026<br />\r\n&nbsp; &nbsp;1. Pemasangan kembali pipa buttres C P89--- reza<br />\r\n2. Running Pompa --- midun</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>*Notes Pekerjaan Harian*<br />\r\n-1 exca 200 / 1 long arm</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>*Pelanggaran / Izin*&nbsp;</p>\r\n\r\n<p>Jhonatan Libur</p>\r\n\r\n<p>Arnol Libur</p>\r\n\r\n<p>Tison izin anak sakit seminggu</p>\r\n\r\n<p>*Job Pending*<br />\r\n1. Pembuatan Perimeter Timur P89 --- &nbsp;on proggress&nbsp;<br />\r\n2. Saluran jalan 70 ---- Buat ulang karna ditimbun<br />\r\n4. Pembuatan saluran di jalan baru sisi barat kolam Pengolah Lindi --- Menunggu unit&nbsp;<br />\r\n5. â Tanggul underdrain -- on progress</p>\r\n\r\n<p>*Peralatan Pendukung*<br />\r\n1. Buat Pipa yg rencana dipakai (kalau bisa) tanyakan erika sampai mana progressnya</p>\r\n\r\n<p>*Remark*<br />\r\n1. Cek rembesan dari area Comp All<br />\r\n2. Cek Pipa vertikal (Khususnya area comp B P89) dan saluran<br />\r\n3. Kawal area Operasional khususnya area saluran (Saluran baru di jalan barat toba 1 dicek dan buatkan saluran agar air dari jalan masuk ke toe drain dahulu)</p>\r\n\r\n<p>*UR*</p>\r\n\r\n<p>*Safety*<br />\r\n* Jadwalkan untuk materi safety anggota&nbsp;</p>\r\n\r\n<p>*Umum*<br />\r\n2. Diskusikan dengan IR masalah eten</p>\r\n\r\n<p>*Notes Besok*&nbsp;<br />\r\n1. pemasangan &amp; setting kembali pipa buttres C P89<br />\r\n2. â perbaikan saluran finger samping 310<br />\r\n3. running pompa</p>\r\n', '1774085354_WhatsApp Image 2026-03-21 at 17.25.54.jpeg', '2026-03-21 09:29:14', 'Hydrology & Hydrogeology', '2026-03-21 09:29:14', NULL, 'pending', NULL, NULL),
(320, 0, 2, 12, 'BA Overshift Instrument & Geotechnical Shift Pagi 25/04/2026', '<p>PEKERJAAN HARI INI</p>\r\n\r\n<p>- QC Material Batu Buttress A P89</p>\r\n\r\n<p>- Monitoring All Area P89</p>\r\n\r\n<p>- Pengujian MC Filterpress</p>\r\n\r\n<p>- Pekerjaan Civil Laboratorium</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>- Area spreading compartement A P89 menumpuk dan menyebabkan perbedaan elevasi yang signifikan</p>\r\n\r\n<p>- Material titik jatuh line 1 dan 2 awal shift lembek</p>\r\n\r\n<p>- Slurry rendah di jam kedua</p>\r\n\r\n<p>- CLiq &amp; CPTe-IT belum ada progress dari tim IT</p>\r\n\r\n<p>- Hold pengujian kepadatan kompartemen<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>JOB PENDING</p>\r\n\r\n<p>- Re-test Gs CPTu.P23.CC.05 (20.00 - 20.50)</p>\r\n\r\n<p>- Pengujian ATT CPTu.P23.CC.05 (7.00 - 7.50, 13.00 - 13.50, 16.00 - 16.50, 20.00 - 20.50)</p>\r\n\r\n<p>- Pengujian Gz&nbsp;CPTu.P89.CB.02 ( 06.00 - 06.50, 14.00 - 14.50, 18.00 - 18.50)</p>\r\n\r\n<p>- Pengambilan, foto, dan progress sampel Filterpress Line 1, Line 2, dan Titik Jatuh</p>\r\n\r\n<p>- Monitoring area operasi (spreading unloading CA P89, Titik jatuh line 2, All area spreading, dan kondisi material)</p>\r\n\r\n<p>- Qc material Buttress A P89</p>\r\n', '1777107056_FILTERPRESS (1).jpg', '2026-04-25 08:50:56', 'Instrument & Geotechnical', '2026-04-25 08:50:56', NULL, 'pending', NULL, NULL),
(321, 0, 2, 12, 'BA Overshift Instrument & Geotechnical Shift Pagi 26/04/2026', '<p>PEKERJAAN HARI INI</p>\r\n\r\n<p>- QC Material Batu Buttress A P89</p>\r\n\r\n<p>- Monitoring All Area P89</p>\r\n\r\n<p>- Pengujian MC Filterpress</p>\r\n\r\n<p>- Pengujian Direct Shear</p>\r\n\r\n<p>- Pekerjaan Civil Laboratorium</p>\r\n\r\n<p>- Prepare Area CPTu</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>TEMUAN</p>\r\n\r\n<p>- Area spreading compartement A P89 menumpuk dan menyebabkan perbedaan elevasi yang signifikan</p>\r\n\r\n<p>- CLiq &amp; CPTe-IT belum ada progress dari tim IT</p>\r\n\r\n<p>- Hold pengujian kepadatan kompartemen<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>JOB PENDING</p>\r\n\r\n<p>- Gs CPTu.P23.CC.05 (20.00 - 20.50)</p>\r\n\r\n<p>- ATT CPTu.P23.CC.05 (7.00 - 7.50)</p>\r\n\r\n<p>- ATT CPTu.P23.CC.05 (16.00 - 16.50)</p>\r\n\r\n<p>- Gz CPTu.P89.CB.02 (06.00 - 06.50)</p>\r\n\r\n<p>- Gz CPTu.P89.CB.02 (14.00 - 14.50)</p>\r\n\r\n<p>- Gz CPTu.P89.CB.02 (18.00 - 18.50)</p>\r\n\r\n<p>- DS PTu.P23.CC.05 (11.00 - 11.50)</p>\r\n\r\n<p>- DS PTu.P23.CC.05 (16.00 - 16.50)</p>\r\n\r\n<p>- Pengambilan, foto, dan progress sampel Filterpress Line 1, Line 2, dan Titik Jatuh</p>\r\n\r\n<p>- Monitoring area operasi (spreading unloading CA P89, Titik jatuh line 2, All area spreading, dan kondisi material)</p>\r\n\r\n<p>- Qc material Buttress A P89</p>\r\n', '1777194919_FILTERPRESS (2).jpg', '2026-04-26 09:15:19', 'Instrument & Geotechnical', '2026-04-26 09:15:19', NULL, 'pending', NULL, NULL),
(322, 0, 2, 12, 'BA Overshift Instrument & Geotechnical Shift Pagi 28/04/2026', '<p>Kategori: Daily Instrument &amp; Geotechnical<br />\r\nTanggal: 2026-04-25 17:50:56</p>\r\n\r\n<p>PEKERJAAN HARI INI<br />\r\n- QC Material Batu Buttress A P89<br />\r\n- Preparasi Pengujian Hidrometer<br />\r\n- Monitoring All Area P89<br />\r\n- Pengujian MC Filterpress<br />\r\n- Pekerjaan Civil Laboratorium</p>\r\n\r\n<p>TEMUAN<br />\r\n- Area spreading compartement A P89 menumpuk dan menyebabkan perbedaan elevasi yang signifikan<br />\r\n- Material titik jatuh line 1 dan 2 awal shift lembek<br />\r\n- Slurry rendah di jam kedua<br />\r\n- CLiq &amp; CPTe-IT belum ada progress dari tim IT<br />\r\n- Hold pengujian kepadatan kompartemen</p>\r\n\r\n<p>JOB PENDING<br />\r\n- Pengujian Gz CPTu.P89.CB.02 ( 06.00 - 06.50, 14.00 - 14.50, 18.00 - 18.50)<br />\r\n- Pengambilan, foto, dan progress sampel Filterpress Line 1, Line 2, dan Titik Jatuh<br />\r\n- Monitoring area operasi (spreading unloading CA P89, Titik jatuh line 2, All area spreading, dan kondisi material)<br />\r\n- Qc material Buttress A P89<br />\r\n- Weekly Report</p>\r\n', '1777368206_FILTERPRESS (3).jpg', '2026-04-28 09:23:26', 'Instrument & Geotechnical', '2026-04-28 09:23:26', NULL, 'pending', NULL, NULL);
