(323, 0, 2, 12, 'BA Overshift Instrument & Geotechnical Shift Pagi 30/04/2026', '<p>PEKERJAAN HARI INI<br />\r\n- QC Material Batu Buttress A P89<br />\r\n- Preparasi Pengujian Hidrometer<br />\r\n- Monitoring All Area P89<br />\r\n- Pengujian MC Filterpress dan pembersihan cawan<br />\r\n- Pekerjaan Civil Laboratorium<br />\r\n- Preparasi area CPTu</p>\r\n\r\n<p>TEMUAN<br />\r\n- Area spreading compartement A P89 menumpuk dan menyebabkan perbedaan elevasi yang signifikan<br />\r\n- Slurry tinggi<br />\r\n- Hold pengujian kepadatan kompartemen</p>\r\n\r\n<p>JOB PENDING<br />\r\n- Pengambilan, foto, dan progress sampel Filterpress Line 1, Line 2, dan Titik Jatuh<br />\r\n- Monitoring area operasi (spreading unloading CA P89, Titik jatuh line 2, All area spreading, dan kondisi material)<br />\r\n- Qc material Buttress A P89<br />\r\n- RAB Bulan April 2026<br />\r\n- Pembersihan dan Persiapan CPTu Besok</p>\r\n', '1777542005_FILTERPRESS (4).jpg', '2026-04-30 09:40:05', 'Instrument & Geotechnical', '2026-04-30 09:40:05', NULL, 'pending', NULL, NULL),
(324, 0, 2, 12, 'BA Overshift Instrument & Geotechnical Shift Pagi 03/05/2026', '<p>PEKERJAAN HARI INI<br />\r\n- QC Material Batu Buttress A P89<br />\r\n- Pengujian Specific Gravity<br />\r\n- Monitoring All Area P89<br />\r\n- Pengujian MC Filterpress dan pembersihan cawan<br />\r\n- Pekerjaan Civil Laboratorium<br />\r\n- Pengujian CPTu<br />\r\n- Pengambilan sampel fly ash</p>\r\n\r\n<p>TEMUAN<br />\r\n- Line 2 Hold Operation due to Maintenance</p>\r\n\r\n<p>JOB PENDING<br />\r\n- Pengambilan, foto, dan progress sampel Filterpress Line 1, Line 2, dan Titik Jatuh<br />\r\n- Monitoring area operasi (spreading unloading CA P89, Titik jatuh line 2, All area spreading, dan kondisi material)<br />\r\n- Qc material Buttress A P89<br />\r\n- Pembersihan Konus<br />\r\n- Pengolahan data CPTu<br />\r\n- Pengujian Lab Drytail Mei 2026<br />\r\n- Pengujian index prop fly sh</p>\r\n', '1777800379_FILTERPRESS (5).jpg', '2026-05-03 09:26:19', 'Instrument & Geotechnical', '2026-05-03 09:26:19', NULL, 'pending', NULL, NULL),
(325, 0, 2, 12, 'BA Overshift  Shift Pagi 04/05/2026', '<p>PEKERJAAN HARI INI<br />\r\n- QC Material Batu Buttress A P89<br />\r\n- Pengujian Specific Gravity&nbsp;<br />\r\n- Monitoring All Area P89<br />\r\n- Pengujian MC Filterpress&nbsp;<br />\r\n- Angkur CPTU<br />\r\n- Pembersihan Push Pull CPTu</p>\r\n\r\n<p>TEMUAN<br />\r\n- Retakan di Buttress belum dilakukan, exa masih fokus fill boulder untuk area sump yang curam yang menjadi salah satu penyebab retakan tersebut.<br />\r\n- WO perbaikan lampu dah dibuat<br />\r\n- IM on progress translate</p>\r\n\r\n<p>JOB PENDING<br />\r\n- Pengambilan, foto, dan progress sampel Filterpress Line 1, Line 2, dan Titik Jatuh<br />\r\n- Monitoring area operasi (spreading unloading CA P89, Titik jatuh line 2, All area spreading, dan kondisi material)<br />\r\n- Qc material Buttress A P89<br />\r\n-&nbsp;Pengolahan data CPTu<br />\r\n- Pengujian Lab Drytail Mei 2026 (cek di papan)<br />\r\n- Revisi Layer yang ada di Monthly (+ pembahasannya)<br />\r\n- Revisi layer (rubah warna dan penjelasan layer), ada di pc<br />\r\n&nbsp;</p>\r\n', '1777887382_FILTERPRESS (6).jpg', '2026-05-04 09:36:22', '', '2026-05-04 09:36:22', NULL, 'pending', NULL, NULL),
(326, 0, 2, 12, 'BA Overshift Instrument & Geotechnical Shift Pagi 18/05/2026', '<p>Pekerjaan Hari Ini<br />\r\n- Pengujian sandcone Kompartemen B P89<br />\r\n- Konstruksi Buttress B P89<br />\r\n- Monitoring lereng<br />\r\n- Pekerjaan Lab<br />\r\n- Pengambilan Sampel CPTu</p>\r\n\r\n<p>Job Pending<br />\r\n- Extrude sampel CPTu<br />\r\n- Perbaikan buttress B P89<br />\r\n- Filterpress Line 1 dan Line 2<br />\r\n- Monitoring area operasi</p>\r\n', '1779095226_WhatsApp Image 2026-05-18 at 18.05.31.jpeg', '2026-05-18 09:07:06', 'Instrument & Geotechnical', '2026-05-18 09:07:06', NULL, 'pending', NULL, NULL);
